INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (1, 'HELPERS', '["تقديم الدعم المساعد في مختلف المهام اليدوية واللوجستية.","تحميل وتفريغ الشحنات والمواد والمعدات يدوياً.","تنظيف وترتيب مواقع العمل لضمان بيئة عمل آمنة.","مساعدة الفنيين في تحضير الأدوات والمواد اللازمة للمهام.","نقل الأثاث والمعدات المكتبية بين الأقسام عند الحاجة.","الالتزام الصارم بتعليمات السلامة والصحة المهنية.","إبلاغ المشرفين فوراً عن أي أعطال أو مخاطر في الموقع.","المساهمة في تجميع وتصنيف المخلفات للتخلص منها بشكل آمن.","مساعدة السائقين وتوجيههم أثناء ركن الشاحنات في المستودعات.","فرز المواد وتصنيفها يدوياً قبل عمليات التخزين.","التعامل بحذر شديد مع المواد القابلة للكسر أو التلف.","تنفيذ أي مهام يدوية إضافية يُكلف بها من قبل الإدارة المباشرة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (2, 'أخصائي إدارة مشاريع', '["التخطيط للمشاريع ومتابعة تنفيذها لضمان تسليمها في الوقت المحدد.","تحديد الموارد البشرية والمادية والميزانية التقديرية لكل مشروع.","إدارة المخاطر المتوقعة ووضع خطط استباقية لمعالجتها.","عقد اجتماعات دورية مع فريق العمل لمتابعة نسب الإنجاز.","إعداد التقارير النهائية وإغلاق المشروع وتقييم النتائج.","تقييم أداء فريق المشروع وتوزيع المهام بناءً على الكفاءة.","التفاوض مع الموردين والمقاولين لضمان الالتزام بمتطلبات المشروع.","استخدام برامج إدارة المشاريع (مثل MS Project أو Jira) لتتبع التقدم.","حل النزاعات وتذليل العقبات التي قد تعرقل سير العمل.","ضمان توافق مخرجات المشروع مع معايير الجودة المعتمدة.","تقديم عروض توضيحية للإدارة العليا حول المعالم الرئيسية للمشروع.","توثيق الدروس المستفادة للاستعانة بها في المشاريع المستقبلية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (3, 'أخصائي إداري', '["تنظيم العمليات الإدارية الداخلية وتطوير نماذج العمل.","الإشراف على توفير القرطاسية والأثاث والمستلزمات المكتبية.","تنسيق المواعيد والاجتماعات الإدارية الكبرى داخل المنشأة.","متابعة عقود الصيانة والنظافة والخدمات العامة للمكاتب.","تطوير الأرشفة الإلكترونية للملفات الإدارية لسهولة الاسترجاع.","إعداد المراسلات والتعاميم الإدارية الداخلية وتوزيعها.","استقبال طلبات الإجازات والمغادرات الإدارية وتوجيهها للاعتماد.","مراجعة الفواتير الخاصة بالخدمات الإدارية قبل تمريرها للمالية.","الإشراف على جاهزية قاعات الاجتماعات والتدريب.","تحديث قواعد بيانات الموردين الخاصين بالخدمات المكتبية.","المساهمة في تنظيم الفعاليات الداخلية للموظفين.","ضمان الالتزام بالسياسات الإدارية وتوجيه الموظفين الجدد."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (4, 'أخصائي استشارات أعمال', '["تقديم نصائح استراتيجية لتحسين أداء الشركة ونموها.","إجراء دراسات الجدوى الاقتصادية للمشاريع الجديدة.","تحليل المنافسين في السوق وتحديد نقاط التميز للشركة.","تقديم خطط إعادة الهيكلة للشركات المتعثرة.","تطوير نماذج أعمال مبتكرة لزيادة مصادر الدخل.","تحليل البيانات المالية والتشغيلية لاكتشاف فرص تقليل التكاليف.","تقييم الهيكل التنظيمي وتقديم توصيات لرفع الكفاءة الإدارية.","تصميم مؤشرات الأداء الرئيسية (KPIs) لقياس نجاح الاستراتيجيات.","توجيه الإدارة العليا في قرارات الاندماج أو الاستحواذ.","إعداد تقارير تحليلية مفصلة حول اتجاهات السوق المستقبلية.","قيادة ورش عمل عصف ذهني مع الإدارات لتوليد أفكار تطويرية.","متابعة تنفيذ التوصيات الاستشارية لضمان تحقيق النتائج المرجوة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (5, 'أخصائي اعلامي', '["إدارة المحتوى الإعلامي والتواصل مع الجهات الصحفية.","صياغة البيانات الصحفية والأخبار الخاصة بالمنشأة.","تنظيم اللقاءات التلفزيونية والإذاعية لمسؤولي الشركة.","رصد الأخبار المنشورة عن الشركة في الصحف والمواقع.","إدارة الأزمات الإعلامية والرد على الشائعات.","تطوير استراتيجيات العلاقات الإعلامية لتعزيز الحضور الإيجابي.","بناء وتحديث قاعدة بيانات محدثة للإعلاميين والصحفيين.","التنسيق لتغطية الفعاليات والمؤتمرات الخاصة بالشركة.","إعداد المواد الإعلامية (Press Kits) لتوزيعها على الصحافة.","كتابة مقالات الرأي والمقابلات الخاصة بالمدراء التنفيذيين.","قياس الأثر الإعلامي للحملات الصحفية وتقديم تقارير التقييم.","توجيه مسؤولي الشركة حول كيفية التعامل المثالي مع وسائل الإعلام."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (6, 'أخصائي التزام', '["التأكد من مطابقة أعمال المنشأة للقوانين واللوائح التنظيمية.","مراقبة العمليات المالية لمنع غسيل الأموال أو الاحتيال.","تحديث سياسات المنشأة وفقاً للتعديلات التشريعية الحكومية.","إجراء التدقيق الدوري على سجلات الامتثال في الأقسام.","تقديم تقارير دورية للجهات الرقابية الخارجية.","تصميم وتنفيذ برامج تدريبية للموظفين حول سياسات الامتثال.","التحقيق في البلاغات الداخلية المتعلقة بانتهاكات السياسات.","تقييم مخاطر عدم الامتثال في المشاريع والعقود الجديدة.","تطوير مدونة السلوك الوظيفي ومراقبة الالتزام بها.","مراجعة الحملات التسويقية للتأكد من توافقها مع القوانين.","الاحتفاظ بسجلات دقيقة لجميع عمليات التدقيق والمراجعة.","تقديم الاستشارات للإدارات المختلفة لتجنب المخالفات التنظيمية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (7, 'أخصائي تحليل مالي', '["تحليل البيانات المالية لتقديم توقعات ودعم اتخاذ القرار.","دراسة القوائم المالية والميزانيات العمومية للشركة.","تقييم ربحية المنتجات والخدمات المختلفة التي تقدمها المنشأة.","رصد التغيرات في التدفقات النقدية وتحليل أسبابها.","تقديم توصيات للاستثمار في أدوات مالية جديدة.","إعداد نماذج مالية معقدة لتقييم السيناريوهات المستقبلية.","مقارنة الأداء المالي الفعلي بالميزانيات التقديرية المعتمدة.","تحليل نسب السيولة والمديونية والعائد على الاستثمار.","تحديد مجالات الهدر المالي وتقديم حلول لترشيد النفقات.","إعداد تقارير مالية دورية مبسطة لعرضها على الإدارة التنفيذية.","متابعة المؤشرات الاقتصادية العامة وتأثيرها على أعمال الشركة.","المشاركة في تسعير المنتجات الجديدة بناءً على تحليل التكلفة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (8, 'أخصائي تدريب وتطوير موارد بشرية', '["تصميم برامج تدريبية لرفع كفاءة الموظفين بناءً على الاحتياجات.","تحليل الفجوات المهارية لدى الكوادر البشرية في مختلف الأقسام.","التنسيق مع مراكز التدريب والمدربين الخارجيين لتنفيذ الورش.","قياس أثر التدريب على أداء الموظفين الفعلي بعد الدورات.","بناء خطط المسارات الوظيفية (Career Paths) للمتميزين.","إدارة ميزانية التدريب السنوية والتأكد من استغلالها الأمثل.","تطوير مواد تدريبية داخلية وعروض تقديمية تفاعلية.","إدارة المنصات الإلكترونية للتعليم عن بعد (LMS) الخاصة بالشركة.","تصميم برامج تهيئة وتوجيه (Onboarding) للموظفين الجدد.","تنظيم ورش عمل لتطوير المهارات القيادية للإدارة الوسطى.","إجراء استبيانات الرضا عن البرامج التدريبية وتحليل نتائجها.","الاحتفاظ بسجلات دقيقة لتدريب الموظفين والشهادات الحاصلين عليها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (9, 'أخصائي تسويق', '["إعداد الخطط التسويقية والترويج للمنتجات والخدمات.","إدارة ميزانية الإعلانات على المنصات المختلفة.","دراسة سلوك المستهلك وتحديد الفئات المستهدفة بدقة.","ابتكار أفكار لحملات إعلانية موسمية تزيد من الولاء للعلامة.","التنسيق مع وكالات الدعاية والإعلان لتنفيذ التصاميم.","إدارة العلاقات مع المؤثرين لترويج العلامة.","كتابة وتطوير المحتوى التسويقي للموقع الإلكتروني والنشرات.","تحليل العائد على الاستثمار للحملات الإعلانية.","مراقبة سمعة الشركة التسويقية والرد على التعليقات.","متابعة أحدث التقنيات والاتجاهات في التسويق الرقمي.","التعاون مع المبيعات لضمان مواءمة الرسائل الترويجية مع أهداف البيع.","تنظيم ورعاية الأحداث الترويجية لتعزيز الانتشار المحلي."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (10, 'أخصائي تطوير إداري', '["تحسين الهياكل التنظيمية وتحديث إجراءات العمل.","دراسة وتطوير تدفق العمل (Workflow) لتقليل البيروقراطية.","صياغة وتحديث أدلة السياسات والإجراءات لجميع الأقسام.","تحليل المشكلات التنظيمية واقتراح حلول لرفع الكفاءة.","مواءمة الأهداف الإدارية مع الاستراتيجية العامة للمنشأة.","إجراء دراسات قياس عبء العمل لتحديد الاحتياجات من القوى العاملة.","تصميم النماذج الإدارية الموحدة وتعميمها على الإدارات.","تقييم بيئة العمل الداخلية واقتراح مبادرات لرفع رضا الموظفين.","إدارة برامج التغيير المؤسسي لضمان انتقال سلس للأنظمة الجديدة.","تحديث التوصيف الوظيفي باستمرار ليواكب التغييرات التشغيلية.","عقد مقارنات معيارية (Benchmarking) مع أفضل الممارسات في السوق.","تدريب مديري الأقسام على أساليب الإدارة الحديثة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (11, 'أخصائي توظيف', '["إدارة عمليات استقطاب واختيار الكفاءات البشرية.","صياغة إعلانات الوظائف ونشرها في القنوات المناسبة.","إجراء المقابلات السلوكية والفنية للمرشحين.","بناء قاعدة بيانات للمواهب المتميزة للاحتياجات المستقبلية.","إنهاء إجراءات التعاقد والترحيب بالموظفين الجدد.","فحص السير الذاتية وتصفية المرشحين بناءً على متطلبات الوظيفة.","إجراء الفحوصات المرجعية (Reference Checks) للمرشحين النهائيين.","التفاوض على العروض الوظيفية والرواتب مع المرشحين.","المشاركة في معارض التوظيف بالجامعات لجذب الخريجين الجدد.","قياس معدل دوران العمالة وتحليل أسباب الاستقالات.","تطوير استراتيجيات تحسين العلامة التجارية لجهة العمل (Employer Branding).","التأكد من التزام عملية التوظيف بقوانين العمل وتكافؤ الفرص."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (12, 'أخصائي جودة', '["مراقبة تطبيق معايير الجودة والتميز المؤسسي.","إجراء التدقيق الداخلي على الأقسام للتأكد من الالتزام بالمعايير.","تحليل مسببات الأخطاء ووضع خطط لتحسين الجودة.","متابعة مؤشرات الأداء (KPIs) المتعلقة بالجودة والإنتاج.","تدريب الموظفين على مفاهيم الجودة الشاملة وأدواتها.","تحديث أدلة وإجراءات الجودة استعداداً للحصول على شهادات الأيزو.","استقبال شكاوى الجودة من العملاء والتحقيق فيها بشكل منهجي.","استخدام أدوات مثل (Six Sigma) لتقليل نسب العيوب في العمليات.","إعداد تقارير دورية تبرز حالات عدم المطابقة والتحسينات المطلوبة.","مراجعة واختبار عينات من المنتجات أو الخدمات بشكل عشوائي.","إدارة نظام الإجراءات التصحيحية والوقائية (CAPA).","تعزيز ثقافة التحسين المستمر (Kaizen) بين جميع العاملين."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (13, 'أخصائي خدمة عملاء', '["معالجة المشكلات المعقدة لضمان رضا العملاء.","تحليل شكاوى العملاء المتكررة واقتراح حلول جذرية لها.","تدريب الموظفين الجدد على مهارات التواصل الفعال.","إدارة حسابات كبار العملاء (Key Accounts) وتقديم دعم خاص لهم.","إعداد تقارير دورية عن مستوى رضا العملاء للإدارة.","الرد السريع والاحترافي على استفسارات العملاء عبر الهاتف والبريد.","تسجيل جميع تفاعلات العملاء بدقة في نظام إدارة العلاقات (CRM).","تصعيد الحالات التقنية أو المالية للإدارات المعنية ومتابعتها.","تنفيذ استبيانات الرضا لقياس مدى سعادة العميل بالخدمة.","إجراء مكالمات متابعة للتأكد من حل المشكلة بشكل نهائي.","تقديم مقترحات لتطوير المنتجات بناءً على ملاحظات الزبائن.","الاحتفاظ بهدوء ومهنية عالية عند التعامل مع العملاء المنفعلين."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (14, 'أخصائي عقود', '["صياغة ومراجعة العقود القانونية والتجارية وضمان حقوق الشركة.","التفاوض مع الموردين والعملاء على بنود العقد المالية والقانونية.","أرشفة العقود الأصلية وضمان أمانها وسريتها.","فض النزاعات التعاقدية من خلال التفسير الصحيح للبنود.","تقييم المخاطر القانونية المرتبطة ببعض العقود طويلة الأجل.","تطوير نماذج قياسية للعقود المتكررة لتسريع الإجراءات.","التأكد من اكتمال كافة التوقيعات والأختام الرسمية قبل بدء التنفيذ.","إنشاء نظام لتتبع تواريخ الانتهاء والتجديد التلقائي للعقود.","التنسيق المباشر مع المستشارين القانونيين الخارجيين عند الحاجة.","مراجعة شروط الدفع والجزاءات التأخيرية في عقود المقاولات.","إعداد ملاحق العقود في حالة تغيير المواصفات أو النطاق الزمني.","تدريب الموظفين المعنيين على كيفية الالتزام بالبنود التعاقدية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (15, 'أخصائي علاقات عامة', '["بناء وتحسين الصورة الذهنية للمنشأة أمام الجمهور.","بناء علاقات قوية مع الجهات الحكومية والمجتمع المحلي.","إدارة برامج المسؤولية الاجتماعية (CSR) للشركة.","استقبال الوفود الرسمية وتنظيم زياراتهم للمنشأة.","الإشراف على إصدار النشرات الداخلية للموظفين.","تنظيم المؤتمرات الصحفية وحفلات إطلاق المنتجات الجديدة.","تمثيل الشركة في المعارض والفعاليات والندوات الخارجية.","الرد على الاستفسارات المجتمعية وبناء قنوات حوار فعالة.","إعداد الهدايا التذكارية والمواد الدعائية لضيوف الشركة.","العمل كوسيط بين الشركة والمجتمع المحيط بها لتعزيز الثقة.","كتابة الخطابات والكلمات الرسمية لمديري الشركة في المناسبات.","إدارة الأزمات المجتمعية التي قد تؤثر على سمعة العلامة التجارية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (16, 'أخصائي علوم حاسب آلي', '["تطوير البرمجيات وإدارة البنية التحتية التقنية.","تصميم وتحليل النظم البرمجية المعقدة للشركة.","كتابة الأكواد البرمجية واختبارها قبل الإطلاق الفعلي.","تقديم استشارات فنية لاختيار الأجهزة والبرمجيات المناسبة.","إدارة قواعد البيانات وضمان كفاءة استرجاع المعلومات.","تطوير وتحديث خوارزميات لتحسين أداء الأنظمة التشغيلية.","مراقبة أمن الشبكات وحماية البيانات من الاختراقات (Cybersecurity).","إنشاء وتوثيق واجهات برمجة التطبيقات (APIs) لربط الأنظمة.","إصلاح الثغرات البرمجية (Debugging) وتقديم تحديثات دورية.","تحسين واجهات المستخدم (UI/UX) لضمان سهولة استخدام النظم.","إعداد بيئات الخوادم السحابية وإدارة الاستضافة والموارد.","تدريب الفرق التقنية الأقل خبرة على أحدث لغات البرمجة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (17, 'أخصائي عمليات موارد بشرية', '["إدارة الإجراءات اليومية مثل الرواتب والإجازات.","متابعة التأمين الطبي والاجتماعي للموظفين وعائلاتهم.","معالجة القروض والبدلات والمستقطعات المالية للموظفين.","إصدار خطابات التعريف وشهادات الخبرة.","إدارة نهاية الخدمة وتسوية مستحقات الموظفين الراحلين.","إدخال وتحديث البيانات الوظيفية على نظام (ERP) للموارد البشرية.","معالجة طلبات النقل والترقيات واعتمادها وفق الصلاحيات.","أرشفة المستندات والوثائق الثبوتية بملفات الموظفين السرية.","متابعة تجديد الإقامات وتصاريح العمل للعمالة الوافدة.","إعداد تقارير مسوغات التعيين للموظفين الجدد.","حل الاستفسارات اليومية للموظفين بشأن سياسات الحضور والغياب.","تحديث هياكل الرواتب بالتنسيق مع قسم المالية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (18, 'أخصائي قانوني', '["تقديم المشورة القانونية والتمثيل في القضايا والمنازعات.","صياغة المذكرات القانونية والرد على الدعاوى القضائية.","تمثيل الشركة أمام المحاكم والجهات الحكومية المختصة.","التحقيق في المخالفات العمالية واتخاذ الإجراءات التأديبية.","شرح التبعات القانونية للقرارات الإدارية الكبرى.","مراجعة لوائح العمل الداخلية واعتمادها من وزارة العمل.","صياغة الإنذارات القانونية للموردين أو العملاء المتعثرين.","تسجيل براءات الاختراع والعلامات التجارية الخاصة بالمنشأة.","تقديم الدعم القانوني لقسم المشتريات في المناقصات الكبرى.","حفظ وتحديث الأرشيف القانوني لكافة الأحكام والقضايا.","توعية مديري الإدارات بالتشريعات والقوانين الجديدة المستحدثة.","متابعة إجراءات التصفية أو الإفلاس في حال لزم الأمر."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (19, 'أخصائي مبيعات', '["تحقيق الأهداف البيعية وتوسيع قاعدة العملاء.","إجراء العروض التقديمية (Presentations) للعملاء المحتملين.","إغلاق الصفقات والتفاوض على العقود البيعية الكبرى.","متابعة التحصيل المالي من العملاء بعد عملية البيع.","إعداد تقارير دورية عن حجم المبيعات المتوقعة.","تحليل بيانات السوق لتحديد الفجوات البيعية وفرص النمو.","بناء شبكة علاقات قوية مع صناع القرار في الشركات المستهدفة.","تحديث بيانات العملاء المحتملين (Leads) في نظام المبيعات.","دراسة تسعيرة المنافسين لتقديم عروض أكثر جاذبية للعميل.","المشاركة الفعالة في المعارض التجارية لفتح قنوات بيع جديدة.","تطوير خطط احتفاظ بالعملاء (Retention) لزيادة المبيعات المكررة.","حل مشكلات ما بعد البيع لضمان استمرار العلاقة التجارية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (20, 'أخصائي مراقبة مخزون', '["متابعة حركة الأصناف لضمان توفرها ومنع الهدر.","تحليل معدل دوران المخزون وتحديد الأصناف سريعة الحركة.","وضع حد أدنى وحد أعلى (Safety Stock) لكل صنف.","إعداد تقارير عن الأصناف الراكدة أو التي قاربت على الانتهاء.","التأكد من نظامية القيود المخزنية على النظام الإلكتروني.","تنظيم وإدارة عمليات الجرد الدوري والمفاجئ للمستودعات.","التحقيق في الفروقات بين الرصيد الفعلي والرصيد الدفتري.","التنسيق مع قسم المشتريات لتجنب نقص المواد الاستراتيجية.","تقييم كفاءة المساحات التخزينية واقتراح طرق لتنظيمها.","متابعة مرتجعات المخزون وتحديد أسبابها ومعالجتها.","الإشراف على إتلاف المواد التالفة وفق الإجراءات المعتمدة.","تطبيق معايير رقابة الجودة على المواد أثناء تخزينها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (21, 'أخصائي مراقبة موارد بشرية', '["مراقبة الالتزام بسياسات العمل وساعات الدوام.","سحب تقارير البصمة اليومية وتحليل الانحرافات.","التأكد من التزام الموظفين بالزي الرسمي أو معايير المظهر.","مراقبة العمل الإضافي والتأكد من مبرراته الفعلية.","القيام بجولات تفتيشية مفاجئة على أماكن العمل.","تدقيق مسوغات منح الإجازات المرضية والاضطرارية.","رصد المخالفات السلوكية وإعداد تقارير لرفعها للجنة التحقيق.","مراجعة صلاحيات الوصول الإلكتروني للموظفين المنهي خدماتهم.","إصدار التعاميم التذكيرية بلائحة الانضباط الوظيفي.","قياس معدلات الغياب والـتأخير ووضع خطط لتقليلها.","مراقبة استغلال الموظفين لموارد الشركة (سيارات، أجهزة).","تقديم المشورة للإدارة حول كيفية تحسين بيئة الانضباط العام."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (22, 'أخصائي مستودعات', '["تنظيم مساحات التخزين وإدارة لوجستيات التوريد.","تصميم خريطة المستودع لسهولة الوصول للأصناف (Layout).","الإشراف على فرق العمل من عمال وسائقين داخل المستودع.","تطبيق معايير السلامة المهنية ومنع الحرائق في مناطق التخزين.","متابعة حالة المعدات داخل المستودع (رافعات، أرفف).","استلام وتدقيق كميات وجودة البضائع الواردة للمستودع.","تطبيق نظام إدارة المستودعات (WMS) لضمان تتبع الشحنات.","تنظيم عمليات التعبئة والتغليف للبضائع الصادرة.","التنسيق مع شركات النقل والشحن لضمان خروج البضائع في موعدها.","تقليل زمن معالجة الطلبات داخل المستودع لرفع الكفاءة.","إجراء الفحوصات الدورية على أنظمة التبريد والتهوية للتخزين الحساس.","تحليل التكاليف اللوجستية واقتراح طرق لتخفيضها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (23, 'أخصائي مشاريع', '["إدارة الجوانب التشغيلية والفنية لمشاريع محددة.","التأكد من مطابقة التنفيذ الميداني للمواصفات الفنية المعتمدة.","التنسيق مع المقاولين والموردين لضمان تدفق المواد للمشروع.","مراقبة استهلاك الموارد المخصصة للمشروع ومنع الهدر.","توثيق كافة مراحل المشروع بالصور والتقارير الفنية المكتوبة.","تحليل جداول الكميات والتسعير مقارنة بالواقع الميداني.","تحديث برامج التخطيط الزمني وعكس نسب الإنجاز الفعلية.","استلام الأعمال المرحلية من المقاولين ورفع المستخلصات.","تحديد المخاطر الفنية أثناء التنفيذ وإيجاد حلول هندسية سريعة.","التنسيق مع الدوائر الحكومية لاستخراج تصاريح العمل اللازمة.","تنظيم اجتماعات الموقع الأسبوعية وتسجيل المحاضر.","التأكد من توفر جميع شروط السلامة للعمال في بيئة المشروع."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (24, 'أخصائي مشتريات', '["اختيار الموردين والتفاوض على أفضل الأسعار والجودة.","بناء علاقات استراتيجية مع كبار الموردين المحليين والدوليين.","مراجعة طلبات الشراء الواردة من الأقسام والتأكد من ضرورتها.","التنسيق مع الحسابات لضمان سداد مستحقات الموردين في موعدها.","البحث المستمر عن بدائل للمواد الخام لتقليل التكاليف.","إعداد وطرح كراسات الشروط والمناقصات للخدمات الكبرى.","تحليل وتقييم عروض الأسعار واختيار الأنسب فنياً ومالياً.","إصدار أوامر الشراء ومتابعة جدول التسليم بدقة.","معالجة مشاكل البضائع التالفة أو المرتجعة مع الموردين.","تقييم أداء الموردين دورياً واستبعاد المتعثرين منهم.","دراسة اتجاهات الأسعار العالمية للمواد لتحديد أوقات الشراء المثلى.","التأكد من مطابقة جميع المشتريات للوائح الجودة الداخلية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (25, 'أخصائي مكتبات', '["تنظيم وتصنيف المصادر المعلوماتية وتسهيل الوصول إليها.","إدارة عمليات الإعارة الداخلية والخارجية للكتب.","فهرسة الكتب الجديدة وتجليد المراجع التالفة.","مساعدة الباحثين في الحصول على المراجع الرقمية والورقية.","تنظيم فعاليات ثقافية أو معارض كتب داخل المنشأة.","تحديث قاعدة البيانات الإلكترونية لفهرس المكتبة.","التواصل مع دور النشر لاقتناء أحدث الإصدارات والمراجع.","توفير مصادر المعلومات الإلكترونية والاشتراك في قواعد البيانات.","جرد محتويات المكتبة بشكل دوري لتعويض الفاقد والتالف.","إرشاد الزوار حول كيفية استخدام أدوات البحث الذكية بالمكتبة.","حفظ وأرشفة الدوريات والصحف والمجلات بشكل منظم.","توفير بيئة هادئة ومناسبة للمطالعة والبحث داخل قاعة المكتبة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (26, 'أخصائي موازنة مالية', '["إعداد الميزانيات التقديرية ومتابعة الإنفاق الفعلي.","مقارنة المصاريف الفعلية مع المخطط لها بشكل شهري.","توزيع الميزانيات على الأقسام بناءً على خطط العمل.","التنبيه في حالة تجاوز الأقسام للميزانية المخصصة لها.","المساهمة في إعداد التقارير المالية السنوية للمساهمين.","دراسة طلبات التمويل الإضافية الواردة من الإدارات.","تحليل الانحرافات بين الميزانية التقديرية والفعلية ومعالجة أسبابها.","إعداد تنبؤات التدفق النقدي لضمان توفر السيولة الكافية.","تقديم المشورة للإدارة بشأن أولويات الإنفاق ووقف الهدر.","تحديث نماذج إعداد الموازنة لتسهيل إدخال البيانات على الإدارات.","الاحتفاظ بسجلات دقيقة لكافة المناقلات المالية بين بنود الميزانية.","تحليل أثر المشاريع الرأسمالية الجديدة على الميزانية العامة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (27, 'أمين صندوق', '["استلام النقدية وصرفها وتوثيق الحركات المالية اليومية.","إيداع النقدية في البنك بشكل يومي ومطابقة الكشوف.","صرف الرواتب أو البدلات النقدية المعتمدة.","الاحتفاظ بسجلات دقيقة لكل عملية دفع أو قبض (إيصالات).","مسؤولية حماية الخزنة والعهدة المالية من السرقة أو الضياع.","إعداد كشف يومي بحركة الخزينة وإرساله للإدارة المالية.","صرف السلف المالية المؤقتة ومتابعة تسويتها بالفواتير.","التأكد من صحة التواقيع والاعتمادات على أذونات الصرف.","التعامل مع أجهزة عد النقدية وكشف العملات المزورة.","الجرد اليومي للخزينة ومطابقتها مع الرصيد الدفتري.","التنسيق مع شركات نقل الأموال لضمان أمان التحويلات الكبرى.","الالتزام بسرية الأرصدة والعمليات المالية الخاصة بالمنشأة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (28, 'أمين مخزن', '["استلام وتسليم البضائع والاحتفاظ بسجلات دقيقة للعهدة.","التأكد من سلامة التغليف للبضائع عند استلامها من المورد.","صرف المواد للأقسام بناءً على أذونات صرف معتمدة.","ترتيب البضائع بنظام (FIFO) الصادر أولاً يدخل أولاً.","الحفاظ على نظافة وتنظيم المخزن بشكل مستمر.","تحديث بطاقات الصنف (Bin Cards) بعد كل عملية إدخال أو إخراج.","تجهيز الطلبيات الصادرة وتغليفها بشكل آمن قبل النقل.","عزل المواد التالفة أو منتهية الصلاحية في منطقة مخصصة.","مراقبة درجات الحرارة والرطوبة في مخازن المواد الحساسة.","التعاون المستمر مع لجان الجرد الداخلي والخارجي.","استخدام الماسح الضوئي (Barcode Scanner) لتسجيل الحركات المخزنية.","إبلاغ الإدارة فور وصول أي صنف إلى حد الطلب (Reorder Point)."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (29, 'أمين مستودع فني', '["إدارة قطع الغيار والمعدات الفنية وتوثيق حركتها.","التأكد من ظروف تخزين القطع الحساسة (حرارة، رطوبة).","صرف الأدوات الفنية للفنيين ومتابعة استردادها (العهدة المستديمة).","ترميز القطع الفنية (Coding) لسهولة البحث عنها في النظام.","إبلاغ قسم المشتريات عند نقص قطع غيار الآلات الحيوية.","تصنيف القطع بناءً على نوع الماكينة وموديلها لمنع التداخل.","تغليف القطع الإلكترونية بأكياس مضادة للشحنات للحفاظ عليها.","إجراء صيانة أولية للأدوات المعادة قبل تخزينها مرة أخرى.","متابعة تواريخ انتهاء الصلاحية للمواد الكيميائية والزيوت.","التخلص من القطع الخردة بالطرق الآمنة المعتمدة هندسياً.","مراجعة كتالوجات المصنعين لمعرفة البدائل للقطع غير المتوفرة.","تسجيل وتسوية القطع التالفة أثناء التركيب بأذونات إتلاف رسمية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (30, 'إداري', '["القيام بالمهام المكتبية والتنظيمية العامة.","استقبال وتوجيه المراجعين والزوار إلى الأقسام المعنية.","تنظيم الملفات الورقية والإلكترونية الخاصة بالقسم.","كتابة المسودات والخطابات الإدارية البسيطة.","متابعة حضور وانصراف الموظفين داخل القسم المعني.","استلام البريد الوارد وتوزيعه على مكاتب القسم.","الرد على الاتصالات الهاتفية وتحويلها للشخص المناسب.","تجهيز غرف الاجتماعات بالضيافة وأدوات العرض.","متابعة طلبات الصيانة لأجهزة الحاسب أو الطابعات في المكتب.","تصوير المستندات وعمل نسخ احتياطية للأوراق المهمة.","توفير الاحتياجات من الأحبار والقرطاسية لموظفي الإدارة.","مساعدة المدير المباشر في أي مهام تنظيمية طارئة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (31, 'إداري عام', '["الإشراف على الشؤون الإدارية المتنوعة داخل الأقسام.","التنسيق بين الإدارة العليا والأقسام التشغيلية المختلفة.","متابعة تنفيذ القرارات الإدارية الصادرة من مجلس الإدارة.","مراجعة العقود والاتفاقيات الإدارية البسيطة قبل اعتمادها.","حل النزاعات الإدارية البسيطة التي قد تنشأ بين الموظفين.","متابعة التراخيص الحكومية للمنشأة وتجديدها في الوقت المحدد.","إدارة ملفات التأمين على مباني وسيارات المنشأة.","الإشراف على موظفي الاستقبال والأمن وعمال النظافة.","تطوير أدلة الإجراءات الداخلية لضمان توحيد العمل الإداري.","إدارة أسطول السيارات ومتابعة صيانتها وتوزيعها.","مراجعة وتدقيق مستحقات شركات الخدمات اللوجستية.","إعداد تقرير شهري شامل عن مستوى الأداء الإداري والمصروفات."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (32, 'إداري مواقع إلكترونية', '["إدارة المحتوى وتحديث المعلومات على المنصات الرقمية.","مراقبة أداء الموقع وسرعة استجابته للمستخدمين.","التأكد من حماية الموقع من الهجمات الإلكترونية والفيروسات.","التنسيق مع المصممين لتحديث الواجهات الرسومية للموقع.","متابعة تجديد النطاقات (Domains) وشهادات الأمان (SSL).","تحليل إحصائيات زوار الموقع باستخدام Google Analytics.","تحسين محركات البحث (SEO) لزيادة ظهور الموقع.","رفع المنتجات الجديدة، الأسعار، والصور على المتجر الإلكتروني.","إصلاح الروابط المعطوبة وتحسين تجربة المستخدم (UX).","التنسيق مع شركات الاستضافة لحل مشاكل توقف الموقع (Downtime).","الرد على تعليقات المستخدمين ورسائلهم عبر الموقع.","إجراء نسخ احتياطي (Backups) لقواعد بيانات الموقع بانتظام."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (33, 'اختصاصي تسويق', '["تنفيذ الحملات الترويجية الموجهة ودراسة سلوك المستهلك.","تحليل بيانات الحملات السابقة لمعرفة أكثر القنوات فعالية.","تقسيم الجمهور المستهدف (Segmentation) لتخصيص الرسائل التسويقية.","متابعة اتجاهات السوق (Trends) وتطبيقها في المحتوى التسويقي.","إجراء استطلاعات رأي لمعرفة مدى قبول المنتجات الجديدة.","تصميم استراتيجيات تسويق عبر البريد الإلكتروني (Email Marketing).","التنسيق مع إدارة المبيعات لتقديم عروض ترويجية حصرية.","مراقبة أداء المنافسين وتحليل نقاط القوة والضعف لديهم.","كتابة نصوص إعلانية جذابة (Copywriting) للمنصات المختلفة.","توزيع المواد الإعلانية المطبوعة في نقاط البيع الاستراتيجية.","إدارة ميزانيات الإعلانات المدفوعة على السوشيال ميديا.","تنظيم الفعاليات الترويجية وتوزيع العينات المجانية للجمهور."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (34, 'اخصائى مشتريات', '["تأمين طلبات الشراء والمواد اللازمة للتشغيل.","إصدار أوامر الشراء (Purchase Orders) عبر النظام.","متابعة وصول البضائع للمستودع في المواعيد المحددة.","التأكد من مطابقة البضائع المستلمة لأمر الشراء من حيث المواصفات.","تحديث قاعدة بيانات الموردين وتقييمهم سنوياً.","المقارنة بين عروض الأسعار لاختيار الأنسب من حيث التكلفة والجودة.","التفاوض على شروط الدفع وتسهيلات الائتمان مع الموردين.","معالجة أوامر الشراء المستعجلة لضمان عدم توقف العمليات.","حفظ وتوثيق الفواتير وعروض الأسعار في أرشيف القسم.","إدارة عمليات إرجاع البضائع التالفة للمورد واسترداد قيمتها.","البحث عبر الإنترنت عن مصادر بديلة للمواد الخام.","التنسيق المستمر مع أمين المخزن لمعرفة النواقص الفورية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (35, 'اخصائي إدارة خدمات', '["الإشراف على جودة الخدمات المقدمة للعملاء أو الموظفين.","وضع معايير الخدمة (SLAs) ومراقبة الالتزام بها.","تقييم أداء مزودي الخدمات الخارجيين (مثل شركات النظافة).","تطوير قنوات تقديم الخدمة لجعلها أكثر سهولة ويسراً.","مراجعة ميزانية تقديم الخدمات وتحقيق توازن الجودة والتكلفة.","استقبال ملاحظات متلقي الخدمة وتعديل الإجراءات بناءً عليها.","تنظيم جداول تقديم الخدمة لمنع التكدس وتوفير الوقت.","التحقق من توفر جميع الأدوات والمعدات اللازمة لمزودي الخدمة.","تصميم نماذج استبيان إلكترونية لتقييم الخدمات دورياً.","إجراء زيارات تفقدية مفاجئة لمواقع تقديم الخدمة.","حل الشكاوى العالقة والمعقدة المتعلقة برداءة الخدمة.","تطوير برامج ولاء لمكافأة العملاء دائمي الاستخدام للخدمة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (36, 'اخصائي استشارات اعمال', '["تقديم حلول عملية للمشاكل التشغيلية والتنظيمية.","مساعدة المديرين في اتخاذ القرارات بناءً على بيانات السوق.","تقييم كفاءة سلاسل التوريد والعمليات اللوجستية.","تصميم مؤشرات أداء لقياس نجاح الخطط التشغيلية.","تقديم ورش عمل تدريبية للقيادات حول أفضل الممارسات.","إجراء عمليات المراجعة والتدقيق الإداري للأقسام.","اقتراح استراتيجيات التوسع الجغرافي أو فتح أسواق جديدة.","تحليل دورة حياة المنتج وتقديم نصائح للتطوير.","توجيه الشركة في مشاريع التحول الرقمي وأتمتة العمليات.","بناء خطط التعاقب الوظيفي (Succession Planning) للمناصب الحساسة.","تقييم ثقافة بيئة العمل واقتراح سبل لزيادة الترابط بين الموظفين.","صياغة الرؤية والرسالة المؤسسية وتحديثها حسب المعطيات."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (37, 'اخصائي تأمين', '["إدارة بوالص التأمين والمطالبات المتعلقة بالشركة.","التفاوض مع شركات التأمين للحصول على أفضل التغطيات.","متابعة إجراءات التعويض في حال حدوث حوادث أو أضرار.","مراجعة كشوف المستفيدين من التأمين وتحديثها بشكل دوري.","تقييم المخاطر القابلة للتأمين داخل المنشأة وتقديم توصيات.","إضافة أو حذف الموظفين وعائلاتهم من وثيقة التأمين الطبي.","الرد على استفسارات الموظفين المتعلقة بمنافع التأمين الطبي.","متابعة التأمين الشامل على أسطول السيارات وتجديده.","تجهيز المستندات والفواتير الطبية المطلوبة لرفع المطالبات.","التأمين على الشحنات والبضائع المستوردة ضد مخاطر النقل.","عقد ورش تعريفية للموظفين لتعريفهم بشبكة المستشفيات المعتمدة.","المقارنة السنوية بين عروض شركات التأمين المختلفة قبل التجديد."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (38, 'اخصائي توظيف', '["فرز السير الذاتية وإجراء المقابلات الوظيفية الأولية.","التنسيق مع رؤساء الأقسام لتحديد الفجوات الوظيفية لديهم.","التحقق من المراجع المهنية والشهادات العلمية للمتقدمين.","تنظيم اختبارات التقييم النفسي والفني للمرشحين.","إدارة العلاقة مع شركات التوظيف الخارجية (Headhunters).","نشر الشواغر الوظيفية على منصات التوظيف مثل LinkedIn.","تحديث قاعدة بيانات السير الذاتية لسهولة الوصول إليها.","إرسال خطابات الرفض أو القبول للمرشحين بأسلوب مهني.","إعداد العروض الوظيفية وتوضيح مزايا العمل للمرشح النهائي.","ترتيب الجداول الزمنية للمقابلات بين المرشحين ومديري الإدارات.","تزويد المرشحين الجدد بدليل الموظف وشرح سياسات الشركة.","متابعة أداء الموظف الجديد خلال فترة التجربة وتقييمه."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (39, 'اخصائي خدمات عملاء', '["الرد على الطلبات التقنية والخدمية المباشرة.","استخدام أنظمة (CRM) لتسجيل تفاعلات العملاء ومتابعتها.","التنسيق مع الأقسام الفنية لحل مشاكل العملاء العالقة.","تقديم شروحات وافية عن العروض والمميزات الجديدة.","متابعة الشحنات أو الطلبات المتأخرة وإفادة العميل بالحالة.","الترحيب بالعملاء في الفروع وتوجيههم لمقدم الخدمة.","معالجة طلبات الإلغاء وتعديل الاشتراكات بمرونة.","التأكد من صحة بيانات العميل المسجلة وتحديثها عند اللزوم.","الاحتفاظ بنسبة عالية من مؤشر جودة الرد (Quality Assurance).","إقناع العملاء بالترقية إلى باقات وخدمات أعلى (Upselling).","الرد على المحادثات المباشرة (Live Chat) بسرعة ودقة.","تجميع مقترحات العملاء ورفعها للإدارة في تقرير شهري."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (40, 'اخصائي خدمة عملاء', '["متابعة مستويات رضا العميل بعد تقديم الخدمة.","إجراء اتصالات ''ما بعد البيع'' للتأكد من جودة التجربة.","معالجة طلبات استرداد الأموال أو استبدال المنتجات.","جمع الاقتراحات من العملاء لتطوير الخدمات المستقبلية.","التعامل مع العملاء الغاضبين وامتصاص استيائهم بحرفية.","إعداد تقارير دورية تبرز المشاكل المتكررة وطرق حلها.","توضيح سياسات الضمان والاستبدال للعملاء بشكل شفاف.","إنشاء قاعدة معرفية (FAQ) للأسئلة الشائعة لتسهيل العمل.","إدارة حسابات التواصل الاجتماعي للرد المباشر على شكاوى الجمهور.","التنسيق مع قسم الجودة لتحسين دورة حياة المنتج بناء على الشكاوى.","تصنيف العملاء حسب أهميتهم وتوفير خدمة (VIP) لكبار الزوار.","التأكد من التزام الفريق بالنصوص المعتمدة أثناء المكالمات."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (41, 'اخصائي خدمه عملاء', '["استقبال الشكاوى الميدانية والعمل على حلها.","التواجد في مراكز الاستقبال للتعامل المباشر مع الجمهور.","التأكد من سرعة زمن الاستجابة لطلبات العملاء في الموقع.","تقديم تقارير عن المشاكل التقنية في أجهزة الخدمة الذاتية.","توجيه العملاء إلى القنوات الرقمية لتسهيل معاملاتهم.","التعامل مع حالات الطوارئ في صالات الانتظار بكل هدوء.","توزيع استبيانات ورقية للعملاء لتقييم الخدمة الميدانية.","المساعدة في ملء استمارات التقديم للأشخاص كبار السن.","الإشراف على ترتيب وتنظيف صالة استقبال العملاء.","متابعة دورة الطلب الميداني حتى تسليمه للعميل يداً بيد.","توزيع الكتيبات الإرشادية والترويجية للجمهور المباشر.","الاحتفاظ بمظهر مهني ولائق يعكس صورة المنشأة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (42, 'اخصائي دعم فني', '["حل المشكلات التقنية المتعلقة بالأجهزة والبرامج للمستخدمين.","صيانة أجهزة الكمبيوتر والطابعات والماسحات الضوئية.","تنصيب أنظمة التشغيل والبرامج المكتبية للموظفين.","إدارة حسابات البريد الإلكتروني وكلمات المرور للمستخدمين.","تقديم الدعم الفني عن بُعد أو ميدانياً للأقسام.","إعداد وتجهيز الأجهزة للموظفين الجدد وربطها بالشبكة.","استكشاف وإصلاح مشاكل الاتصال بالإنترنت والشبكات الداخلية.","تنظيف الأجهزة من الفيروسات والبرمجيات الخبيثة بانتظام.","توثيق البلاغات التقنية في نظام التذاكر (Ticketing System).","إجراء عمليات النسخ الاحتياطي لبيانات المستخدمين الهامة.","تحديث تعريفات الأجهزة (Drivers) لضمان التوافق.","شرح طرق الاستخدام الصحيح للأجهزة التقنية للموظفين."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (43, 'اخصائي عقود', '["متابعة فترات صلاحية وتجديد الاتفاقيات التجارية.","التنبيه المبكر بمواعيد انتهاء العقود لاتخاذ إجراءات التجديد.","التأكد من التزام الأطراف المتعاقدة ببنود التسليم والدفع.","معالجة طلبات تعديل أو إضافة ملاحق للعقود القائمة.","متابعة الكفالات البنكية والضمانات المرتبطة بالعقود.","التواصل مع الموردين لإخطارهم بإنهاء التعاقد عند ضعف الأداء.","إعداد تقارير ملخصة لأهم الشروط التعاقدية لتسهيل فهمها للإدارة.","مراجعة عقود الإيجار والتأمين الخاصة بمرافق الشركة.","تأمين حفظ العقود في خزائن آمنة مقاومة للحريق.","أرشفة نسخ إلكترونية من كافة العقود لسهولة البحث.","التنسيق مع المالية لصرف الدفعات المرتبطة بنسب الإنجاز في العقود.","مقارنة أسعار العقود القديمة بالأسعار الحالية قبل التجديد."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (44, 'اخصائي علاقات عامة', '["تنظيم الفعاليات والمؤتمرات واللقاءات الخاصة بالشركة.","حجز القاعات وتنسيق خدمات الضيافة للفعاليات.","اختيار وتصميم الهدايا الدعائية الرسمية للمنشأة.","التنسيق مع المصورين والمصممين لتغطية فعاليات الشركة.","إدارة قواعد البيانات الخاصة بكبار الشخصيات والشركاء.","كتابة التقارير حول نجاح الفعاليات ومدى تحقيق أهدافها.","بناء شبكة تواصل مع الجمعيات الخيرية لتعزيز العمل المجتمعي.","تطوير حملات توعوية لتعزيز الصورة الإيجابية في المجتمع.","مرافقة كبار الزوار أثناء جولاتهم الميدانية بمقر العمل.","إعداد لوحات الترحيب والشهادات التقديرية للشركاء.","تسهيل إجراءات الرعاية (Sponsorships) للمؤتمرات الكبرى.","مراقبة ما يُنشر عن الشركة على منصات التواصل الاجتماعي والرد عليه."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (45, 'اخصائي عمليات موارد بشرية', '["تحديث ملفات الموظفين والبيانات الوظيفية على النظام.","أرشفة المستندات الرسمية (هويات، جوازات) لكل موظف.","متابعة إصدار وتجديد بطاقات العمل والتصاريح الأمنية.","إعداد التقارير الإحصائية الدورية عن القوى العاملة.","مراقبة توازن الإجازات السنوية والمرضية للموظفين.","معالجة مطالبات تذاكر السفر للموظفين وعائلاتهم.","متابعة بوالص التأمين على الحياة الخاصة بالكوادر البشرية.","استكمال استمارات الخروج النهائي ونقل الكفالة للعمالة.","التنسيق مع المستشفيات لإجراء الفحص الطبي للموظفين الجدد.","مراجعة كشوفات الغياب واعتماد الخصومات في مسير الرواتب.","تحديث الهيكل التنظيمي (Org Chart) عند كل تغيير وظيفي.","الرد على استفسارات الموظفين المتعلقة بطلبات النظام الإلكتروني (ERP)."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (46, 'اخصائي قانوني', '["مراجعة اللوائح الداخلية للتأكد من قانونيتها.","مراجعة العقود الدولية والمحلية من الناحية القانونية.","حماية حقوق الملكية الفكرية والعلامات التجارية للشركة.","متابعة تحديثات قوانين العمل والتأمينات الاجتماعية.","صياغة اتفاقيات عدم الإفصاح (NDA) مع الشركاء.","تقديم المشورة حول القوانين الضريبية والتجارية الجديدة.","حضور الجلسات في المحاكم العمالية والتجارية كممثل قانوني.","صياغة عرائض الدعاوى ومذكرات الدفاع لتقديمها للقضاء.","متابعة القضايا المتعلقة بتحصيل الديون المتعثرة.","الاشتراك في لجان التحقيق الداخلي لضمان سيرها بنزاهة.","إعداد خطابات رسمية للجهات الحكومية ذات طابع قانوني.","تدريب الإدارة العليا على قواعد الحوكمة والامتثال القانوني."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (47, 'اخصائي مبيعات', '["تحليل توجهات السوق لزيادة الحصة السوقية.","دراسة أسعار المنافسين وتقديم توصيات لتعديل قائمة الأسعار.","فتح أسواق جديدة للمنتج في مناطق جغرافية مختلفة.","المشاركة في المعارض التجارية لجذب عملاء جدد.","بناء علاقات طويلة الأمد مع كبار المشترين (Wholesalers).","تطوير خطة زيارات ميدانية دورية للعملاء الحاليين.","تقديم استشارات للعملاء لتوضيح كيفية استفادتهم القصوى من المنتج.","التفاوض على العقود الكبيرة لضمان أعلى هامش ربح.","استخدام أدوات التحليل للتنبؤ بالمبيعات في الربع القادم.","تدريب البائعين الجدد على مهارات التفاوض وإغلاق البيع.","العمل المستمر لتخفيض نسبة إلغاء العقود من قبل العملاء.","تنظيم ورش عمل مصغرة لشرح مميزات المنتج التقنية للعميل."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (48, 'اخصائي مراقبة مخزون', '["إجراء عمليات الجرد الدوري ومطابقة الأرصدة.","التحقيق في أسباب العجز أو الزيادة في المخزون الفعلي.","الإشراف على عمليات جرد نهاية العام المالي.","مراجعة مستندات الإضافة والصرف من المخازن.","التأكد من كفاءة برامج إدارة المخازن (ERP System).","تقديم اقتراحات للتخلص من المخزون الراكد أو بطيء الحركة.","تقييم دقة البيانات المخزنية وإجراء تصحيحات دورية للنظام.","التأكد من عزل المواد التالفة مادياً وإسقاطها دفترياً.","مراقبة ظروف السلامة المخزنية لمنع تلف البضائع.","تحليل تواريخ الانتهاء لترتيب أولويات صرف المواد (FEFO).","إعداد تقرير أسبوعي عن نسب النقص في الأصناف الأساسية.","الرقابة على حركة نقل المواد بين المستودعات الفرعية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (49, 'اخصائي مراقبة موارد بشرية', '["التأكد من تطبيق لائحة الجزاءات والمكافآت والالتزام.","التحقيق في مبررات الغياب والتقارير الطبية المشكوك فيها.","مراجعة كشوف الرواتب للتأكد من مطابقتها لأيام الدوام الفعلي.","مراقبة التزام الموظفين بمدونة السلوك الأخلاقي والمهني.","رفع توصيات للإدارة بشأن الموظفين غير المنضبطين.","التأكد من التزام الإدارات بعدم تكليف الموظفين بأعمال خطرة.","مراقبة الالتزام بمواعيد فترات الراحة والصلاة المحددة.","استلام الشكاوى العمالية والتحقق منها بسرية تامة.","القيام بزيارات مفاجئة للفروع لمراقبة سير العمل وانضباطه.","مراجعة سجلات الإضافي لمنع التلاعب في الساعات المسجلة.","تحليل شكاوى التحرش أو التنمر في بيئة العمل.","مراقبة التزام الموظفين بالدورات التدريبية الإلزامية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (50, 'اخصائي مشاريع', '["متابعة تقارير الإنجاز الدورية ورفعها للإدارة.","قياس مؤشرات أداء المشروع (KPIs) بشكل أسبوعي.","تحديث الجدول الزمني للمشروع بناءً على المعطيات الميدانية.","مراجعة مطالبات المستخلصات المالية للمقاولين والموردين.","تقديم الدعم اللوجستي لفرق العمل المتواجدة في موقع المشروع.","أرشفة كافة المخططات الهندسية والموافقات الرسمية للمشروع.","التأكد من توفر المواد الخام اللازمة قبل بدء أي مرحلة عمل.","عقد ورش عمل لتوضيح أهداف المشروع لفريق التنفيذ الميداني.","توثيق التغييرات (Change Orders) واعتمادها من الإدارة المباشرة.","تقييم أداء المقاولين من الباطن وتقديم تقرير عن جودتهم.","ترتيب عمليات فحص الجودة الميدانية بالتنسيق مع الاستشاري.","تجهيز ملف التسليم الابتدائي والنهائي للمشروع بكامل مستنداته."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (51, 'اخصائي مشتريات', '["تقييم أداء الموردين دورياً وبحث سبل تقليل التكاليف.","دراسة السوق لمعرفة تغيرات الأسعار العالمية للمواد.","تنظيم المناقصات وجمع عروض الأسعار ومقارنتها.","معالجة مرتجعات المشتريات التي لا تطابق المواصفات.","التأكد من حصول المشتريات على التراخيص والشهادات المطلوبة.","التفاوض لتأمين عقود شراء سنوية تثبت الأسعار وتحمي الشركة.","استكشاف موردين دوليين للبحث عن خيارات ذات جودة أعلى.","مراجعة الشروط الجزائية في عقود التوريد قبل توقيعها.","متابعة التخليص الجمركي للشحنات المستوردة من الخارج.","تسريع إجراءات الشراء للمواد الطارئة دون الإخلال بالسياسات.","الاحتفاظ بقاعدة بيانات دقيقة ومحدثة لجميع الموردين وأسعارهم.","التأكد من استخدام الموردين لمواد صديقة للبيئة (Green Purchasing)."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (52, 'اداري عام', '["تنسيق العمل الإداري المشترك بين الإدارات المختلفة.","الإشراف على توزيع الموارد المكتبية المشتركة بين الأقسام.","إعداد تقارير الأداء الإداري الدوري للمنشأة ككل.","متابعة الالتزام بالهوية المؤسسية في كافة المراسلات.","إدارة الخدمات اللوجستية المشتركة مثل أسطول السيارات.","الإشراف المباشر على الكافتيريا ومستوى النظافة في المبنى.","تنظيم عمليات صيانة التكييف والمصاعد بشكل دوري.","متابعة تجديد عقود الإيجار لمقار الفروع المختلفة.","إصدار التعاميم الإدارية الخاصة بالعطلات الرسمية والمناسبات.","تأمين حجوزات الطيران والفنادق للموظفين المنتدبين.","الإشراف على عمليات النقل والإخلاء عند تغيير المقار.","حل أي مشاكل تعيق سير العمل المكتبي اليومي للموظفين."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (53, 'اداري مواقع الكترونيه', '["متابعة أداء الموقع وحل مشاكل الروابط وتجربة المستخدم.","تحليل حركة الزوار (Analytics) وتقديم تقارير لزيادة التفاعل.","التأكد من توافق الموقع مع الهواتف الذكية والمتصفحات المختلفة.","إدارة المتجر الإلكتروني وتحديث المنتجات والأسعار.","حل المشكلات البرمجية البسيطة التي تظهر في واجهة الموقع.","إنشاء وتعديل الصفحات المقصودة (Landing Pages) للحملات التسويقية.","تحسين سرعة تحميل الصفحات لتقليل معدل الارتداد (Bounce Rate).","تحديث المدونة بمقالات دورية تتوافق مع محركات البحث.","التأكد من عمل بوابات الدفع الإلكتروني بسلاسة ودون أعطال.","تحديث سياسات الخصوصية وشروط الاستخدام على الموقع.","إرسال النشرات البريدية (Newsletters) للقائمة البريدية للموقع.","مراقبة التعليقات على الموقع وإدارة عمليات التسجيل للأعضاء."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (54, 'اعمال ادارية', '["تنفيذ المهام المكتبية الروتينية مثل الأرشفة والمراسلات.","تصوير المستندات وتوزيعها على الجهات ذات العلاقة.","الرد على المكالمات الهاتفية وتحويلها للمختصين.","المساعدة في إدخال البيانات البسيطة على الأنظمة.","ترتيب قاعات الاجتماعات وتجهيز أدوات العرض.","استلام وتوثيق البريد السريع الطرود المرسلة للإدارة.","تنظيم أدراج الملفات ووضع فواصل واضحة لتسهيل البحث.","إعداد القهوة والضيافة للزوار المهمين عند الحاجة.","جمع التواقيع من المدراء على الأوراق الرسمية والمستندات.","تسجيل مواعيد حضور وانصراف الموظفين في سجل مخصص.","شراء الطوابع البريدية وإرسال الخطابات الرسمية عبر البريد.","الحفاظ على سرية المستندات التي يتم تصويرها أو تداولها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (55, 'بائع', '["إتمام عمليات البيع المباشر مع العملاء في نقاط البيع.","تقديم النصيحة للعميل لاختيار المنتج الأنسب لاحتياجه.","ترتيب المنتجات في منطقة البيع لجذب انتباه الزبائن.","استخدام جهاز الكاشير ومعالجة المدفوعات النقدية والبطاقات.","المساعدة في عمليات الجرد اليومي لمنطقة البيع.","التأكد من نظافة الرفوف وخلوها من الأتربة.","شرح سياسات الاستبدال والاسترجاع للعميل قبل الدفع.","تحقيق مستهدفات المبيعات اليومية والشهرية (تارجت).","تغليف المنتجات المشتراة بشكل أنيق يرضي العميل.","إبلاغ مشرف المعرض بالمنتجات التي أوشكت على النفاذ.","الرد على استفسارات الزبائن حول تواريخ توفر بضاعة معينة.","توزيع العروض الترويجية والكتيبات على زوار المعرض."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (56, 'بائع عطور', '["شرح أنواع الروائح ومكوناتها وإقناع الزبائن بالشراء.","تقديم عينات تجريبية للعملاء لشرح الفرق بين العطور.","معرفة الثبات والتركيز لكل عطر للإجابة على أسئلة العميل.","تنسيق سلال الهدايا وتغليف العطور بشكل جذاب.","الحفاظ على نظافة التسترات (Tester) والزجاجات المعروضة.","اقتراح العطور المناسبة للمواسم المختلفة (صيفي/شتوي).","التمييز بين النوتات العطرية (الافتتاحية، القلب، القاعدة).","تطبيق تقنيات البيع المتقاطع لبيع البخور أو معطرات الجسم.","تنظيم زجاجات العطور على الأرفف حسب الماركات لسهولة العرض.","إدارة المخزون الشخصي للمبيعات اليومية لتجنب العجز.","رش معطرات الجو في المعرض للحفاظ على بيئة جاذبة.","تقديم النصائح للعملاء حول كيفية تخزين العطر ليدوم طويلاً."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (57, 'بائع هاتفي', '["تسويق المنتجات وإغلاق الصفقات البيعية عبر الهاتف.","إجراء المكالمات الصادرة للعملاء المحتملين (Cold Calling).","شرح مميزات الخدمة والرد على اعتراضات العميل هاتفياً.","تسجيل بيانات العملاء المهتمين ومتابعتهم لاحقاً.","تحقيق الهدف اليومي من عدد المكالمات والمبيعات الهاتفية.","تحديث قاعدة بيانات العملاء بعد كل مكالمة بإضافة الملاحظات.","استخدام مهارات الإقناع الصوتي للتعامل مع تردد العملاء.","إرسال عروض الأسعار والكتالوجات عبر الإيميل أو الواتساب بعد المكالمة.","التأكد من التزام العميل بتسديد الرسوم أو الدفعة الأولى.","الاحتفاظ بنبرة صوت إيجابية ومحفزة طوال ساعات العمل.","إجراء مكالمات للمبيعات المتقاطعة (Cross-Selling) للعملاء الحاليين.","التعامل بمهنية مع العملاء غير المهتمين وإنهاء المكالمة بلباقة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (58, 'تسويق', '["المساهمة في تنفيذ الأنشطة الترويجية الميدانية.","توزيع المواد الدعائية (بروشورات، هدايا) في المعارض.","المساعدة في تنظيم منصات العرض في الفعاليات التجارية.","تصوير الأنشطة الميدانية لاستخدامها في المحتوى الرقمي.","رصد ملاحظات الجمهور الميدانية ورفعها لفريق التسويق.","تجهيز العينات المجانية للجمهور في نقاط التوزيع.","المشاركة في العصف الذهني لابتكار أفكار تسويقية غير تقليدية.","جمع بيانات العملاء المهتمين أثناء المعارض لمتابعتهم لاحقاً.","إجراء استبيانات سريعة للجمهور لقياس مدى وعيهم بالعلامة.","التأكد من توافر المطويات والكتيبات في جميع فروع الشركة.","المساهمة في ترتيب وتجهيز اللوحات الإعلانية (Roll-ups).","مراقبة الأنشطة الترويجية للمنافسين في نفس موقع الفعالية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (59, 'جامع بيانات', '["جمع المعلومات من الميدان أو المصادر لغرض الدراسة والتحليل.","إجراء المقابلات الميدانية وتعبئة الاستبيانات الورقية أو الإلكترونية.","التأكد من دقة المعلومات المجموعة ومطابقتها للواقع.","تصنيف البيانات الميدانية وترتيبها في جداول أولية.","رفع تقارير يومية عن العينات التي تم جمعها.","استخدام الأجهزة اللوحية (Tablets) لضمان إدخال البيانات فورا.","الالتزام بالحياد التام وعدم التأثير على إجابات المستهدفين.","التواجد في المناطق الجغرافية المحددة لضمان تنوع العينات.","شرح أهداف الاستبيان للمشاركين لكسب ثقتهم وتعاونهم.","مراجعة الاستمارات لتلافي النقص قبل مغادرة موقع الجمع.","الحفاظ على سرية البيانات الشخصية للمشاركين في الدراسة.","التصوير الميداني لتوثيق المواقع إذا تطلب البحث ذلك."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (60, 'حارس أمن', '["حماية المنشأة ومراقبة المداخل والمخارج وضمان السلامة.","التحقق من تصاريح الدخول والخروج للزوار والمركبات.","القيام بجولات تفتيشية دورية داخل مرافق المنشأة.","مراقبة شاشات الكاميرات وأنظمة إنذار الحريق والسرقة.","التدخل السريع في حالات الطوارئ وتوجيه الأفراد للإخلاء.","تسجيل بيانات الزوار في السجل المخصص قبل السماح بدخولهم.","تفتيش الحقائب والطرود الواردة للمنشأة باستخدام الأجهزة المخصصة.","إغلاق وتأمين الأبواب والنوافذ بعد انتهاء ساعات الدوام الرسمي.","كتابة تقرير وردية يومي يوضح أي حوادث أو اختراقات أمنية.","منع الأشخاص غير المصرح لهم من التواجد في المناطق المقيدة.","التواصل المستمر مع أجهزة الدفاع المدني والشرطة عند الطوارئ.","التأكد من عدم وقوف سيارات في المداخل المخصصة للطوارئ."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (61, 'خدمة العملاء', '["التواصل المباشر للإجابة على تساؤلات الجمهور.","شرح شروط وأحكام الخدمات المقدمة بوضوح.","توجيه العميل للقسم المختص حسب نوع استفساره.","استقبال المستندات المطلوبة من العملاء لمراجعتها.","الترحيب بالجمهور بأسلوب يعكس هوية المنشأة.","توزيع أرقام الانتظار وتنظيم طوابير العملاء في الفروع.","مساعدة العملاء في استخدام أجهزة الخدمة الذاتية لتسريع العمل.","استلام شكاوى العملاء المكتوبة وإرسالها لمركز العناية بالعملاء.","الاحتفاظ بنماذج التقديم والكتيبات الإرشادية لتوزيعها.","التأكد من توفر بيئة مريحة للعميل في منطقة الانتظار.","التحدث بلباقة والابتسامة المستمرة لترك انطباع أولي ممتاز.","إخطار المشرف بأي تأخير في معالجة طلبات العملاء الموجودين."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (62, 'خدمة عملاء', '["إدارة تجربة العميل اليومية وتحسين مستوى الخدمة.","الرد على استفسارات العملاء عبر البريد الإلكتروني والشات.","تحديث بيانات العملاء في النظام بشكل مستمر.","المساعدة في حل مشكلات الدخول للحسابات الإلكترونية.","تقديم تغذية راجعة للإدارة حول العيوب الشائعة في الخدمة.","الاستماع الفعال لاحتياجات العميل لتقديم الحل الأنسب.","تحليل تكرار استفسار معين لطلب تحديث صفحة الأسئلة الشائعة.","تنفيذ عمليات إلغاء الخدمات أو إيقافها بناءً على طلب العميل.","التأكد من استلام العميل لرسائل التأكيد بعد كل إجراء.","التواصل مع شركات الشحن للاستعلام عن مسار شحنة العميل.","استخدام النصوص الجاهزة (Templates) لتسريع الرد على الإيميلات.","التعامل مع استرداد المبالغ المالية وفق سياسة المنشأة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (63, 'رئيس مجلس إدارة', '["رسم السياسات العليا وتمثيل الشركة أمام الجهات الرسمية.","اعتماد الميزانية السنوية والخطط الاستراتيجية الكبرى.","مراقبة أداء المدير التنفيذي وضمان تحقيق الأرباح.","اتخاذ القرارات المصيرية بشأن التوسع أو الاندماج.","إدارة علاقات المستثمرين وحمايتهم حقوقهم.","رئاسة جلسات مجلس الإدارة وضمان سيرها بنظام وفاعلية.","دعوة الجمعية العمومية للمساهمين للانعقاد ومناقشة التقرير السنوي.","التصديق على الحسابات الختامية وتوزيع الأرباح على المساهمين.","بناء علاقات استراتيجية مع كبار مسؤولي الدولة والبنوك.","تشكيل اللجان المنبثقة عن المجلس (كلجنة المراجعة والمخاطر).","ضمان تطبيق مبادئ الحوكمة والشفافية في كافة أعمال الشركة.","توجيه الشركة لتبني مبادرات الاستدامة والمسؤولية المجتمعية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (64, 'رسام خرائط', '["رسم الخرائط الجغرافية والطبوجرافية باستخدام برامج الـ GIS.","تحديث الخرائط بناءً على المسوحات الأرضية الجديدة.","إدخال البيانات الوصفية للمواقع الجغرافية على الخرائط الرقمية.","إنتاج الخرائط المطبوعة والملونة لاستخدامها في الدراسات.","تحويل الصور الجوية إلى خرائط خطية دقيقة.","تصميم مفاتيح الخرائط (Legends) لتسهيل قراءتها وفهمها.","تحديد الإحداثيات والمسافات بدقة لتجنب الأخطاء المساحية.","دمج الخرائط الجغرافية مع البيانات الديموغرافية للمناطق.","التعاون مع المهندسين المدنيين لتخطيط مسارات الطرق والشبكات.","استخدام برامج مثل AutoCAD Civil 3D لإنشاء نماذج أرضية.","أرشفة المخططات القديمة والرجوع إليها لعمل مقارنات تاريخية.","إخراج الخرائط التفاعلية لنشرها على مواقع الويب الخاصة بالمشروع."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (65, 'رسام هندسي', '["تحويل التصاميم والأفكار إلى مخططات تنفيذية دقيقة.","رسم المساقط الأفقية والواجهات والقطاعات باستخدام AutoCAD.","تعديل الرسومات الهندسية بناءً على ملاحظات المهندسين.","حساب الكميات الأولية من خلال المخططات الهندسية.","طباعة وتنسيق اللوحات الهندسية بمقاييس رسم صحيحة.","إضافة الأبعاد والمحاور والمناسيب الدقيقة على اللوحات.","رسم التفاصيل الإنشائية والمعمارية (Details) لتوضيح التنفيذ.","استخدام برامج الـ 3D لعمل مناظير توضيحية للمشروع.","التأكد من تطابق المخططات المعمارية مع المخططات الإنشائية.","تحديث الرسومات حسب ما تم تنفيذه فعلياً في الموقع (As-Built).","تجهيز ملفات الأوتوكاد (Layers) بشكل منظم يسهل التعديل عليه.","حفظ وأرشفة نسخ إلكترونية من جميع الإصدارات للمخططات."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (66, 'سائق سيارة', '["نقل الموظفين والطرود الصغيرة داخل المدينة بأمان.","الحفاظ على نظافة المركبة وإجراء الفحص اليومي لها.","الالتزام بقواعد السير المرورية لتجنب المخالفات والحوادث.","توثيق المسافات المقطوعة في سجل الحركة اليومي.","إبلاغ مسؤول النقل بمواعيد الصيانة الدورية للمركبة.","فحص مستويات الزيت والمياه وضغط الإطارات قبل التحرك.","استخدام تطبيقات الخرائط (GPS) للوصول للوجهات بأسرع الطرق.","التعامل بلباقة واحترام مع الموظفين المنقولين.","القيادة بحذر أثناء الظروف الجوية السيئة (أمطار، ضباب).","الإبلاغ الفوري عن أي حوادث أو أضرار تلحق بالسيارة.","تجديد رخصة القيادة واستمارة السيارة قبل انتهائها.","مساعدة الركاب في حمل أمتعتهم أو طرودهم الخفيفة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (67, 'سائق سيارة أجرة', '["تقديم خدمات النقل الفردي للركاب والالتزام بالمسارات.","مساعدة الركاب في تحميل وتنزيل الأمتعة.","التعامل اللبق مع الجمهور وتقديم خدمة متميزة.","استخدام تطبيقات الخرائط لتفادي الازدحام المروري.","محاسبة الركاب بدقة حسب العداد أو التسعيرة المقررة.","الحفاظ على نظافة السيارة داخلياً وخارجياً لراحة الركاب.","تشغيل التكييف أو الراديو بناءً على رغبة الراكب.","الالتزام الصارم بالسرعات القانونية لتجنب الحوادث.","التواجد في أماكن التجمعات الحيوية (المطارات، الفنادق).","إرجاع المفقودات التي ينساها الركاب في السيارة للإدارة أو الشرطة.","التعامل مع تطبيقات الحجز الذكية (مثل أوبر أو كريم).","توفير فكة نقدية كافية لتسهيل عملية الحساب مع الركاب."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (68, 'سائق شاحنة صغيرة', '["نقل البضائع والمستلزمات بين الفروع والمستودعات.","التأكد من ربط وتثبيت الشحنة جيداً قبل التحرك.","مطابقة كشوف الاستلام مع البضائع المشحونة.","توخي الحذر الشديد عند القيادة في المناطق المزدحمة بالحمولة.","تنظيف صندوق الشحن للتأكد من عدم تلوث البضائع.","المساعدة في تحميل البضائع وتفريغها عند نقاط التسليم.","تخطيط مسار الرحلة لتقليل استهلاك الوقود والوقت.","تغطية البضائع بالشفاف أو المشمع لحمايتها من المطر أو الشمس.","الحصول على توقيع المستلم على بوليصة الشحن.","فحص فرامل وإطارات الشاحنة بشكل يومي نظراً لوزن الحمولة.","التوقف في محطات الوزن (الميازين) للتأكد من التزام الحمولة المسموحة.","إبلاغ الإدارة بأي نقص أو تلف في البضائع أثناء النقل."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (69, 'سكرتير', '["إدارة المكاتب وتنظيم الملفات واستقبال المراجعات والاتصالات.","ترتيب أجندة المواعيد اليومية للمدير المباشر.","طباعة الخطابات والتقارير وتنسيق المراسلات.","تنظيم وحفظ الملفات في الأرشيف الورقي والإلكتروني.","استقبال الضيوف وتقديم خدمات الضيافة الأولية.","استلام البريد اليومي وفرزه وعرضه على المدير.","تجهيز ملفات الاجتماعات بالوثائق والمعلومات المطلوبة.","إرسال واستقبال الفاكسات ورسائل البريد الإلكتروني الرسمية.","تأمين حجوزات الطيران والفنادق لرحلات عمل المدير المباشر.","متابعة توفير الأدوات المكتبية والقرطاسية الخاصة بالمكتب.","تسجيل تذكيرات هامة للمدير بمواعيد تسليم التقارير.","منع المتطفلين أو المراجعين غير المجدولين من تعطيل وقت المدير."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (70, 'سكرتير تنفيذي', '["دعم الإدارة العليا في تنظيم المواعيد وإعداد التقارير السرية.","حضور الاجتماعات الهامة وتدوين المحاضر والقرارات.","فلترة المكالمات والرسائل الموجهة للمدير العام.","تنسيق رحلات السفر والحجوزات الفندقية للإدارة العليا.","متابعة تنفيذ التكليفات الصادرة من المدير العام للأقسام.","إعداد عروض تقديمية (PowerPoint) احترافية لعرضها في الاجتماعات.","صياغة المراسلات عالية الأهمية باللغتين العربية والإنجليزية.","الحفاظ على سرية المعلومات الخاصة باستراتيجيات وماليات الشركة.","تنظيم المؤتمرات الصحفية أو اللقاءات الكبرى الخاصة بالإدارة العليا.","توجيه الإدارات المختلفة بشأن سياسات مكتب المدير التنفيذي.","تمثيل مكتب المدير في استقبال كبار الشخصيات والوفود الأجنبية.","تلخيص التقارير الطويلة الواردة من الأقسام وعرضها بإيجاز على المدير."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (71, 'ضابط علاقات عامة', '["التنسيق الميداني للفعاليات والتعامل مع الجهات الحكومية.","تخليص المعاملات الرسمية التي تتطلب تواجداً ميدانياً.","مرافقة الوفود في جولاتهم الخارجية وتمثيل الشركة.","الحصول على التراخيص اللازمة لإقامة الفعاليات العامة.","معالجة المشكلات الميدانية التي قد تواجه ضيوف الشركة.","تجديد رخص وتصاريح الشركة لدى البلدية أو الدفاع المدني.","تسليم خطابات الدعوة لكبار الشخصيات بشكل يدوي ورسمي.","بناء علاقات ودية مع موظفي الدوائر الحكومية لتسهيل الإجراءات.","تنسيق مواكب السيارات وتنقلات الوفود الرسمية.","الإشراف على عمليات التخليص الجمركي الخاصة بهدايا الفعاليات.","التأكد من التغطية الإعلامية للفعاليات في المواقع الخارجية.","حجز القاعات الخارجية والفنادق والتأكد من مستوى الخدمة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (72, 'عامل تصنيع', '["العمل على خطوط الإنتاج لتجميع أو تصنيع المنتجات النهائية.","تشغيل الآلات الإنتاجية البسيطة ومراقبة سير عملها.","التأكد من جودة المنتج المنتج ومطابقته للمواصفات الأولية.","تغليف المنتجات الجاهزة ووضع الملصقات التعريفية عليها.","تنظيف وصيانة ماكينات التصنيع بشكل دوري وبسيط.","إبعاد المنتجات المعيبة أو التي بها شوائب عن خط الإنتاج.","الالتزام بارتداء الملابس الوقائية (القفازات، الكمامات، سدادات الأذن).","تزويد الآلات بالمواد الخام لضمان عدم توقف عملية التصنيع.","المحافظة على نظافة وترتيب مساحة العمل (نظام الـ 5S).","تعبئة النماذج اليومية بعدد القطع المنتجة وحجم التالف.","المساعدة في نقل المنتجات الجاهزة إلى منطقة التسليم أو التخزين.","الإبلاغ الفوري عن أي أصوات غريبة أو أعطال في خطوط الإنتاج."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (73, 'عامل تعبئة رفوف', '["ترتيب المنتجات في المتجر وضمان توفرها بشكل لائق أمام الزبائن.","فحص تواريخ الصلاحية وسحب المنتجات المنتهية أو التالفة.","وضع ملصقات الأسعار والباركود على المنتجات والرفوف.","الحفاظ على نظافة الممرات والأرفف المخصصة للعرض.","نقل البضائع من المخزن الخلفي إلى صالة العرض لسد النقص.","تطبيق قاعدة (الصادر أولاً يباع أولاً - FIFO) عند رص البضائع.","تجميع عربات التسوق الفارغة من المواقف وإعادتها للمتجر.","مساعدة الزبائن في العثور على أماكن المنتجات داخل الممرات.","إعادة المنتجات التي تركها الزبائن في أماكن خاطئة لموقعها الصحيح.","إبلاغ مشرف الصالة عن المنتجات التي أوشكت على النفاد.","ترتيب واجهات الثلاجات لعرض المنتجات الغذائية بشكل جذاب.","التأكد من سلامة تغليف العبوات قبل وضعها على الأرفف."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (74, 'علاقات عامة', '["إدارة قنوات التواصل الاجتماعي والمؤسسي مع الجمهور.","الرد على الرسائل والتعليقات بأسلوب دبلوماسي ومهني.","نشر الأخبار والفعاليات بشكل لحظي على المنصات الرقمية.","التنسيق مع المؤثرين في حملات العلاقات العامة.","متابعة الترندات واقتراح محتوى تفاعلي للجمهور.","صياغة منشورات احترافية تبرز إنجازات الشركة ومشاريعها.","تنظيم مسابقات إلكترونية لزيادة التفاعل مع العلامة التجارية.","التغطية المباشرة (Live Streaming) لفعاليات الشركة.","تصميم رسائل التهنئة للمناسبات الوطنية والدينية ونشرها.","إجراء تحليل مشاعر الجمهور (Sentiment Analysis) من التعليقات.","العمل على إدارة الأزمات الرقمية واحتواء أي غضب جماهيري.","تقديم تقارير شهرية عن معدلات الوصول والتفاعل للمحتوى."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (75, 'فني تدفئة وتهوية وتكييف', '["صيانة وإصلاح أنظمة التكييف والتبريد المركزية.","تنظيف الفلاتر وفحص مستويات الفريون في الأجهزة.","تغيير القطع التالفة في وحدات التبريد والمراوح.","تركيب وحدات تكييف جديدة وتمديد الأنابيب الخاصة بها.","برمجة الثرموستات لضمان كفاءة استهلاك الطاقة.","فحص تسربات الغاز في دوائر التبريد ومعالجتها لحامياً.","غسيل وحدات التكييف الداخلية والخارجية بضغط الماء.","استكشاف أعطال اللوحات الإلكترونية (PCBs) لأجهزة التكييف.","صيانة مضخات المياه الخاصة بأبراج التبريد المركزية (Chillers).","تغيير سيور المراوح وتشحيم المحركات لمنع الاحتكاك.","قراءة المخططات الهندسية لمعرفة مسارات الدكت (Ducts).","الالتزام بمعايير السلامة عند التعامل مع غازات التبريد المضغوطة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (76, 'فني تصميم داخلي', '["تنفيذ الديكورات وتوزيع الأثاث في المساحات الداخلية للمنشأة.","اختيار الألوان والخامات والأقمشة المناسبة للمكاتب.","الإشراف على عمال الدهانات والجبس والباركيه.","توزيع الإضاءة بشكل جمالي ووظيفي داخل الغرف.","تقديم عينات للمواد (Moodboard) قبل البدء في التنفيذ.","رسم مخططات توزيع الأثاث باستخدام برامج AutoCAD أو SketchUp.","رفع المقاسات الميدانية للموقع ومطابقتها مع المخطط.","اقتراح النباتات واللوحات الجدارية لإضافة لمسة جمالية.","التنسيق مع فنيي الكهرباء لضمان توزيع الأفياش بشكل يخدم التصميم.","حساب كميات المواد المطلوبة للتنفيذ بدقة لمنع الهدر.","تصميم أثاث مخصص (Custom Made) ليناسب المساحات الضيقة.","متابعة أحدث صيحات الديكور الداخلي لتقديم أفكار عصرية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (77, 'فني تصميم معارض', '["تجهيز منصات العرض والديكورات في المؤتمرات والأسواق.","تركيب الاستندات واللوحات الإعلانية داخل أجنحة العرض.","توزيع المنتجات بشكل جذاب داخل المعرض لزيادة المبيعات.","صيانة ديكورات المعارض المتنقلة وتخزينها بعد الانتهاء.","تنسيق الصوت والإضاءة الخاصة بمنصة العرض.","تركيب الشاشات التفاعلية وتوصيلها بأجهزة العرض.","التعاون مع النجارين لتفصيل أجنحة عرض خشبية مخصصة.","تثبيت الملصقات الجدارية (Stickers) والمواد الدعائية بدقة.","التأكد من التزام تصميم الجناح بمساحة المعرض المخصصة.","تفكيك الجناح بالكامل بطريقة آمنة بعد انتهاء الفعالية.","التأكد من توفر مسارات آمنة للزوار داخل جناح العرض.","إصلاح أي تلف سريع في الديكورات يحدث أثناء فترة المعرض."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (78, 'فني دعم برامج', '["مساعدة المستخدمين في تنصيب وتشغيل التطبيقات المكتبية.","تدريب الموظفين على استخدام البرمجيات الجديدة في العمل.","حل مشاكل التوافق بين البرامج المختلفة على أجهزة الموظفين.","تحديث نسخ البرمجيات لضمان الحصول على آخر المزايا والأمان.","تسجيل البلاغات البرمجية المتكررة لرفعها لمطوري النظم.","إدارة تراخيص البرامج (Licenses) والتأكد من صلاحيتها.","تقديم حلول سريعة لمشاكل التوقف المفاجئ للتطبيقات (Crashes).","إنشاء أدلة استخدام مبسطة ومصورة للتطبيقات الأساسية.","استخدام برامج التحكم عن بعد لحل مشاكل الموظفين في الفروع.","استرداد الملفات المحذوفة أو التالفة للمستخدمين عند الإمكان.","تثبيت وتكوين برامج مكافحة الفيروسات والتأكد من فعاليتها.","التأكد من توافق البرامج المحاسبية أو الإدارية مع تحديثات النظام."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (79, 'فني سلامة وصحة مهنية', '["التفتيش على مواقع العمل للتأكد من خلوها من المخاطر المهنية.","التأكد من ارتداء الموظفين لمهمات الوقاية الشخصية (خوذة، قفاز).","الإشراف على تعبئة وسلامة طفايات الحريق وخراطيم المياه.","نشر لوحات إرشادية للسلامة في المناطق الخطرة.","التحقيق في حوادث العمل وإصابات الموظفين ورفع تقارير بها.","إجراء خطط إخلاء وهمية وتدريب الموظفين على مخارج الطوارئ.","فحص حبال السلامة والسقالات في المواقع الإنشائية.","التأكد من التهوية الجيدة في الأماكن المغلقة لتجنب الاختناق.","مراقبة التخزين الآمن للمواد الكيميائية والقابلة للاشتعال.","تحديث سجلات السلامة والأمن الصناعي بشكل دوري.","التأكد من وجود حقائب إسعافات أولية صالحة في جميع الأقسام.","إيقاف العمل فوراً في حال رصد أي مخالفة جسيمة تهدد الأرواح."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (80, 'فني صيانة آلات كهربائية', '["إصلاح المحركات واللوحات الكهربائية الصناعية والأعطال.","قراءة المخططات الكهربائية للآلات لتحديد أماكن الخلل.","فحص الدوائر الإلكترونية وتبديل المقاومات والقواطع التالفة.","صيانة مولدات الكهرباء الاحتياطية وتجربتها دورياً.","الالتزام بمعايير السلامة عند التعامل مع الضغط العالي.","إجراء برامج الصيانة الوقائية للآلات لمنع التوقف المفاجئ.","استخدام أجهزة القياس (Avometer) لفحص الجهد والتيار والمقاومة.","إعادة لف المحركات الكهربائية المحترقة (Rewinding).","برمجة وصيانة وحدات التحكم المنطقي المبرمج (PLC).","تغيير التوصيلات والأسلاك التالفة في لوحات التحكم الصناعية.","تشحيم المحركات والقطع الميكانيكية المرتبطة بالأنظمة الكهربائية.","كتابة تقارير الصيانة الفنية وتحديد قطع الغيار المطلوبة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (81, 'فني كهرباء', '["تمديد وصيانة الشبكات الكهربائية الداخلية والخارجية.","تركيب المفاتيح والأفياش ووحدات الإضاءة في المباني.","فحص التمديدات الكهربائية للتأكد من عدم وجود التماسات.","صيانة لوحات التوزيع الرئيسية في الطوابق.","تركيب أنظمة الطوارئ والإضاءة البديلة.","توزيع الأحمال الكهربائية لضمان عدم انقطاع التيار (Tripping).","تركيب كاميرات المراقبة وأنظمة الدخول الذكي (Access Control).","تمديد كابلات الشبكات (Data) والانتركم وأنظمة الصوت.","استكشاف وإصلاح أعطال السخانات الكهربائية والمضخات.","تطبيق أنظمة التأريض (Earthing) لحماية الأجهزة والمباني من الصواعق.","قراءة المخططات الكهربائية المعمارية وتنفيذها على أرض الواقع.","تبديل اللمبات ووحدات الإضاءة التالفة في المكاتب والممرات."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (82, 'فني مدني', '["الإشراف الفني الميداني على أعمال البناء والتشطيبات الإنشائية.","استلام أعمال النجارة والحدادة والخرسانة من المقاولين.","التأكد من جودة مواد البناء الموردة للموقع.","مراقبة العمال في الموقع وضمان تنفيذ المخططات بدقة.","كتابة تقرير يومي عن تطور الأعمال الإنشائية.","أخذ عينات من الخرسانة لإجراء اختبارات التكسير في المعمل.","الإشراف على أعمال العزل المائي والحراري للأسطح والخزانات.","مراجعة مناسيب الحفر والردم ومطابقتها للمخططات.","استلام أعمال التشطيبات كالمحارة، والدهانات، وتركيب السيراميك.","التأكد من معالجة الخرسانة بالماء (Curing) لعدة أيام بعد الصب.","حصر الكميات المنفذة فعلياً على أرض الواقع لرفع المستخلصات.","التنسيق المباشر مع المهندس المدني لإيجاد حلول للمشاكل الميدانية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (83, 'فني مساحة', '["تحديد المسافات والزوايا والحدود الجغرافية ورفع المساحات.","استخدام أجهزة (Total Station) و (GPS) في الرفع المساحي.","وضع نقاط المنسوب (Bench Marks) للمشاريع الإنشائية.","رسم الكروكيات المساحية الأولية للأراضي والمواقع.","التأكد من عدم تعدي المنشآت على الحدود القانونية المجاورة.","توقيع المحاور والأعمدة على الطبيعة لتوجيه عمال البناء.","حساب كميات الحفر والردم بناءً على المناسيب المرفوعة.","مراجعة دقة الأجهزة المساحية ومعايرتها بانتظام.","رفع إحداثيات الطرق وشبكات الصرف الصحي والمياه.","نقل البيانات من أجهزة المساحة إلى أجهزة الكمبيوتر لمعالجتها.","المشاركة في تسوية الأراضي لتجهيزها للعمليات الإنشائية.","إعداد تقارير مساحية دقيقة تسلم للاستشاري لاعتمادها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (84, 'فني ميكانيكي', '["صيانة المركبات أو الآلات الميكانيكية الثقيلة والمحركات.","تغيير الزيوت والفلاتر والسيور بشكل دوري (صيانة وقائية).","فحص أنظمة الهيدروليك والفرامل والتروس.","استخدام أجهزة الفحص الكمبيوترية لتحديد أعطال السيارات.","توضيب المحركات وإصلاح الأجزاء الميكانيكية المتآكلة.","استبدال ممتصات الصدمات (المساعدين) ونظام التعليق (العفشة).","فحص وإصلاح أعطال دورة التبريد (الردياتير) ومضخات المياه.","فك وتركيب صندوق التروس (الجيربوكس) وصيانته.","ضبط زوايا العجلات وترصيص الإطارات لتجنب الاهتزاز.","استخدام المخارط لتسوية وتعديل بعض القطع المعدنية.","التأكد من سلامة أنظمة العادم (الشكمان) لتقليل الانبعاثات.","كتابة تقارير تفصيلية عن حالة المركبة واحتياجاتها من القطع."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (85, 'فني نظم حاسب آلي', '["تجميع وإصلاح أجهزة الكمبيوتر وتركيب قطع العتاد.","فحص وتغيير القطع التالفة مثل الذاكرة أو الأقراص الصلبة.","تركيب وتوصيل الشبكات السلكية واللاسلكية داخل المكاتب.","إجراء الصيانة الوقائية الدورية للأجهزة لضمان عدم توقفها.","إدارة طرفيات الحاسب (شاشات، لوحات مفاتيح) وضمان عملها.","إعداد وتكوين أجهزة التوجيه (Routers) والمبدلات (Switches).","تمديد وتركيب كابلات الشبكة (CAT6) وإنهاء أطرافها.","تنظيف الأجهزة من الداخل لضمان تهوية جيدة للمعالجات.","ترقية الأجهزة القديمة بقطع حديثة لزيادة سرعة الأداء.","تجهيز كبائن الشبكات (Racks) وتنظيم الكابلات بداخلها.","استكشاف مشاكل الطابعات المركزية وإصلاح أعطال الورق.","إعداد جرد دقيق لكافة الأجهزة والقطع التابعة للقسم."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (86, 'فني نظم معلومات', '["تشغيل قواعد البيانات وحماية أمن المعلومات التقنية.","إجراء النسخ الاحتياطي (Backup) للبيانات الحساسة بانتظام.","إدارة صلاحيات الوصول للمجلدات والملفات المشتركة.","مراقبة جدران الحماية (Firewalls) ومنع الاختراقات التقنية.","المساعدة في استعادة البيانات في حالات الفشل التقني.","مراقبة أداء الخوادم (Servers) والتأكد من استقرار عملها.","تحديث أنظمة التشغيل للخوادم وترقيع الثغرات الأمنية.","إنشاء وحذف حسابات البريد الإلكتروني للموظفين الجدد والمغادرين.","تقديم الدعم لنظام تخطيط موارد المؤسسة (ERP) وحل مشاكله.","إعداد وتكوين الشبكات الافتراضية الخاصة (VPN) للعمل عن بعد.","إعداد تقارير دورية حول استهلاك مساحات التخزين وموارد الشبكة.","المساهمة في وضع سياسات أمن المعلومات وتوعية الموظفين بها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (87, 'كاتب', '["تدوين المحاضر وصياغة الخطابات والمراسلات الرسمية.","مراجعة النصوص لغوياً والتأكد من صحة التعبير.","تلخيص التقارير الطويلة في نقاط مركزة للإدارة.","صياغة العقود البسيطة والنماذج الإدارية.","توثيق المراسلات الصادرة والواردة في سجلات خاصة.","كتابة مقالات ونشرات داخلية للتواصل مع الموظفين.","تفريغ التسجيلات الصوتية للاجتماعات إلى نصوص مكتوبة.","إعداد مسودات الكلمات والخطابات للمديرين في المناسبات.","ترجمة المراسلات القصيرة بين العربية واللغات الأخرى إن تطلب الأمر.","تحديث محتوى لوحات الإعلانات الداخلية للشركة بانتظام.","إدخال البيانات والمعلومات المكتوبة إلى قواعد البيانات.","الحفاظ على أرشيف مرتب للمسودات والمذكرات للرجوع إليها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (88, 'كاتب إداري عام', '["القيام بأعمال الكتابة والتوثيق لمختلف الأقسام واللجان.","معالجة وتدقيق المستندات الرسمية قبل اعتمادها.","توزيع المذكرات الداخلية على الموظفين المعنيين.","تحديث سجلات الصادر والوارد الرقمية بشكل يومي.","أرشفة ملفات الموظفين والوثائق التاريخية للمنشأة.","تصنيف المعاملات وتوجيهها إلى الإدارات المختصة.","طباعة الجداول الزمنية والتعاميم الإدارية الموحدة.","تجهيز ملفات التوظيف وعقود العمل الجديدة لتوقيعها.","الاحتفاظ بنسخ احتياطية من جميع القرارات الإدارية.","إعداد خطابات التعريف بالراتب وشهادات لمن يهمه الأمر.","مراجعة الفواتير الإدارية وتجميعها لإرسالها للحسابات.","استقبال المراجعين وتوجيههم وتزويدهم بالاستمارات اللازمة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (89, 'كاتب اتصال', '["إدارة المراسلات الواردة والصادرة وتوجيهها للجهات المعنية.","الرد على الاستفسارات العامة عبر البريد الرسمي.","التأكد من وصول الطرود والخطابات للجهات الخارجية.","التنسيق مع شركات الشحن والبريد السريع.","أرشفة إيصالات التسليم والاستلام للمراسلات.","فرز البريد اليومي الوارد حسب الإدارة أو الشخص المعني.","كتابة وتغليف الرسائل والطرود وتجهيزها للشحن.","متابعة مسار الشحنات الهامة باستخدام أرقام التتبع (Tracking).","توزيع البريد الداخلي على المكاتب بشكل منتظم يومياً.","إعداد كشف شهري بمصروفات البريد والشحن.","الرد السريع على رسائل الفاكس وتوجيهها فور وصولها.","التأكد من كتابة العناوين بدقة لتجنب ضياع المراسلات."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (90, 'كاتب اتصالات', '["متابعة سجلات المكالمات والبريد الإلكتروني والاتصال الرسمي.","تحويل المكالمات الهاتفية الدولية والمحلية للمختصين.","تسجيل المكالمات الواردة الهامة وإبلاغ المدير بمحتواها.","إدارة غرفة البدالة والسنترال الخاص بالشركة.","تقديم تقارير عن تكلفة الاتصالات الشهرية للأقسام.","الترحيب بالمتصلين باسم الشركة بأسلوب احترافي.","حفظ وتحديث دليل الهواتف الداخلية (التحويلات) لجميع الموظفين.","أخذ الرسائل الصوتية وتدوينها عند عدم تواجد الشخص المعني.","الإبلاغ عن أعطال شبكة الهواتف الداخلية للقسم التقني.","ترتيب المؤتمرات الهاتفية (Conference Calls) بين الأقسام.","توجيه المكالمات المزعجة أو التسويقية وإنهائها بلباقة.","التواصل عبر أجهزة اللاسلكي مع فرق الأمن والميدان عند الطوارئ."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (91, 'كاتب اختزال', '["تدوين النصوص والكلمات بسرعة كبيرة أثناء الاجتماعات والندوات.","تفريغ التسجيلات الصوتية للاجتماعات إلى نصوص مكتوبة.","ملاحقة المتحدثين في المؤتمرات لتدوين كل ما يقال بدقة.","إعداد مسودات فورية للقرارات أثناء انعقاد الجلسات.","حفظ السجلات المختزلة للرجوع إليها عند الحاجة للتدقيق.","استخدام آلات الاختزال أو لوحات المفاتيح السريعة بكفاءة.","تنقيح ومراجعة النصوص بعد تفريغها لتصحيح الأخطاء المطبعية.","صياغة المحاضر النهائية بلغة سليمة واعتمادها من المجتمعين.","ضمان السرية المطلقة للمعلومات الحساسة التي تم تدوينها.","التعرف على المصطلحات الفنية المحددة لمجال عمل الشركة.","فصل مداخلات المتحدثين المتعددين لضمان وضوح المحضر.","أرشفة التسجيلات الصوتية وربطها بالمحاضر المكتوبة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (92, 'كاتب ادارى عام', '["حفظ وتصنيف المستندات الورقية والإلكترونية في الأرشيف.","تسهيل عملية استرجاع الملفات القديمة للأقسام الطالبة.","التخلص من الملفات القديمة غير الهامة وفق سياسة الإتلاف.","ترقيم الملفات ووضع ملصقات تعريفية عليها في الأرشيف.","الحفاظ على سرية المستندات ومنع الاطلاع عليها لغير المخولين.","تحويل المستندات الورقية إلى نسخ رقمية (Scanning) بشكل يومي.","ترتيب سجلات الموظفين وإضافة أي مستندات جديدة إليها.","كتابة المسودات للمذكرات الداخلية البسيطة.","توزيع التعاميم الإدارية المطبوعة على لوحات الإعلانات.","متابعة توفر نماذج العمل الفارغة (طلب إجازة، عهدة) للأقسام.","المساعدة في تنسيق غرف الاجتماعات وترتيب الكراسي والأدوات.","تسجيل المعاملات الواردة من خارج الشركة برقم وتاريخ محدد."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (93, 'كاتب اداري', '["إعداد التقارير الإدارية البسيطة ومتابعة المعاملات.","ملء النماذج الإدارية الخاصة بالموظفين (طلب إجازة، عهدة).","متابعة سداد الفواتير الدورية (كهرباء، هاتف) للمكتب.","ترتيب المكتبة الإدارية الخاصة بالقسم.","المساعدة في تنظيم الدورات التدريبية داخل القسم.","استلام طلبات المشتريات البسيطة للقسم وتمريرها للاعتماد.","كتابة خطابات الشكر أو المراسلات الروتينية لعملاء القسم.","جدولة المواعيد الخاصة بمدير القسم وتنظيم روزنامته.","التأكد من توفر الضيافة والمياه في مكتب الاستقبال للقسم.","الإشراف على سجل استعارة الكتب أو الأدوات داخل الإدارة.","جمع التوقيعات اللازمة على المعاملات الإدارية اليومية.","تجهيز ملفات المراجعين قبل دخولهم لمقابلة المسؤول."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (94, 'كاتب اداري عام', '["معالجة البيانات المكتبية وتوزيع المهام الكتابية.","التأكد من توفر الأحبار والأوراق لجميع الطابعات في المكتب.","استقبال طلبات الصيانة المكتبية ومتابعتها.","تنظيم سجل الحضور والانصراف الورقي (في حال وجوده).","إعداد كشوف توزيع الرواتب أو البدلات البسيطة.","الإشراف على تصوير المستندات بأحجام كبيرة إن تطلب الأمر.","تدقيق المستندات للتأكد من خلوها من الأخطاء الإملائية.","تحديث لوحة الحضور والغياب اليومية لموظفي الإدارة.","استقبال وتوجيه عمال النظافة أو الصيانة لمناطق العمل.","تسليم الشيكات أو الخطابات للمندوبين الخارجيين.","مساعدة الإدارة في إعداد كشوف الجرد المكتبي.","تنظيم درج الملفات الشخصية للمكتب وسرعة استخراجها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (95, 'كاتب ادخال بيانات', '["نقل البيانات من المستندات الورقية إلى الأنظمة الحاسوبية.","تدقيق البيانات المدخلة للتأكد من خلوها من الأخطاء الرقمية.","تحديث قواعد بيانات العملاء أو المنتجات بانتظام.","إجراء مسح ضوئي (Scanning) للمستندات وربطها بالبيانات.","استخراج تقارير إحصائية بسيطة من البيانات المدخلة.","الالتزام بالسرعة والدقة العالية في الكتابة على لوحة المفاتيح.","حذف السجلات المكررة أو القديمة لتنظيف قاعدة البيانات.","تشفير وحماية البيانات الحساسة أثناء عملية الإدخال.","مراجعة الجداول البيانية ومطابقتها مع المصدر الأساسي.","اكتشاف وتصحيح الأخطاء المنطقية في البيانات الواردة.","التعامل مع برامج الجداول الإلكترونية مثل (Excel) بمهارة.","حفظ النسخ الاحتياطية للبيانات المدخلة في نهاية يوم العمل."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (96, 'كاتب استعلامات', '["الرد على استفسارات الزوار الأولية وتوجيههم.","استقبال المكالمات الهاتفية العامة والإجابة عليها.","شرح مواقع الأقسام في المبنى للزوار الجدد.","توزيع النماذج الأولية للتقديم على الخدمات.","تسجيل أسماء الزوار وتوقيت دخولهم وخروجهم.","إصدار بطاقات زائر (Visitor Badges) وتصاريح الدخول.","إرشاد الزوار لسياسات المنشأة كمنع التدخين أو التصوير.","الاحتفاظ بكتيبات معلوماتية عن خدمات الشركة لتوزيعها.","الحفاظ على منطقة الاستقبال نظيفة ومنظمة وهادئة.","التواصل مع الموظفين لإعلامهم بوصول ضيوفهم أو مراجعيهم.","التعامل بلباقة مع الزوار غير الراضين لامتصاص غضبهم.","إرشاد المتقدمين للوظائف عن كيفية تسليم سيرهم الذاتية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (97, 'كاتب استعلامات خدمة عملاء', '["تقديم معلومات تفصيلية عن الخدمات والمنتجات للعملاء.","شرح كيفية استخدام التطبيق الإلكتروني للعملاء.","الرد على الأسئلة المتعلقة بالأسعار وفترات الضمان.","معالجة طلبات تغيير البيانات الشخصية للعملاء.","توجيه العميل لأقرب فرع يقدم الخدمة المطلوبة.","التحقق من هوية العميل قبل تقديم أي بيانات عن حسابه.","تسجيل ملاحظات العملاء المباشرة في النظام لرفعها للإدارة.","إرسال نماذج الخدمة للعملاء عبر البريد الإلكتروني أو الواتساب.","التأكد من فهم العميل لكافة الشروط والأحكام الخاصة بالخدمة.","طباعة الفواتير أو كشوف الحساب السريعة للعملاء المراجعين.","مساعدة العملاء في تعبئة استمارات الاشتراك المعقدة.","توجيه العملاء الذين يحتاجون لحلول استثنائية للمدير المناوب."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (98, 'كاتب استعلامات مركز خدمة عملاء', '["العمل في مراكز الاتصال الهاتفية للرد على الأسئلة.","استخدام أنظمة الاتصال الحديثة لاستقبال الطلبات.","تسجيل بلاغات الأعطال الواردة من العملاء هاتفياً.","تحويل المكالمات المعقدة للمشرفين أو المختصين.","الالتزام بالنص (Script) الموحد للرد على العملاء.","التعامل مع ضغط المكالمات في أوقات الذروة باحترافية وسرعة.","التأكد من إغلاق التذاكر (Tickets) المفتوحة بعد حل المشكلة.","إجراء مكالمات صادرة لتقييم جودة الخدمة المقدمة للعميل.","تقديم الدعم الفني المبدئي لتخفيف الضغط على قسم الدعم.","تسجيل بيانات المتصلين الجدد لإنشاء ملف تعريفي لهم.","الحفاظ على سرية بيانات المتصلين وعدم إفشائها.","تحقيق مؤشرات الأداء (KPIs) المتعلقة بمدة المكالمة وسرعة الرد."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (99, 'كاتب استقبال خدمة عملاء', '["استقبال العملاء وتسجيل طلباتهم وتنسيق دخولهم.","توزيع أرقام الانتظار على العملاء في صالة الاستقبال.","التأكد من راحة العملاء في صالات الانتظار.","مراجعة الأوراق الثبوتية للعميل قبل توجيهه للموظف المختص.","إبلاغ العملاء بمواعيد العمل الرسمية وفترات الذروة.","تزويد العملاء بشبكة الواي فاي أو أدوات الضيافة في صالة الانتظار.","مراقبة شاشات أرقام الانتظار وتوجيه العميل للمكتب الصحيح.","فرز المراجعين حسب نوع الخدمة (سريعة، معقدة، شكاوى).","توفير استمارات التقديم و مساعدة العملاء في كتابتها.","الاعتذار للعملاء في حال وجود عطل تقني وإرشادهم للبدائل.","الإشراف على تنظيم الطوابير وتجنب التكدس في الفروع.","الإبلاغ فوراً عن أي حالات طوارئ أو إغماءات في صالة الجمهور."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (100, 'مساعد اداري', '["تنظيم وتنسيق المواعيد والاجتماعات اليومية للإدارة.","معالجة المراسلات الواردة والصادرة وتصنيفها حسب الأولوية.","إعداد المسودات والتقارير والوثائق الإدارية المطلوبة.","أرشفة الملفات والسجلات وضمان سهولة الوصول إليها عند الحاجة.","متابعة توفير المستلزمات المكتبية وضمان كفاءة سير العمل الإداري.","تدوين الملاحظات والقرارات أثناء اجتماعات الإدارة.","ترجمة بعض المراسلات البسيطة للمديرين.","إجراء حجوزات الطيران والفنادق لموظفي الإدارة.","متابعة إجراءات الصيانة الخاصة بأجهزة الإدارة.","الرد المبدئي على رسائل البريد الإلكتروني الخاصة بالمدير.","تنظيم وتحديث قاعدة بيانات جهات الاتصال الخاصة بالمنشأة.","استقبال فواتير الإدارة ومراجعتها قبل تسليمها للقسم المالي."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (101, 'مساعد إداري', '["تنظيم وتنسيق المواعيد والاجتماعات اليومية للإدارة.","معالجة المراسلات الواردة والصادرة وتصنيفها حسب الأولوية.","إعداد المسودات والتقارير والوثائق الإدارية المطلوبة.","أرشفة الملفات والسجلات وضمان سهولة الوصول إليها عند الحاجة.","متابعة توفير المستلزمات المكتبية وضمان كفاءة سير العمل الإداري.","تدوين الملاحظات والقرارات أثناء اجتماعات الإدارة.","استقبال الزوار والمراجعين وتوجيههم للأقسام المعنية بأسلوب مهني ولبق.","تحديث قاعدة بيانات جهات الاتصال الخاصة بالمنشأة بانتظام.","متابعة سير المعاملات الورقية بين الإدارات المختلفة لضمان عدم تأخرها.","ترتيب وتنظيم الملفات السرية للإدارة مع ضمان الخصوصية التامة.","إعداد تقارير المصروفات النثرية الخاصة بالمكتب وتسويتها شهرياً.","تحديث لوحات الإعلانات الداخلية بالقرارات أو التعاميم الجديدة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (102, 'مندوب مبيعات', '["البحث عن عملاء محتملين وفتح قنوات بيع جديدة للمنتجات.","إجراء الزيارات الميدانية والعروض التقديمية لإقناع العملاء بالشراء.","التفاوض على الأسعار وشروط البيع لإنهاء الصفقات بنجاح.","متابعة تحصيل المبالغ المالية من العملاء وفقاً للمواعيد المحددة.","إعداد تقارير دورية عن حالة السوق وحجم المبيعات المحققة.","توزيع كتالوجات المنتجات والعينات المجانية على العملاء المستهدفين.","بناء علاقة قوية ومستدامة مع أصحاب الشركات وتجار التجزئة.","دراسة نشاط المنافسين في السوق الميداني وتسجيل ملاحظات عن عروضهم.","معالجة شكاوى العملاء الميدانية وحلها فوراً للحفاظ على ولائهم.","تحديث قاعدة بيانات العملاء (CRM) بعد كل زيارة ميدانية.","تنفيذ استراتيجيات البيع المتقاطع (Cross-Selling) لزيادة حجم الصفقة.","تحقيق أهداف المبيعات (الـ Target) المحددة من الإدارة شهرياً."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (103, 'مندوب مشتريات', '["البحث عن موردين جدد وتقييم قدرتهم على تلبية احتياجات المنشأة.","استلام طلبات الشراء من الأقسام ومطابقتها مع الميزانية المعتمدة.","التفاوض مع الموردين للحصول على أفضل الأسعار والجداول الزمنية للتسليم.","متابعة أوامر الشراء المفتوحة وضمان وصول البضائع في وقتها.","فحص العينات الموردة للتأكد من مطابقة المواصفات الفنية المطلوبة.","التواجد في الأسواق ميدانياً للبحث عن عروض وأسعار أفضل.","تخليص وإنهاء الإجراءات الجمركية للبضائع المستوردة عند الحاجة.","شراء الاحتياجات العاجلة نقداً من الأسواق المحلية.","تسليم البضائع المستلمة إلى أمين المخزن مع فواتير الموردين.","المحافظة على السلفة المالية المؤقتة وتسويتها بانتظام مع المالية.","إجراء مقارنات سريعة للأسعار (Quotations) للمشتريات اليومية.","إرجاع البضائع غير المطابقة للمواصفات للمورد واستبدالها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (104, 'مراقب عام', '["الإشراف الميداني على سير العمل في المواقع أو الأقسام المختلفة.","التأكد من التزام الموظفين بالسياسات والإجراءات ومعايير السلامة.","رصد أي مخالفات أو قصور في الأداء ورفع تقارير فورية بها.","التنسيق بين الإدارة والعمال لضمان تنفيذ المهام وفق الجدول الزمني.","مراقبة استخدام الموارد والمعدات لمنع الهدر أو سوء الاستخدام.","القيام بجولات تفتيشية يومية لجميع مرافق المنشأة لتسجيل الملاحظات.","التأكد من جودة النظافة والصيانة في الممرات والساحات ومناطق العمل.","الإشراف على حضور وانصراف العمالة الميدانية وتسجيل تأخيراتهم.","حل النزاعات الميدانية البسيطة بين العمال لتجنب تعطل العمل.","التأكد من ارتداء جميع العمال للزي الرسمي ومعدات الوقاية.","رفع تقرير يومي شامل للمدير المباشر عن حالة الموقع وأي عقبات.","تنظيم حركة دخول وخروج شاحنات ومعدات الموردين في ساحات العمل."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (105, 'اخصائي استقدام', '["التنسيق مع مكاتب الاستقدام الخارجية لجذب العمالة المطلوبة.","متابعة استخراج التأشيرات وتذاكر السفر وإنهاء الإجراءات القنصلية.","التأكد من مطابقة مهارات العمالة المستقدمة للمواصفات المطلوبة.","إدارة عمليات استقبال العمالة الجديدة وتوفير السكن والتهيئة.","متابعة تجديد العقود والإقامات للعمالة الوافدة مع الجهات المختصة.","إجراء المقابلات الافتراضية مع المرشحين بالخارج لتقييمهم مبدئياً.","مراجعة عقود العمل الدولية وضمان توافقها مع قوانين الدولة.","حل المشاكل العمالية المتعلقة بالوافدين مع مكاتب الاستقدام.","التنسيق لإجراء الفحوصات الطبية واستخراج رخص العمل فور الوصول.","إعداد تقارير دورية حول تكاليف الاستقدام ومدد الوصول المتوقعة.","تنظيم إجراءات تسفير العمالة المنتهي عقودها أو المستقيلة.","بناء علاقات مع وكالات توظيف دولية موثوقة لضمان جودة العمالة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (106, 'امين مخزن', '["استلام الشحنات الواردة ومطابقتها مع أوامر الشراء والمواصفات.","تنظيم وترتيب البضائع داخل المخزن بشكل يسهل الوصول إليها.","صرف المواد للأقسام بناءً على أذونات صرف معتمدة وموثقة.","إجراء الجرد الدوري للمخزون والتأكد من مطابقة الرصيد الفعلي للدفتري.","مراقبة صلاحية المنتجات وظروف التخزين لضمان سلامتها.","استخدام رافعات الشوكة (Forklift) اليدوية أو الآلية لنقل البليتات.","تحديث السجلات المخزنية أو برامج (ERP) فورياً بعد كل حركة.","المحافظة على نظافة المستودع وخلو ممراته من العوائق والمخلفات.","تجميع وتغليف الطلبيات الصادرة وتجهيزها للتحميل.","الإبلاغ الفوري للإدارة عند وصول كميات أصناف معينة لحد الخطر.","فرز المرتجعات وتصنيفها كـ (صالحة) أو (تالفة) تمهيداً لمعالجتها.","التأكد من إغلاق المستودع وتأمينه وإطفاء الأنوار بعد انتهاء الدوام."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (107, 'مترجم', '["ترجمة الوثائق والخطابات والتقارير من لغة إلى أخرى بدقة.","القيام بالترجمة الشفهية (الفورية أو التتبعية) في الاجتماعات.","مراجعة النصوص المترجمة للتأكد من ملاءمتها للسياق الثقافي.","توحيد المصطلحات الفنية المستخدمة داخل المنشأة في كافة اللغات.","المساعدة في ترجمة المحتوى الرقمي والمواقع الإلكترونية للشركة.","ترجمة العقود القانونية مع الحفاظ على دقة المعنى والمصطلح.","إنشاء وتحديث مسرد (Glossary) بالمصطلحات الخاصة بصناعة الشركة.","التأكد من خلو النصوص المترجمة من الأخطاء النحوية والإملائية.","تنسيق الوثيقة المترجمة لتطابق التصميم الأصلي (Desktop Publishing).","السرعة في إنجاز الترجمات العاجلة للقرارات أو الأخبار الصحفية.","مرافقة الوفود الأجنبية لتسهيل التواصل المباشر أثناء الزيارات الميدانية.","ضمان السرية المطلقة للمستندات والمعلومات التي يتم ترجمتها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (108, 'مهندس', '["تصميم وتطوير المخططات الهندسية والمواصفات الفنية للمشاريع.","الإشراف الميداني على تنفيذ الأعمال لضمان مطابقتها للأكواد.","إجراء الحسابات الفنية وتقدير الكميات والتكاليف اللازمة.","حل المشكلات التقنية التي تظهر أثناء مرحلة الإنشاء أو التشغيل.","التأكد من تطبيق معايير الجودة والسلامة المهنية في مراحل العمل.","اعتماد المواد الموردة للموقع والتأكد من مطابقتها للمواصفات القياسية.","إعداد التقارير الفنية الدورية لرفعها لاستشاري أو مالك المشروع.","عقد اجتماعات تنسيقية بين تخصصات (المدني، المعماري، الميكانيكا، الكهرباء).","مراجعة الرسومات التنفيذية (Shop Drawings) واعتمادها قبل التنفيذ.","استخدام البرامج الهندسية الحديثة مثل (Revit, AutoCAD, SAP2000).","إدارة وتوجيه فرق العمل من فنيين وعمال لضمان كفاءة الإنتاجية.","اعتماد المستخلصات المالية للمقاولين بناءً على نسب الإنجاز الفعلية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (109, 'محاسب', '["تسجيل وإثبات القيود والعمليات المالية اليومية في السجلات المحاسبية.","إعداد القوائم المالية (الدخل، المركز المالي) في نهاية الفترة.","متابعة الحسابات المدينة والدائنة وضمان تسوية المطالبات في موعدها.","مراجعة وتدقيق الفواتير والمستندات المالية لضمان صحتها.","إعداد التقارير الضريبية والزكوية وضمان الالتزام بالأنظمة المالية.","إعداد مسيرات رواتب الموظفين ومراجعة الخصومات والبدلات.","تسوية الحسابات البنكية (Bank Reconciliations) بشكل شهري.","مراقبة التدفقات النقدية (Cash Flow) وإعداد التوقعات المستقبلية.","جرد الأصول الثابتة وحساب إهلاكاتها الدفترية سنوياً.","المشاركة في عمليات جرد المخزون وتقييم التكلفة بانتظام.","التعاون المباشر مع مراجع الحسابات الخارجي (المدقق القانوني).","التحقق من صحة العهد المالية المؤقتة وتسويتها مع الموظفين."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (110, 'كاتب مراسلات', '["استلام وتوجيه المراسلات الواردة والصادرة للجهات المعنية.","فرز البريد اليومي وتوزيعه على الأقسام المختلفة.","أرشفة الخطابات والمستندات الرسمية لسهولة الرجوع إليها.","متابعة تسليم البريد والطرود والتأكد من استلامها.","إعداد تقارير دورية بحركة المراسلات الصادرة والواردة.","الرد على الاستفسارات المتعلقة بحالة البريد والمعاملات.","تحديث السجلات الإلكترونية الخاصة بالبريد والصادرات بانتظام.","التنسيق مع شركات الشحن والبريد السريع لتسليم الطرود الهامة.","صياغة الردود الروتينية والمذكرات الداخلية نيابة عن الإدارة.","الحفاظ على سرية المراسلات والمعلومات الخاصة بالشركة.","مراجعة وتدقيق العناوين البريدية لضمان وصول الرسائل للوجهة الصحيحة.","طلب وتوفير مستلزمات التغليف والقرطاسية الخاصة بقسم المراسلات."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (111, 'محصل', '["متابعة وتحصيل المديونيات المستحقة على العملاء في مواعيدها.","إصدار سندات القبض وتسليمها للعملاء عند التحصيل.","تسوية المبالغ المحصلة مع الإدارة المالية بانتظام.","التواصل مع العملاء المتأخرين عن السداد وتذكيرهم بالمطالبات.","إعداد تقارير دورية بالمبالغ المحصلة والمتأخرات.","تحديث سجلات العملاء وحالة حساباتهم بعد كل عملية تحصيل.","جدولة الزيارات الميدانية للعملاء لضمان سير عملية التحصيل بفعالية.","التفاوض مع العملاء لجدولة الديون أو إيجاد خطط سداد بديلة عند التعثر.","إيداع المبالغ النقدية والشيكات المحصلة في الحسابات البنكية للشركة.","تصنيف الديون المعدومة والمشكوك في تحصيلها ورفعها للإدارة.","التعاون مع الإدارة القانونية لاتخاذ الإجراءات اللازمة ضد المتهربين.","مطابقة كشوف الحسابات مع العملاء لحل أي تباينات أو أخطاء في الرصيد."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (112, 'كاتب موارد بشرية', '["إعداد وتحديث ملفات الموظفين الورقية والإلكترونية بانتظام.","متابعة عمليات تسجيل حضور وانصراف الموظفين يومياً.","إعداد مسودات عقود العمل للموظفين الجدد ورفعها للاعتماد.","تسجيل الإجازات والمغادرات في نظام الموارد البشرية.","المساعدة في فرز السير الذاتية وتحديد مواعيد المقابلات.","تجهيز خطابات التعريف بالراتب وشهادات لمن يهمه الأمر.","توثيق وتسجيل الإقرارات والعهد المستلمة من الموظفين.","متابعة انتهاء عقود العمل وتنبيه الإدارة لتجديدها.","أرشفة تقييمات الأداء السنوية لجميع العاملين في المنشأة.","الإجابة على استفسارات الموظفين المتعلقة بالسياسات الإدارية.","المساعدة في إعداد مسيرات الرواتب وتدقيق الخصومات.","متابعة تجديد الإقامات والتأمين الطبي للعمالة الوافدة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (113, 'موظف استقبال', '["الترحيب بالزوار والمراجعين بمهنية وتوجيههم إلى الأقسام المعنية.","الرد على المكالمات الهاتفية الواردة وتحويلها للأشخاص المناسبين.","تسجيل بيانات الزوار وتوقيتات دخولهم وخروجهم في السجلات المخصصة.","استلام البريد والطرود اليومية وتوزيعها على مكاتب الموظفين.","الحفاظ على نظافة وترتيب منطقة الاستقبال بشكل دائم.","تقديم المعلومات الأساسية للعملاء حول خدمات الشركة ومواعيد العمل.","إدارة وحجز غرف الاجتماعات والتأكد من جاهزيتها قبل المواعيد.","المساعدة في المهام الإدارية البسيطة مثل تصوير المستندات والطباعة.","إصدار وتوزيع تصاريح أو بطاقات الدخول للزوار.","التعامل مع الشكاوى الأولية للزوار وتوجيهها للإدارة المختصة.","تحديث أدلة الهواتف الداخلية وبيانات الاتصال الخاصة بالموظفين.","مراقبة سجلات الحضور والانصراف في منطقة الاستقبال إن تطلب الأمر."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (114, 'مدخل بيانات', '["إدخال البيانات النصية والرقمية بدقة وسرعة في أنظمة الشركة.","مراجعة وتدقيق البيانات المدخلة لاكتشاف أي أخطاء مطبعية وتصحيحها.","تحديث السجلات وقواعد البيانات الحالية بمعلومات جديدة.","أرشفة وحفظ المستندات الورقية في ملفات منظمة بعد الانتهاء من إدخالها.","استخراج تقارير دورية مبسطة بناءً على البيانات المدخلة في النظام.","عمل نسخ احتياطية للبيانات لضمان عدم ضياعها.","الالتزام التام بسرية المعلومات والبيانات الخاصة بالشركة والعملاء.","استخدام برامج الجداول الإلكترونية لتصنيف وتنظيم البيانات المعقدة.","إجراء المسح الضوئي للمستندات الورقية وتحويلها إلى صيغ رقمية.","التواصل مع الأقسام المعنية لاستكمال البيانات الناقصة أو غير الواضحة في النماذج.","تنظيف قواعد البيانات بحذف السجلات المكررة أو القديمة.","الاستجابة السريعة لطلبات الإدارة في استرجاع معلومات محددة من النظام."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (115, 'مدير تطوير موارد بشرية', '["وضع الخطط الاستراتيجية لتطوير كفاءات ومهارات الموظفين في المنشأة.","تحليل الاحتياجات التدريبية لجميع الأقسام وتصميم برامج ملائمة.","تقييم أداء الموظفين دورياً وربط النتائج بخطط التطوير والتحسين.","إدارة ميزانية التدريب السنوية والتأكد من استغلالها بكفاءة عالية.","تصميم مسارات التطور الوظيفي للموظفين المتميزين للاحتفاظ بهم.","الإشراف على برامج التوجيه والتهيئة الشاملة للموظفين الجدد.","بناء شراكات مع مراكز تدريب ومؤسسات تعليمية خارجية.","قياس العائد على الاستثمار من البرامج التدريبية المنفذة.","تطوير سياسات الاحتفاظ بالكفاءات والمواهب وتقليل معدلات الدوران.","تعزيز ثقافة التعلم المستمر وبيئة العمل الإيجابية في المؤسسة.","تقديم المشورة للإدارة العليا حول برامج الإحلال والتعاقب الوظيفي.","إعداد تقارير شاملة حول تقدم خطط التطوير ورفعها للإدارة التنفيذية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (116, 'كاتب بيانات عملاء', '["جمع بيانات العملاء الجدد وإدخالها في نظام إدارة علاقات العملاء بدقة.","تحديث المعلومات الشخصية وبيانات الاتصال الخاصة بالعملاء الحاليين بشكل دوري.","التحقق من صحة واكتمال المستندات المرفقة بملفات العملاء.","تصنيف العملاء في قواعد البيانات بناءً على فئات محددة (أفراد، شركات، إلخ).","دمج أو حذف الحسابات المكررة لضمان دقة قاعدة البيانات ونظافتها.","الحفاظ على سرية وخصوصية بيانات العملاء وفقاً للسياسات المعتمدة.","استخراج قوائم بيانات العملاء المستهدفة لدعم حملات التسويق والمبيعات.","الرد على استفسارات الأقسام الأخرى المتعلقة بسجلات وملفات العملاء.","معالجة طلبات العملاء بتعديل أو حذف بياناتهم الشخصية من النظام.","إجراء مسح ضوئي لهويات ومستندات العملاء وحفظها إلكترونياً بالملف المخصص.","مراجعة العقود والنماذج الموقعة للتأكد من مطابقتها للبيانات المدخلة بالنظام.","إعداد تقارير إحصائية دورية عن حجم نمو أعداد العملاء الجدد."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (117, 'كاتب حسابات', '["تسجيل القيود اليومية والمصروفات والإيرادات في الدفاتر المحاسبية.","مراجعة وتدقيق الفواتير الواردة من الموردين قبل تمريرها للدفع.","إصدار فواتير المبيعات للعملاء ومتابعة تسليمها.","مطابقة الأرصدة النقدية اليومية مع السجلات الدفترية والخزينة.","أرشفة وحفظ المستندات المالية (فواتير، سندات قبض، سندات صرف) بانتظام.","المساعدة في إعداد التسويات البنكية الشهرية ومطابقة كشوف الحساب.","متابعة حسابات الذمم الدائنة والمدينة وتسجيل الحركات عليها.","إعداد كشوف حسابات العملاء والموردين عند الطلب للتدقيق.","المشاركة في عمليات الجرد الدوري للمخزون أو الأصول الثابتة.","تسجيل ومتابعة السلف النثرية الخاصة بالموظفين وتصفيتها دورياً.","المساعدة في تجهيز البيانات اللازمة لإعداد القوائم المالية الختامية.","إدخال البيانات المالية وتحديثها في البرامج المحاسبية الإلكترونية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (118, 'كاتب رواتب', '["تجميع ومراجعة سجلات الحضور والانصراف وساعات العمل الإضافي.","إدخال بيانات الرواتب للموظفين الجدد في نظام الأجور المعتمد.","احتساب الخصومات والبدلات والمكافآت الشهرية للموظفين بدقة.","إعداد مسيرات الرواتب الشهرية ومراجعتها قبل الاعتماد النهائي.","تحديث ملفات الموظفين بأي تغييرات في الرواتب الأساسية أو الترقيات.","احتساب مستحقات نهاية الخدمة وتصفية حسابات الموظفين المغادرين.","الرد على استفسارات الموظفين المتعلقة بتفاصيل الراتب أو الخصومات بشكل سري.","إصدار خطابات ومفردات الراتب (Payslips) للموظفين عند الطلب.","تنسيق ومراجعة ملفات تحويل الرواتب مع البنوك المعتمدة للشركة.","متابعة استقطاعات القروض أو السلف وتسويتها من الراتب الشهري.","إعداد تقارير دورية حول تكاليف الرواتب والأجور لرفعها للإدارة المالية.","الحفاظ المطلق على سرية بيانات الرواتب والمعلومات المالية للموظفين."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (119, 'مدير تخطيط قوى عاملة', '["تحليل الوضع الحالي للقوى العاملة وتحديد الفجوات المستقبلية.","التنبؤ باحتياجات الشركة من الموظفين بناءً على خطط التوسع والنمو السنوية.","تصميم هياكل تنظيمية فعالة ومرنة تتناسب مع أهداف المؤسسة.","تحليل معدلات الدوران الوظيفي ووضع استراتيجيات جذرية للحد منها.","إعداد الميزانية التقديرية السنوية الخاصة بالتوظيف والأجور والمزايا.","تطوير خطط التعاقب الوظيفي لضمان استمرارية العمل في المناصب القيادية.","دراسة وتحليل سوق العمل الخارجي وتأثيره على توفر الكفاءات والمواهب.","التعاون المستمر مع مديري الأقسام لفهم متطلباتهم التشغيلية من الموظفين.","إعداد تقارير إحصائية تحليلية حول إنتاجية وتوزيع القوى العاملة.","وضع خطط إعادة الهيكلة أو تدوير الموظفين عند الحاجة لرفع الكفاءة.","الإشراف على تطوير التوصيفات الوظيفية لتناسب متطلبات وتحديثات كل دور.","استخدام برامج وتقنيات تحليل البيانات لدعم قرارات تخطيط الموارد البشرية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (120, 'مدير مكتب', '["الإشراف الشامل على العمليات الإدارية اليومية في المكتب لضمان سيرها بسلاسة.","إدارة وتوجيه طاقم الدعم الإداري (السكرتارية، الاستقبال، المراسلات).","متابعة عقود الصيانة الدورية للأجهزة والمرافق والخدمات داخل المكتب.","إدارة ميزانية المصروفات النثرية المكتبية والتحكم في التكاليف.","تنظيم وترتيب جداول اجتماعات الإدارة العليا وتجهيز متطلباتها وتدوين محاضرها.","التأكد من توفر جميع المستلزمات والقرطاسية المكتبية وطلب النواقص.","تطبيق سياسات الأمن والسلامة المهنية داخل بيئة العمل المكتبي.","إدارة نظام الأرشفة الورقي والإلكتروني للملفات الإدارية الهامة والسرية.","تنظيم الفعاليات الداخلية للموظفين وورش العمل والمناسبات الخاصة بالشركة.","استقبال كبار الزوار وتنسيق ترتيبات الضيافة والإقامة والسفر لهم.","التعامل مع شكاوى ومقترحات الموظفين المتعلقة ببيئة ومرافق العمل.","صياغة وتوزيع التعاميم والقرارات الإدارية الداخلية المعتمدة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (121, 'مدير مالي', '["التخطيط المالي الاستراتيجي وتحديد الأهداف المالية طويلة وقصيرة الأجل.","إعداد وإدارة الموازنات التقديرية السنوية للشركة والأقسام المختلفة.","الإشراف على إعداد القوائم والتقارير المالية الدورية والختامية.","إدارة ومراقبة التدفقات النقدية لضمان توفر السيولة اللازمة للتشغيل.","تحليل الأداء المالي للشركة وتقديم توصيات للإدارة التنفيذية لزيادة الربحية.","تقييم وإدارة المخاطر المالية التي قد تواجه المؤسسة ووضع خطط وقائية.","الإشراف على عمليات التدقيق الداخلي والتنسيق مع مراجعي الحسابات الخارجيين.","تطوير السياسات والإجراءات المحاسبية لضمان الرقابة المالية الصارمة.","إدارة المحافظ الاستثمارية للشركة وتوجيه الفوائض المالية بشكل آمن ومربح.","التفاوض مع البنوك والمؤسسات المالية للحصول على التسهيلات والقروض.","التأكد من التزام الشركة التام بالقوانين واللوائح الضريبية والمالية الحكومية.","قيادة وتطوير وتقييم فريق العمل في الإدارة المالية والمحاسبية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (122, 'مدير إداري', '["الإشراف العام على العمليات الإدارية اليومية للمنشأة وضمان سيرها بكفاءة.","إدارة طاقم الدعم الإداري والمكتبي، وتوزيع المهام، ومتابعة وتقييم أدائهم.","وضع وتحديث السياسات والإجراءات الإدارية الداخلية لضمان الانضباط المؤسسي.","متابعة عقود النظافة والصيانة والخدمات العامة للمبنى والمرافق مع المقاولين.","إدارة ميزانية الشؤون الإدارية ومراقبة وتخفيض النفقات التشغيلية للمكتب.","تنظيم وترتيب الاحتياجات اللوجستية للشركة من أثاث، وقرطاسية، وأجهزة مكتبية.","إدارة أسطول السيارات الخاص بالمنشأة وتنسيق حركتها، واستهلاكها، وصيانتها.","الإشراف على إدارة أمن المنشأة وتنظيم سياسات الدخول والخروج.","متابعة تجديد العقود الإدارية، والإيجارات، والتراخيص الخاصة بمقرات وفروع الشركة.","إعداد تقارير دورية للإدارة العليا عن سير العمل الإداري وأبرز المعوقات التشغيلية.","التنسيق لإقامة الفعاليات الداخلية للموظفين والمناسبات الرسمية لتعزيز الترابط.","معالجة شكاوى الموظفين المتعلقة ببيئة العمل، والمرافق، والخدمات المقدمة لهم."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (123, 'أخصائي تخطيط قوى عاملة', '["جمع وتحليل البيانات الديموغرافية والوظيفية لجميع موظفي الشركة.","تحديث ومراجعة الهياكل التنظيمية للأقسام بشكل دوري استجابة للتغييرات.","إعداد دراسات قياس عبء العمل لتحديد الاحتياج الفعلي للعمالة.","تصميم وتحديث بطاقات الوصف الوظيفي لجميع الوظائف لتعكس المهام الدقيقة.","المشاركة في إعداد خطط التوظيف السنوية بالتنسيق المباشر مع مديري الإدارات.","تتبع وتحليل مؤشرات الأداء الخاصة بالموارد البشرية مثل معدلات الدوران والغياب.","إجراء مقارنات معيارية لممارسات القوى العاملة في الشركة مع معايير السوق.","المساهمة في وضع خطط الإحلال والتعاقب للمناصب الحيوية والقيادية.","إعداد تقارير شهرية حول نسب الشواغر، تكلفة العمالة، والإنتاجية.","اقتراح حلول لسد الفجوات في المهارات من خلال التوظيف أو إعادة توزيع المهام.","إدارة البيانات الخاصة بالتخطيط ضمن نظام معلومات الموارد البشرية.","تقديم الدعم التحليلي في مشاريع إعادة هيكلة الأقسام التقنية أو الإدارية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (124, 'أخصائي أداء مؤسسي', '["تصميم وتطوير مؤشرات الأداء الرئيسية (KPIs) المتوائمة مع استراتيجية الشركة.","جمع وتحليل بيانات الأداء الدورية من مختلف الإدارات التشغيلية والداعمة.","متابعة تنفيذ الخطة الاستراتيجية للشركة والتأكد من تقدم الإدارات نحو أهدافها.","إعداد تقارير ولوحات قيادة تفاعلية لعرض مستويات الأداء للإدارة العليا.","تحديد الفجوات في الأداء التشغيلي واقتراح خطط تصحيحية ومبادرات تطوير.","عقد ورش عمل لتدريب المديرين على كيفية قياس وتقييم أداء فرق عملهم.","إدارة وتنسيق دورة تقييم الأداء السنوي للموظفين ومراجعة وتحليل النتائج.","إجراء مقارنات معيارية مع أفضل الممارسات في السوق لتحسين الأداء الداخلي.","مراجعة وتحسين إجراءات وتدفقات العمل الداخلي لتقليل الهدر ورفع الكفاءة.","التنسيق لربط نتائج تقييم الأداء المؤسسي ببرامج المكافآت والحوافز والترقيات.","توثيق قصص النجاح والمبادرات الاستراتيجية المنفذة لنشر ثقافة التميز.","إدارة برامج إدارة التغيير لضمان تقبل الموظفين لأنظمة التقييم والقياس الجديدة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (125, 'مشرف مكتب', '["الإشراف المباشر على الموظفين الإداريين وتوزيع المهام اليومية عليهم بفعالية.","مراقبة التزام طاقم المكتب بمواعيد الحضور والانصراف والسياسات الداخلية.","التأكد من جاهزية قاعات الاجتماعات ونظافة وترتيب المكاتب يومياً قبل بدء العمل.","جرد العهد المكتبية والقرطاسية ورفع طلبات الشراء للإدارة قبل نفاذ المخزون.","تدريب الموظفين الإداريين وموظفي الاستقبال الجدد وتوجيههم في مهامهم.","مراجعة وتدقيق المراسلات والتقارير الإدارية الأولية قبل توجيهها للجهات المعنية.","استقبال وتنظيم الشكاوى أو طلبات الصيانة المتعلقة ببيئة العمل ومتابعة تنفيذها.","ترتيب وتنظيم نظام الأرشفة اليومي والتأكد من حفظ المستندات بالملفات الصحيحة.","تنسيق ومتابعة عمليات استلام وتسليم البريد والطرود الهامة لضمان عدم ضياعها.","إعداد تقرير أسبوعي لمدير المكتب عن سير العمل المكتبي والمشاكل التي تم حلها.","الموافقة المبدئية على الإجازات القصيرة وتوزيع النوبات لطاقم الدعم الإداري.","ضمان تقديم مستوى عالٍ من خدمة العملاء والدعم للزوار الداخليين والخارجيين للمكتب."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (126, 'موظف علاقات عامه', '["صياغة وتوزيع البيانات الصحفية والأخبار الخاصة بالشركة لوسائل الإعلام المختلفة.","المساعدة في تنظيم وإدارة المؤتمرات والفعاليات والندوات الخاصة بالمنشأة.","إدارة حسابات الشركة على منصات التواصل الاجتماعي والتفاعل الإيجابي مع الجمهور.","بناء شبكة علاقات قوية مع الصحفيين، والإعلاميين، والمؤثرين في الصناعة.","مراقبة التغطية الإعلامية للشركة وإعداد تقارير تحليلية حول صورتها الذهنية بالسوق.","إعداد وتصميم المحتوى الإعلامي والنشرات الداخلية لتواصل فعال مع الموظفين.","المساهمة في إدارة الأزمات الإعلامية والمشاركة في الرد السريع على الشائعات.","تمثيل الشركة بمهنية في المعارض التجارية والمناسبات المجتمعية.","تنفيذ وتنسيق برامج ومبادرات المسؤولية المجتمعية للشركات المعتمدة.","تنظيم جولات وزيارات الوفود الرسمية وكبار الشخصيات لمرافق ومواقع الشركة.","مراجعة وتحديث المحتوى التعريفي للشركة على الموقع الإلكتروني والكتيبات التسويقية.","التنسيق مع وكالات الدعاية والإعلان لضمان توحيد وتوافق الرسالة الإعلامية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (127, 'كاتب علاقات حكومية (مندوب تعقيب)', '["استلام ومراجعة مستندات الموظفين الخاصة بتجديد الإقامات، جوازات السفر، والتأشيرات.","إدخال البيانات وتحديث السجلات في البوابات الحكومية الإلكترونية المخصصة للشركات.","إعداد وتجهيز النماذج والاستمارات الورقية بدقة لتقديمها للجهات الرسمية المختلفة.","أرشفة وحفظ التراخيص، السجلات التجارية، وتصاريح العمل في ملفات يسهل الوصول إليها.","متابعة تواريخ انتهاء المستندات الحكومية للشركة وتنبيه الإدارة مبكراً قبل انتهائها.","تدوين وسداد الرسوم والمخالفات الحكومية ومتابعة الفواتير لاستردادها من الإدارة المالية.","المتابعة الميدانية للمعاملات المعلقة مع الوزارات (مثل وزارة العمل والجوازات والبلديات).","طباعة التأشيرات وخطابات الدعوة للزوار الأجانب وترتيبها في ملفات المنشأة.","استخراج التقارير وكشوف البيانات الرسمية من الأنظمة الحكومية عند الحاجة.","تصديق الوثائق والشهادات والعقود من الغرف التجارية، وزارة الخارجية، والسفارات.","الحفاظ الصارم على سرية المستندات والوثائق الرسمية الخاصة بالشركة وبالموظفين.","ترتيب وجدولة المواعيد للمراجعات الميدانية للجهات الحكومية عند اللزوم لإنهاء المعاملات."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (128, 'كاتب علاقات حكومية', '["إعداد وتجهيز النماذج والاستمارات الورقية أو الإلكترونية الخاصة بالجهات الحكومية (مثل وزارة العمل، والجوازات، والبلدية).","إدخال وتحديث بيانات الشركة والموظفين عبر البوابات والمنصات الحكومية الإلكترونية.","إنشاء ومتابعة جدول زمني لتواريخ انتهاء التراخيص، والسجلات التجارية، وإقامات الموظفين لتنبيه الإدارة قبل انتهائها بوقت كافٍ.","استلام جوازات السفر والإقامات والوثائق الرسمية من الموظفين لتجديدها، وإعادة تسليمها لهم بعد الانتهاء.","أرشفة وتنظيم جميع المعاملات، والمستندات، والمراسلات الحكومية في ملفات آمنة يسهل الرجوع إليها.","تجهيز خطابات التفويض والوكالات الرسمية وتصديقها من الغرفة التجارية أو الجهات المعنية.","متابعة تسديد الرسوم والمخالفات الحكومية المتعلقة بتجديد الرخص والتأشيرات وإعداد كشوفات بها للإدارة المالية.","استخراج وطباعة التأشيرات الجديدة، وتأشيرات الخروج والعودة، والخروج النهائي للموظفين.","التنسيق المستمر مع المعقبين الميدانيين أو مكاتب الخدمات العامة لمتابعة حالة المعاملات التي تتطلب حضوراً شخصياً.","متابعة التعاميم والقرارات الحكومية الجديدة الصادرة، ورفع ملخص بها للإدارة لتوضيح تأثيرها على إجراءات الشركة.","إعداد تقارير دورية (أسبوعية أو شهرية) توضح حالة المعاملات المنجزة والمعاملات التي لا تزال قيد الإجراء.","الالتزام التام بالمحافظة على سرية المستندات والبيانات الشخصية الخاصة بالشركة وبجميع العاملين فيها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (129, 'كاتب إنتاج', '["تسجيل كميات الإنتاج اليومية من خطوط التصنيع في السجلات أو الأنظمة.","إعداد تقارير يومية عن حجم الإنتاج الفعلي ومقارنته بالمستهدف.","حصر وتسجيل المواد الخام المستهلكة في عمليات التصنيع.","توثيق وتسجيل أوقات التوقف (Downtime) لأي ماكينة وأسباب ذلك.","متابعة طلبات صرف المواد من المخازن لضمان استمرارية خطوط الإنتاج دون توقف.","إدخال بيانات المنتجات التالفة أو المعيبة (Scrap) ورفعها لإدارة الجودة.","طباعة وتوزيع أوامر الشغل (Work Orders) على العمال ومشرفي خطوط الإنتاج.","أرشفة سجلات ونماذج الإنتاج الورقية لتسهيل الرجوع إليها عند التدقيق.","التنسيق مع قسم الصيانة لتسجيل بلاغات الأعطال الواردة من مشرفي الإنتاج.","إعداد ملصقات المنتجات وتتبع الباركود الخاص بكل تشغيلة (Batch).","مراجعة كشوف حضور وغياب عمال الإنتاج ورفعها لشؤون الموظفين.","المساعدة في إعداد جداول تسليم المنتجات النهائية لقسم المستودعات."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (130, 'كاتب تدقيق بيانات', '["مراجعة البيانات المدخلة في النظام ومطابقتها مع المستندات الورقية الأصلية.","تصحيح الأخطاء المطبعية أو الإملائية أو الرقمية في قواعد البيانات.","التحقق من اكتمال كافة الحقول المطلوبة في النماذج والاستمارات قبل حفظها.","اكتشاف السجلات المكررة ودمجها أو حذفها لتنظيف قاعدة البيانات.","التواصل مع الأقسام المختلفة لاستكمال المعلومات الناقصة أو غير الواضحة.","مطابقة الأرقام المالية أو الإحصائية للتأكد من صحة العمليات الحسابية المرفوعة.","إعداد تقارير دورية بالأخطاء الشائعة في إدخال البيانات لرفع وعي الموظفين وتقليل الأخطاء.","تطبيق سياسات ومعايير الجودة الخاصة بالشركة أثناء معالجة وحفظ البيانات.","أرشفة المستندات المدققة ووضع ختم أو علامة \\"تمت المراجعة\\" عليها.","التأكد من توافق البيانات المدخلة مع القواعد واللوائح التنظيمية للشركة.","استخدام برامج متخصصة لعمل فلاتر وبحث متقدم عن الشذوذ أو التناقضات في البيانات.","الحفاظ على سرية البيانات وعدم مشاركة أي معلومات لغير المصرح لهم."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (131, 'كاتب حفظ ملفات', '["استلام المستندات والأوراق الرسمية وتصنيفها حسب النظام المعتمد (أبجدي، رقمي، تاريخي).","فتح ملفات جديدة للموظفين، أو العملاء، أو المشاريع، وتسميتها بشكل واضح.","حفظ المستندات في الملفات والأدراج الصحيحة لضمان عدم ضياعها.","تحديث سجلات الاستعارة لتعقب الملفات التي يتم أخذها من قبل الموظفين وتاريخ إرجاعها.","استرجاع الملفات المطلوبة للإدارة أو الأقسام بسرعة وكفاءة.","إجراء مسح ضوئي للمستندات الهامة لإنشاء نسخ إلكترونية احتياطية.","التخلص من الملفات القديمة أو غير الضرورية وفقاً لسياسة الإتلاف المعتمدة وتحت الإشراف.","صيانة خزائن الملفات والتأكد من نظافتها وتنظيمها الداخلي المستمر.","وضع ملصقات تعريفية واضحة وموحدة على المجلدات والرفوف.","جرد الملفات بشكل دوري للتأكد من عدم وجود أوراق أو مستندات في غير مكانها الصحيح.","حماية الملفات السرية وتطبيق نظام وصول مقيد للمستندات الحساسة.","إعداد تقارير بنواقص الملفات أو المستندات المفقودة لإبلاغ الإدارة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (132, 'كاتب حركة مخزون', '["تسجيل جميع عمليات الإدخال (الاستلام) والإخراج (الصرف) على نظام المخازن.","مراجعة أذونات الصرف والإضافة والتأكد من وجود التوقيعات والاعتمادات اللازمة.","مطابقة الفواتير وبوليصات الشحن مع الكميات المستلمة فعلياً في المستودع.","تحديث بطاقات الصنف الدفترية بعد كل عملية سحب أو إضافة.","إعداد تقارير يومية أو أسبوعية بحركة المخزون والأصناف الراكدة.","إدخال بيانات المرتجعات (سواء من العملاء أو الموردين) في النظام الخاص بالمستودع.","تنبيه أمين المخزن أو إدارة المشتريات عندما تصل أصناف معينة لحد الخطر أو نقطة إعادة الطلب.","المساعدة في عمليات الجرد الدوري والمفاجئ وتسجيل الفروقات وتبريرها.","توثيق وتسجيل حركات نقل البضائع بين المستودعات الفرعية والرئيسية للشركة.","الاحتفاظ بأرشيف منظم لأذونات الصرف والاستلام الورقية.","تسجيل محاضر إتلاف المواد التالفة أو منتهية الصلاحية وفق الإجراءات المتبعة.","مراجعة تسعيرة وتكلفة المواد الخارجة من المخزون بناءً على النظام المحاسبي المعتمد."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (133, 'فني صحة عامة', '["إجراء التفتيش الميداني على المنشآت (المطاعم، المصانع، المستشفيات) للتأكد من التزامها بالاشتراطات الصحية.","سحب عينات من المياه، والأغذية، والأسطح وإرسالها للمختبرات للتحليل البكتيري والكيميائي.","رصد ومكافحة نواقل الأمراض (مثل الحشرات والقوارض) في المنشآت والمرافق العامة.","التأكد من سلامة وصلاحية المواد الغذائية وطرق تخزينها وتداولها ومصادرتها إن لزم الأمر.","الإشراف على عمليات النظافة والتطهير والتعقيم الدورية في المرافق.","توعية وتثقيف العاملين والمجتمع بالطرق السليمة للنظافة الشخصية والوقاية من الأمراض.","تحرير المخالفات وتوجيه الإنذارات للمنشآت غير الملتزمة بالمعايير الصحية والبيئية.","متابعة عمليات التخلص الآمن من النفايات الطبية والعامة لمنع التلوث البيئي.","المشاركة في الاستجابة الميدانية لحالات تفشي الأمراض المعدية أو التسمم الغذائي.","إعداد تقارير دورية عن الحالة الصحية والبيئية للمرافق ورفعها للجهات الرقابية.","فحص الشهادات الصحية للعاملين في المنشآت الغذائية لضمان خلوهم من الأمراض المعدية.","التأكد من كفاءة أنظمة التهوية والصرف الصحي في المنشآت لمنع انتشار العدوى."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (134, 'محلل بيانات', '["استخراج وجمع البيانات من مصادر وقواعد بيانات متعددة.","تنظيف البيانات ومعالجتها لإزالة القيم المفقودة أو السجلات الشاذة والمكررة.","تصميم وبناء لوحات تحكم تفاعلية (Dashboards) لعرض البيانات بشكل مرئي للإدارة.","تحليل البيانات التاريخية لاكتشاف الأنماط، والاتجاهات، وسلوك العملاء.","إعداد تقارير تحليلية دورية تدعم الإدارة العليا في اتخاذ قرارات دقيقة مبنية على الأرقام.","إجراء تحليلات إحصائية معقدة لاختبار الفرضيات وتقييم أداء المنتجات أو الحملات.","العمل مع فرق التسويق والمبيعات لتحديد مؤشرات الأداء الرئيسية ومتابعتها.","تحويل البيانات والأرقام المعقدة إلى عروض تقديمية ورسوم بيانية مبسطة ومفهومة.","بناء نماذج تنبؤية أولية لتقدير المبيعات، والنمو، والطلب المستقبلي.","تحديد الفرص ومجالات التحسين لتقليل التكاليف التشغيلية أو زيادة الأرباح بناءً على البيانات.","صيانة وتحديث مستودعات البيانات بالتعاون مع فريق هندسة البيانات.","ضمان دقة وتناسق البيانات وتطبيق معايير أمن وسرية المعلومات."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (135, 'كاتب بريدي', '["استلام وفرز البريد اليومي الوارد (الورقي والطرود) وتصنيفه حسب الأقسام أو الموظفين المعنيين.","تسليم البريد الداخلي وتوزيعه على مكاتب الموظفين وفق جدول زمني وخط سير محدد.","تجميع المراسلات الصادرة من كافة الأقسام وتجهيزها للإرسال الخارجي.","تغليف وتعبئة الطرود والرسائل الهامة بشكل آمن لحمايتها أثناء الشحن.","التنسيق المستمر مع شركات الشحن والبريد السريع لترتيب مواعيد الاستلام والتسليم.","وزن الطرود وحساب تكاليف البريد وطباعة الطوابع أو بوليصات الشحن.","توثيق وتسجيل كافة المراسلات الواردة والصادرة في السجلات والدفاتر المخصصة لها.","استخدام أرقام التتبع لمراقبة مسار الشحنات الهامة والتأكد من وصولها للوجهة الصحيحة.","التعامل السريع مع المراسلات العاجلة وإعطائها الأولوية القصوى.","الحفاظ المطلق على سرية وأمان البريد، خاصة المستندات القانونية والمالية.","توجيه البريد الخاطئ وإعادته للمرسل أو البحث عن العنوان الصحيح للمستلم.","إعداد كشوف حساب شهرية بمصروفات الشحن والبريد وتسليمها للإدارة المالية لتسويتها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (136, 'كاتب سجل', '["إنشاء سجلات وملفات جديدة (للموظفين، أو المرضى، أو العملاء) بطريقة منظمة ودقيقة.","تحديث السجلات القائمة وإضافة المعلومات، أو الملاحظات، أو المستندات الجديدة إليها بانتظام.","ترقيم وتكويد السجلات وتصنيفها لضمان سهولة وسرعة الرجوع إليها عند الطلب.","مراجعة محتويات السجلات للتأكد من اكتمال كافة النماذج والأوراق القانونية المطلوبة.","إدخال البيانات الوصفية والملخصات الخاصة بالسجلات في النظام الإلكتروني الموحد للشركة.","تلبية طلبات سحب أو استعارة السجلات من قبل الأقسام والموظفين المصرح لهم فقط.","تتبع السجلات المستعارة والتأكد من إعادتها إلى الأرشيف في الوقت المحدد والتأكد من سلامتها.","الحفاظ على سرية السجلات والالتزام الصارم بلوائح حماية البيانات والخصوصية.","فرز السجلات التاريخية أو المغلقة ونقلها إلى مستودعات الحفظ طويل الأمد.","التنسيق لإتلاف السجلات المنتهية الصلاحية قانونياً تحت إشراف لجان متخصصة وفق محضر رسمي.","إجراء مسح ضوئي لرقمنة السجلات الورقية القديمة وحفظها في قاعدة البيانات الإلكترونية.","حل أي تناقضات أو أخطاء تظهر في السجلات والتواصل مع مصدر المعلومة لتصحيحها فوراً."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (137, 'مساعداداري', '["تنظيم وتنسيق المواعيد والاجتماعات اليومية للإدارة.","معالجة المراسلات الواردة والصادرة وتصنيفها حسب الأولوية.","إعداد المسودات والتقارير والوثائق الإدارية المطلوبة.","أرشفة الملفات والسجلات وضمان سهولة الوصول إليها عند الحاجة.","متابعة توفير المستلزمات المكتبية وضمان كفاءة سير العمل الإداري.","تدوين الملاحظات والقرارات أثناء اجتماعات الإدارة.","استقبال الزوار والمراجعين وتوجيههم للأقسام المعنية بأسلوب مهني ولبق.","تحديث قاعدة بيانات جهات الاتصال الخاصة بالمنشأة بانتظام.","متابعة سير المعاملات الورقية بين الإدارات المختلفة لضمان عدم تأخرها.","ترتيب وتنظيم الملفات السرية للإدارة مع ضمان الخصوصية التامة.","إعداد تقارير المصروفات النثرية الخاصة بالمكتب وتسويتها شهرياً.","تحديث لوحات الإعلانات الداخلية بالقرارات أو التعاميم الجديدة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (138, 'مدبر إداري', '["الإشراف العام على العمليات الإدارية اليومية للمنشأة وضمان سيرها بكفاءة.","إدارة طاقم الدعم الإداري والمكتبي، وتوزيع المهام، ومتابعة وتقييم أدائهم.","وضع وتحديث السياسات والإجراءات الإدارية الداخلية لضمان الانضباط المؤسسي.","متابعة عقود النظافة والصيانة والخدمات العامة للمبنى والمرافق مع المقاولين.","إدارة ميزانية الشؤون الإدارية ومراقبة وتخفيض النفقات التشغيلية للمكتب.","تنظيم وترتيب الاحتياجات اللوجستية للشركة من أثاث، وقرطاسية، وأجهزة مكتبية.","إدارة أسطول السيارات الخاص بالمنشأة وتنسيق حركتها، واستهلاكها، وصيانتها.","الإشراف على إدارة أمن المنشأة وتنظيم سياسات الدخول والخروج.","متابعة تجديد العقود الإدارية، والإيجارات، والتراخيص الخاصة بمقرات وفروع الشركة.","إعداد تقارير دورية للإدارة العليا عن سير العمل الإداري وأبرز المعوقات التشغيلية.","التنسيق لإقامة الفعاليات الداخلية للموظفين والمناسبات الرسمية لتعزيز الترابط.","معالجة شكاوى الموظفين المتعلقة ببيئة العمل، والمرافق، والخدمات المقدمة لهم."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (139, 'موظف إداري مبتدئ', '["استلام وتوجيه المراسلات والبريد اليومي للأقسام المعنية.","تصوير المستندات والملفات وتجهيزها للاجتماعات.","إدخال البيانات الأساسية في الجداول والأنظمة لتنظيم العمل.","الرد على المكالمات الهاتفية وتحويلها للموظفين المختصين.","تنظيم وترتيب الملفات الورقية في الأرشيف لسهولة الوصول إليها.","مساعدة فريق العمل في المهام اللوجستية البسيطة داخل المكتب.","طباعة الخطابات والنماذج الإدارية وتوزيعها.","متابعة المخزون البسيط للقرطاسية والأدوات المكتبية وتبليغ المشرف بالنواقص.","تسجيل حضور وانصراف الزوار في سجلات الاستقبال عند الحاجة.","استلام طلبات العملاء أو المراجعين ومراجعة اكتمال أوراقهم مبدئياً.","تنسيق وترتيب قاعات الاجتماعات قبل وبعد الاستخدام.","تقديم الدعم العام للمشرفين والالتزام بتعليمات العمل اليومية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (140, 'كاتب عام', '["استلام وتوجيه المراسلات والبريد اليومي للأقسام المعنية.","تصوير المستندات والملفات وتجهيزها للاجتماعات.","إدخال البيانات الأساسية في الجداول والأنظمة لتنظيم العمل.","الرد على المكالمات الهاتفية وتحويلها للموظفين المختصين.","تنظيم وترتيب الملفات الورقية في الأرشيف لسهولة الوصول إليها.","مساعدة فريق العمل في المهام اللوجستية البسيطة داخل المكتب.","طباعة الخطابات والنماذج الإدارية وتوزيعها.","متابعة المخزون البسيط للقرطاسية والأدوات المكتبية وتبليغ المشرف بالنواقص.","تسجيل حضور وانصراف الزوار في سجلات الاستقبال عند الحاجة.","استلام طلبات العملاء أو المراجعين ومراجعة اكتمال أوراقهم مبدئياً.","تنسيق وترتيب قاعات الاجتماعات قبل وبعد الاستخدام.","تقديم الدعم العام للمشرفين والالتزام بتعليمات العمل اليومية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (141, 'كيميائي', '["سحب عينات من المواد الخام والمنتجات النهائية لفحصها في المختبر.","إجراء التحاليل الكيميائية والفيزيائية باستخدام الأجهزة المعملية المتخصصة.","معايرة الأجهزة والمعدات المعملية بشكل دوري لضمان دقة النتائج.","إعداد وتحضير المحاليل الكيميائية والكواشف اللازمة للاختبارات اليومية.","تسجيل نتائج التحاليل بدقة في سجلات المختبر أو أنظمة إدارة الجودة.","مقارنة نتائج الاختبارات بالمواصفات القياسية المعتمدة ورفض العينات غير المطابقة.","تطبيق معايير السلامة والصحة المهنية الصارمة أثناء التعامل مع المواد الكيميائية الخطرة.","التخلص الآمن من النفايات الكيميائية وبقايا العينات وفقاً للوائح البيئية.","كتابة تقارير فنية مفصلة عن جودة المنتجات وحالات عدم المطابقة.","المشاركة في أبحاث تطوير المنتجات وتحسين التركيبات الكيميائية الحالية.","الإشراف على ظروف تخزين المواد الكيميائية الحساسة (درجة الحرارة، الرطوبة).","تدريب الفنيين الجدد على طرق الفحص القياسية واستخدام الأجهزة المعملية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (142, 'أخصائي مختبر', '["سحب عينات من المواد الخام والمنتجات النهائية لفحصها في المختبر.","إجراء التحاليل الكيميائية والفيزيائية باستخدام الأجهزة المعملية المتخصصة.","معايرة الأجهزة والمعدات المعملية بشكل دوري لضمان دقة النتائج.","إعداد وتحضير المحاليل الكيميائية والكواشف اللازمة للاختبارات اليومية.","تسجيل نتائج التحاليل بدقة في سجلات المختبر أو أنظمة إدارة الجودة.","مقارنة نتائج الاختبارات بالمواصفات القياسية المعتمدة ورفض العينات غير المطابقة.","تطبيق معايير السلامة والصحة المهنية الصارمة أثناء التعامل مع المواد الكيميائية الخطرة.","التخلص الآمن من النفايات الكيميائية وبقايا العينات وفقاً للوائح البيئية.","كتابة تقارير فنية مفصلة عن جودة المنتجات وحالات عدم المطابقة.","المشاركة في أبحاث تطوير المنتجات وتحسين التركيبات الكيميائية الحالية.","الإشراف على ظروف تخزين المواد الكيميائية الحساسة (درجة الحرارة، الرطوبة).","تدريب الفنيين الجدد على طرق الفحص القياسية واستخدام الأجهزة المعملية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (143, 'فني جودة', '["سحب عينات من المواد الخام والمنتجات النهائية لفحصها في المختبر.","إجراء التحاليل الكيميائية والفيزيائية باستخدام الأجهزة المعملية المتخصصة.","معايرة الأجهزة والمعدات المعملية بشكل دوري لضمان دقة النتائج.","إعداد وتحضير المحاليل الكيميائية والكواشف اللازمة للاختبارات اليومية.","تسجيل نتائج التحاليل بدقة في سجلات المختبر أو أنظمة إدارة الجودة.","مقارنة نتائج الاختبارات بالمواصفات القياسية المعتمدة ورفض العينات غير المطابقة.","تطبيق معايير السلامة والصحة المهنية الصارمة أثناء التعامل مع المواد الكيميائية الخطرة.","التخلص الآمن من النفايات الكيميائية وبقايا العينات وفقاً للوائح البيئية.","كتابة تقارير فنية مفصلة عن جودة المنتجات وحالات عدم المطابقة.","المشاركة في أبحاث تطوير المنتجات وتحسين التركيبات الكيميائية الحالية.","الإشراف على ظروف تخزين المواد الكيميائية الحساسة (درجة الحرارة، الرطوبة).","تدريب الفنيين الجدد على طرق الفحص القياسية واستخدام الأجهزة المعملية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (144, 'الثانوية العامة', '["استلام وتوجيه المراسلات والبريد اليومي للأقسام المعنية.","تصوير المستندات والملفات وتجهيزها للاجتماعات.","إدخال البيانات الأساسية في الجداول والأنظمة لتنظيم العمل.","الرد على المكالمات الهاتفية وتحويلها للموظفين المختصين.","تنظيم وترتيب الملفات الورقية في الأرشيف لسهولة الوصول إليها.","مساعدة فريق العمل في المهام اللوجستية البسيطة داخل المكتب.","طباعة الخطابات والنماذج الإدارية وتوزيعها.","متابعة المخزون البسيط للقرطاسية والأدوات المكتبية وتبليغ المشرف بالنواقص.","تسجيل حضور وانصراف الزوار في سجلات الاستقبال عند الحاجة.","استلام طلبات العملاء أو المراجعين ومراجعة اكتمال أوراقهم مبدئياً.","تنسيق وترتيب قاعات الاجتماعات قبل وبعد الاستخدام.","تقديم الدعم العام للمشرفين والالتزام بتعليمات العمل اليومية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (145, 'بكالوريوس تخصص الكيمياء', '["سحب عينات من المواد الخام والمنتجات النهائية لفحصها في المختبر.","إجراء التحاليل الكيميائية والفيزيائية باستخدام الأجهزة المعملية المتخصصة.","معايرة الأجهزة والمعدات المعملية بشكل دوري لضمان دقة النتائج.","إعداد وتحضير المحاليل الكيميائية والكواشف اللازمة للاختبارات اليومية.","تسجيل نتائج التحاليل بدقة في سجلات المختبر أو أنظمة إدارة الجودة.","مقارنة نتائج الاختبارات بالمواصفات القياسية المعتمدة ورفض العينات غير المطابقة.","تطبيق معايير السلامة والصحة المهنية الصارمة أثناء التعامل مع المواد الكيميائية الخطرة.","التخلص الآمن من النفايات الكيميائية وبقايا العينات وفقاً للوائح البيئية.","كتابة تقارير فنية مفصلة عن جودة المنتجات وحالات عدم المطابقة.","المشاركة في أبحاث تطوير المنتجات وتحسين التركيبات الكيميائية الحالية.","الإشراف على ظروف تخزين المواد الكيميائية الحساسة (درجة الحرارة، الرطوبة).","تدريب الفنيين الجدد على طرق الفحص القياسية واستخدام الأجهزة المعملية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (146, 'بكالوريوس تخصص الكیمیاء', '["سحب عينات من المواد الخام والمنتجات النهائية لفحصها في المختبر.","إجراء التحاليل الكيميائية والفيزيائية باستخدام الأجهزة المعملية المتخصصة.","معايرة الأجهزة والمعدات المعملية بشكل دوري لضمان دقة النتائج.","إعداد وتحضير المحاليل الكيميائية والكواشف اللازمة للاختبارات اليومية.","تسجيل نتائج التحاليل بدقة في سجلات المختبر أو أنظمة إدارة الجودة.","مقارنة نتائج الاختبارات بالمواصفات القياسية المعتمدة ورفض العينات غير المطابقة.","تطبيق معايير السلامة والصحة المهنية الصارمة أثناء التعامل مع المواد الكيميائية الخطرة.","التخلص الآمن من النفايات الكيميائية وبقايا العينات وفقاً للوائح البيئية.","كتابة تقارير فنية مفصلة عن جودة المنتجات وحالات عدم المطابقة.","المشاركة في أبحاث تطوير المنتجات وتحسين التركيبات الكيميائية الحالية.","الإشراف على ظروف تخزين المواد الكيميائية الحساسة (درجة الحرارة، الرطوبة).","تدريب الفنيين الجدد على طرق الفحص القياسية واستخدام الأجهزة المعملية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (147, 'بكلوریوس - منتظمة تخصص المحسبة', '["تسجيل وإثبات القيود والعمليات المالية اليومية في السجلات المحاسبية.","إعداد القوائم المالية (الدخل، المركز المالي) في نهاية الفترة.","متابعة الحسابات المدينة والدائنة وضمان تسوية المطالبات في موعدها.","مراجعة وتدقيق الفواتير والمستندات المالية لضمان صحتها.","إعداد التقارير الضريبية والزكوية وضمان الالتزام بالأنظمة المالية.","إعداد مسيرات رواتب الموظفين ومراجعة الخصومات والبدلات.","تسوية الحسابات البنكية (Bank Reconciliations) بشكل شهري.","مراقبة التدفقات النقدية (Cash Flow) وإعداد التوقعات المستقبلية.","جرد الأصول الثابتة وحساب إهلاكاتها الدفترية سنوياً.","المشاركة في عمليات جرد المخزون وتقييم التكلفة بانتظام.","التعاون المباشر مع مراجع الحسابات الخارجي (المدقق القانوني).","التحقق من صحة العهد المالية المؤقتة وتسويتها مع الموظفين."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (148, 'فني ميكانيكي محركات', '["فحص وتشخيص أعطال المحركات (سواء كانت بنزين أو ديزل).","فك وتجميع أجزاء المحرك المختلفة بدقة وبحسب أدلة الصيانة.","استبدال القطع الداخلية التالفة مثل المكابس (الشنابر)، الصمامات، والأحزمة.","قياس خلوصات الأجزاء الميكانيكية باستخدام أدوات القياس الدقيقة.","تنظيف وتزييت أجزاء المحرك لضمان عملها بسلاسة ومنع التآكل.","اختبار ضغط أسطوانات المحرك لتقييم كفاءة الاحتراق.","صيانة نظام الوقود والحقن (البخاخات) الخاص بالمحرك.","استخدام أجهزة الفحص الإلكترونية (Scanners) لقراءة أكواد الأعطال.","إجراء عمليات الصيانة الدورية الشاملة مثل تغيير الزيوت والفلاتر.","ضبط توقيت المحرك (Timing) بشكل دقيق لضمان الأداء الأمثل.","اختبار المحركات بعد إصلاحها، سواء على المنصة أو داخل المركبة/المعدة.","إعداد تقارير فنية توضح حالة المحرك والقطع التي تم استبدالها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (149, 'مهندس مدني', '["تصميم الهياكل الخرسانية والمعدنية للمباني والمنشآت.","إعداد المخططات الهندسية والمواصفات الفنية للمشاريع.","الإشراف الميداني اليومي على مواقع العمل لمتابعة سير التنفيذ.","حساب كميات المواد المطلوبة (الحديد، الأسمنت، الرمل) وتقدير التكاليف.","الإشراف على اختبارات التربة وتحليل النتائج لضمان سلامة الأساسات.","مراجعة وتقييم تقارير السلامة الإنشائية للمباني القائمة.","إدارة وتنسيق فرق العمل من مقاولين وعمال في الموقع.","التأكد من مطابقة الأعمال المنفذة للأكواد والمعايير الهندسية المعتمدة.","تخطيط مسارات شبكات المياه والصرف الصحي والبنية التحتية للمشروع.","حل المشكلات الهندسية الطارئة التي تظهر أثناء عملية التنفيذ.","إعداد الجداول الزمنية لمراحل المشروع المختلفة ومتابعة الالتزام بها.","التنسيق مع الجهات الحكومية لاستخراج التراخيص والتصاريح اللازمة للإنشاء."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (150, 'مهندس ميكانيكي', '["تصميم الأنظمة الميكانيكية كأنظمة التدفئة، التهوية، والتكييف (HVAC).","تطوير وتصميم الآلات والمعدات الميكانيكية الصناعية.","إجراء حسابات الأحمال الحرارية والديناميكية وهندسة الموائع للمشاريع.","الإشراف على تركيب وتشغيل الأنظمة الميكانيكية والسباكة ومكافحة الحريق في المواقع.","تحليل أداء الآلات والمعدات وتحديد فرص تحسين كفاءة استهلاك الطاقة.","استخدام برامج التصميم بمساعدة الحاسوب (مثل SolidWorks أو AutoCAD) لعمل المخططات.","إعداد جداول وبرامج الصيانة الوقائية والتنبؤية للمعدات.","تشخيص وحل المشكلات الهندسية المعقدة في خطوط الإنتاج والآلات.","مراجعة واعتماد المخططات التنفيذية الميكانيكية (Shop Drawings).","اختبار المواد المستخدمة في التصنيع للتأكد من تحملها للضغوط والحرارة.","إعداد المواصفات الفنية لطرح المناقصات لشراء المعدات وقطع الغيار.","ضمان توافق الأنظمة الميكانيكية مع معايير السلامة والصحة المهنية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (151, 'فني كهربائي أنظمة حماية كهربائية', '["تركيب مرحلات الحماية (Protection Relays) في محطات توليد وتوزيع الكهرباء.","برمجة وضبط إعدادات أجهزة الحماية (Settings) وفقاً للمخططات الهندسية.","إجراء اختبارات الحقن الأولي والثانوي (Primary & Secondary Injection).","فحص قواطع الدورة الكهربائية (Circuit Breakers) والتأكد من استجابتها لتيار الفصل.","صيانة بطاريات المحطات وأنظمة التيار المستمر (DC Systems) التي تغذي أجهزة الحماية.","قراءة وتحليل المخططات الكهربائية الأحادية (Single Line Diagrams).","تشخيص أسباب الأعطال والفصل المفاجئ (Tripping) للتيار الكهربائي.","فحص وصيانة محولات التيار ومحولات الجهد (CT & VT).","معايرة أجهزة القياس المرتبطة ارتباطاً وثيقاً بأنظمة الحماية الكهربائية.","توثيق نتائج الاختبارات وإعداد تقارير الصيانة الدورية بشكل دقيق.","استبدال الأجزاء التالفة في لوحات التحكم، القياس، والحماية.","تطبيق إجراءات السلامة الصارمة (Lockout/Tagout) أثناء التعامل مع معدات الجهد العالي."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (152, 'فني أجهزة إلكترونية', '["تتبع الأعطال في اللوحات الإلكترونية المطبوعة (PCBs).","استخدام أجهزة القياس الدقيقة مثل راسم الإشارة (Oscilloscope) والملتيميتر.","لحام وفك المكونات الإلكترونية السطحية الدقيقة (SMD) باستخدام محطات اللحام بالهواء الساخن.","قراءة الدوائر الإلكترونية (Schematics) لفهم مسار الإشارات والطاقة.","فحص المكثفات، المقاومات، والترانزستورات، والدوائر المتكاملة واستبدال التالف منها.","صيانة أجهزة التحكم الدقيقة (Microcontrollers) وإعادة برمجتها إذا لزم الأمر.","إصلاح شاشات العرض والأجهزة المنزلية والمكتبية ذات المكونات الإلكترونية المعقدة.","تجميع الأجهزة الإلكترونية وتركيب وتوصيل مكوناتها الداخلية.","تنظيف اللوحات الإلكترونية من التآكل والرطوبة باستخدام المحاليل المتخصصة.","تحديث البرامج الثابتة (Firmware) للأجهزة الإلكترونية لضمان توافقها.","معايرة الأجهزة الإلكترونية الحساسة لضمان دقة عملها وقراءاتها.","إعداد سجلات بمكونات الغيار المستهلكة وأنواع الأعطال الشائعة للأجهزة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (153, 'فني ميكانيكي مركبات', '["تشخيص أعطال السيارات باستخدام أجهزة كشف الأعطال بالكمبيوتر (OBD-II).","فك وإصلاح أنظمة التعليق والتوجيه (مساعدين، مقصات، علبة دركسيون).","صيانة نظام الفرامل (تغيير أقمشة، مسح طنابير، استنزاف هواء الفرامل).","تغيير زيوت المحرك، ناقل الحركة، والتروس (الدفرنس) مع فلاترها.","إصلاح أو استبدال أجزاء دورة التبريد (الردياتير، طرمبة المياه، الثرموستات).","فك وتركيب وإصلاح ناقل الحركة (الجيربوكس) بنوعيه العادي والأوتوماتيكي.","تغيير السيور (الأحزمة) والبكرات التالفة أو المنتهية الصلاحية.","اختبار ضغط الإطارات وضبط زوايا العجلات (Wheel Alignment & Balancing).","صيانة نظام العادم ومحول الحفاز (الكتالايزر) لضمان تقليل الانبعاثات.","فحص حالة البطارية والمولد الكهربائي (الدينامو) ومحرك بدء الحركة (المارش).","إجراء الفحص الدوري والشامل للمركبات قبل السفر أو لتجديد الرخص.","تدوين الملاحظات حول حالة السيارة وتوجيه النصائح للعميل بشأن الصيانة المستقبلية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (154, 'مهندس إدارة مشاريع', '["إعداد ميثاق المشروع وتحديد النطاق والأهداف والمتطلبات بوضوح.","إنشاء الجداول الزمنية لتنفيذ الأعمال باستخدام برامج مثل Primavera أو MS Project.","تقدير وتخصيص الميزانيات وتتبع التكاليف المالية لتجنب التجاوزات.","إدارة الموارد البشرية والمادية لضمان توفرها في الوقت والمكان المناسبين.","تقييم المخاطر المحتملة للمشروع ووضع خطط استباقية (Risk Management) للتعامل معها.","تنسيق التواصل وإدارة العلاقات بين جميع الأطراف المعنية (المقاول، المالك، الاستشاري).","مراقبة جودة سير العمل والتأكد من مطابقته للمواصفات القياسية.","عقد وإدارة اجتماعات دورية لتقييم تقدم العمل وحل العقبات اليومية.","إدارة العقود والمطالبات وأوامر التغيير (Change Orders) أثناء فترة التنفيذ.","مراجعة واعتماد المستخلصات المالية للمقاولين بناءً على نسب الإنجاز.","إعداد تقارير الأداء الشهرية أو الأسبوعية ورفعها للإدارة العليا.","الإشراف على التسليم الابتدائي والنهائي للمشروع وإغلاق الوثائق الرسمية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (155, 'مهندس معماري', '["تصميم الواجهات المعمارية والتوزيع الداخلي للمباني بما يحقق الجمالية والوظيفة.","إعداد المخططات المعمارية ثنائية وثلاثية الأبعاد باستخدام برامج AutoCAD و Revit.","عمل مناظير ولقطات ثلاثية الأبعاد (3D Renders) باستخدام برامج مثل 3ds Max أو Lumion.","دراسة حركة الشمس، الظلال، والتهوية الطبيعية لتصميم مباني مستدامة بيئياً.","اختيار مواد التشطيبات المناسبة للواجهات والديكورات الداخلية (أرضيات، حوائط، أسقف).","التنسيق مع المهندسين الإنشائيين والكهربائيين والميكانيكيين لضمان تكامل المخططات (Coordination).","مراجعة قوانين البناء المحلية والاشتراطات البلدية وتطبيقها حرفياً في التصميم.","تقديم العروض التقديمية (Presentations) للمنظور التصميمي للعملاء وإقناعهم بالفكرة.","القيام بزيارات إشرافية للموقع لضمان دقة تنفيذ التفاصيل المعمارية والتشطيبات.","تصميم تنسيق الموقع العام (Landscape)، الممرات، والحدائق المحيطة بالمبنى.","عمل المخططات التنفيذية التفصيلية (Detailing) للتشطيبات، النجارة، والألومنيوم.","تقديم حلول مكانية مبتكرة للاستغلال الأمثل للمساحات الضيقة أو المعقدة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (156, 'فني كهربائي شبكات توزيع أرضية', '["تمديد وسحب الكابلات الأرضية ذات الجهد المتوسط والمنخفض.","عمل وصلات الكابلات الأرضية (Cable Joints) ونهاياتها (Terminations) باحترافية.","الإشراف على حفر وتجهيز الخنادق لمد الكابلات وفقاً للعمق والمواصفات القياسية.","تحديد مسارات الكابلات وتجنب التعارض مع خطوط البنية التحتية الأخرى (ماء، غاز، اتصالات).","تركيب كبائن التوزيع (Pillars) والمحولات الأرضية (Pad-mounted Transformers) وتوصيلها.","فحص عزل الكابلات باستخدام أجهزة الميجر (Megger) لاختبار سلامتها قبل إطلاق التيار.","استخدام أجهزة تحديد الأعطال الدقيقة للبحث عن نقاط القطع أو التلف في الكابلات المدفونة.","إصلاح الأعطال المباشرة في الكابلات الأرضية وإعادة عزلها واستعادة التيار.","قراءة المخططات الجغرافية (GIS) والمخططات التنفيذية لشبكات التوزيع.","تنفيذ أعمال التأريض للمعدات والكابلات لضمان الحماية من التسرب الأرضي.","عزل وتأمين مساحة العمل الأرضية ووضع العلامات التحذيرية قبل بدء الحفر.","تمرير وسحب الكابلات داخل المواسير البلاستيكية (Ducts) وإغلاق الفتحات لمنع تسرب المياه."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (157, 'فني علوم أغذية', '["سحب عينات عشوائية من المواد الخام والمنتجات النهائية والمياه لتحليلها.","إجراء الاختبارات الكيميائية والفيزيائية لتقييم جودة الأغذية ومطابقتها للمواصفات.","الفحص الميكروبيولوجي للعينات في المختبر للكشف عن البكتيريا والفطريات الضارة.","قياس مستويات الحموضة (pH)، الرطوبة، الكثافة، واللزوجة للمنتجات الغذائية.","الجولات التفتيشية على خطوط الإنتاج للتأكد من الالتزام بمعايير التصنيع الجيد (GMP).","معايرة الأجهزة المعملية (مثل الموازين وأجهزة قياس الحموضة) وتنظيفها بشكل دوري.","تسجيل وتحليل بيانات الاختبارات المخبرية بدقة في سجلات الجودة.","المساعدة في تجارب تطوير وصفات جديدة وتحسين الخصائص الحسية للمنتجات الحالية.","مراقبة عمليات التعبئة والتغليف لضمان غلق العبوات بشكل يحفظ عمر المنتج.","التأكد من التزام المنشأة بتطبيق نظام تحليل المخاطر ونقاط التحكم الحرجة (HACCP).","إعداد تقارير الإيقاف أو الرفض للمنتجات أو المواد الخام غير المطابقة للمواصفات.","المراقبة اليومية لدرجات حرارة التخزين في الثلاجات، المجمدات، ومستودعات الجاف."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (158, 'فني دعم تقنية معلومات (IT Support)', '["تثبيت وتحديث وإعداد أنظمة التشغيل (Windows, Linux, macOS) على أجهزة الموظفين.","تقديم الدعم الفني وحل مشاكل المستخدمين (Helpdesk) سواء عن بُعد (Remote) أو حضورياً.","صيانة مكونات الحواسيب المادية (Hardware) واستبدال القطع التالفة مثل الرامات والقرص الصلب.","إعداد وتهيئة الطابعات، الماسحات الضوئية، وآلات التصوير وربطها بالشبكة المحلية.","تثبيت حزم البرامج المكتبية، وتطبيقات الشركة، ومضادات الفيروسات وتحديثها.","إدارة عمليات النسخ الاحتياطي للبيانات (Backups) واسترجاع الملفات عند فقدانها.","حل مشاكل الاتصال بالإنترنت، الشبكة المحلية، والبريد الإلكتروني للموظفين.","إنشاء، تعديل، وإلغاء حسابات المستخدمين وإدارة الصلاحيات عبر (Active Directory).","تقديم توجيه سريع وتدريب للموظفين الجدد على استخدام الأنظمة والمعدات التقنية للشركة.","تشخيص وإزالة الفيروسات والبرامج الضارة (Malware) من الأجهزة المصابة.","توثيق وحفظ سجلات عبر نظام التذاكر (Ticketing System) لتتبع الأعطال وكيفية حلها.","تجهيز قاعات الاجتماعات وصيانتها (أجهزة العرض، شاشات التلفاز، أجهزة الصوت للاتصال المرئي)."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (159, 'فني دعم تقنية معلومات', '["تثبيت وتحديث وإعداد أنظمة التشغيل (Windows, Linux, macOS) على أجهزة الموظفين.","تقديم الدعم الفني وحل مشاكل المستخدمين (Helpdesk) سواء عن بُعد (Remote) أو حضورياً.","صيانة مكونات الحواسيب المادية (Hardware) واستبدال القطع التالفة مثل الرامات والقرص الصلب.","إعداد وتهيئة الطابعات، الماسحات الضوئية، وآلات التصوير وربطها بالشبكة المحلية.","تثبيت حزم البرامج المكتبية، وتطبيقات الشركة، ومضادات الفيروسات وتحديثها.","إدارة عمليات النسخ الاحتياطي للبيانات (Backups) واسترجاع الملفات عند فقدانها.","حل مشاكل الاتصال بالإنترنت، الشبكة المحلية، والبريد الإلكتروني للموظفين.","إنشاء، تعديل، وإلغاء حسابات المستخدمين وإدارة الصلاحيات عبر (Active Directory).","تقديم توجيه سريع وتدريب للموظفين الجدد على استخدام الأنظمة والمعدات التقنية للشركة.","تشخيص وإزالة الفيروسات والبرامج الضارة (Malware) من الأجهزة المصابة.","توثيق وحفظ سجلات عبر نظام التذاكر (Ticketing System) لتتبع الأعطال وكيفية حلها.","تجهيز قاعات الاجتماعات وصيانتها (أجهزة العرض، شاشات التلفاز، أجهزة الصوت للاتصال المرئي)."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (160, 'مهندس شبكات', '["تصميم وبناء البنية التحتية لشبكات الحاسب الآلي المحلية والواسعة (LAN, WAN).","برمجة وتهيئة أجهزة التوجيه (Routers) والمبدلات (Switches) وفقاً لمتطلبات العمل.","تنفيذ سياسات أمان الشبكة وتهيئة الجدران النارية (Firewalls) لمنع الاختراقات.","مراقبة أداء الشبكة وتحليل تدفق البيانات (Traffic Analysis) لتجنب الاختناقات.","إنشاء وإدارة الشبكات الافتراضية الخاصة (VPN) للسماح للموظفين بالوصول الآمن عن بُعد.","إدارة وتحديث أنظمة تشغيل أجهزة الشبكة (IOS) لسد الثغرات الأمنية.","تخطيط وتنفيذ مساحة عناوين الـ IP وتقسيم الشبكات (Subnetting & VLANs).","حل المشاكل المعقدة في الشبكة وتتبع انقطاع الاتصال (Advanced Troubleshooting).","إعداد وتكوين شبكات الإنترنت اللاسلكية (Wi-Fi) وإدارة نقاط الوصول (Access Points) بفعالية.","التعاون مع مقدمي خدمات الإنترنت (ISP) لحل مشاكل انقطاع الخدمة أو ضعف السرعات.","رسم وتوثيق مخططات الشبكة المادية والمنطقية (Network Topology) للرجوع إليها.","وضع وتجربة خطط التعافي من الكوارث (Disaster Recovery) لضمان استمرارية عمل الشبكة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (161, 'فني صيانة أجهزة كهربائية', '["الفحص والتشخيص الدقيق للأعطال في الأجهزة المنزلية (غسالات، ثلاجات، أفران، مكيفات شباك).","قراءة الدوائر الكهربائية (Wiring Diagrams) الخاصة بكل جهاز لفهم تسلسل التشغيل.","استخدام أجهزة القياس (الأفوميتر) لقياس الجهد، التيار، والمقاومة لتحديد القطع التالفة.","فك وتغيير قطع الغيار التالفة مثل المحركات، المضخات، السخانات، والمستشعرات (Sensors).","الكشف عن تسريب غاز الفريون، لحام المواسير، وإعادة شحن الغاز للثلاجات والمبردات.","صيانة وتنظيف الفلاتر، المكثفات، والمبخرات لرفع كفاءة الأجهزة وتقليل استهلاكها للكهرباء.","فحص وإصلاح أو استبدال لوحات التحكم الإلكترونية (PCBs) التي تشغل الأجهزة الحديثة.","التأكد من سلامة التوصيلات الكهربائية وتأريض الأجهزة لتجنب خطر الصدمات الكهربائية للعملاء.","تحديد قطع الغيار المطلوبة بدقة وتقديم تقدير مسبق لتكلفة الإصلاح للعميل.","تشغيل الجهاز واختباره تحت أحمال مختلفة (Testing Cycle) بعد الانتهاء من صيانته.","تقديم إرشادات ونصائح للعملاء حول كيفية الحفاظ على الأجهزة وتجنب سوء الاستخدام.","إصلاح الأدوات والمعدات الكهربائية الصغيرة مثل الخلاطات، المكانس الكهربائية، والمكاوي."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (162, 'مدير مبيعات تجزئة', '["وضع وتطوير خطط واستراتيجيات المبيعات لزيادة الإيرادات والحصة السوقية.","تحقيق أهداف المبيعات اليومية، والشهرية، والسنوية للفروع أو المتجر.","إدارة وتوجيه وتطوير فريق المبيعات لتحقيق أقصى درجات الكفاءة.","متابعة حركة المخزون وضمان توافر المنتجات على أرفف العرض باستمرار.","التعامل مع شكاوى العملاء المعقدة وحلها لضمان مستوى عالٍ من الرضا.","تحليل بيانات وتقارير المبيعات لفهم اتجاهات السوق وسلوك المستهلك.","تخطيط وتنفيذ العروض الترويجية والخصومات بالتعاون مع قسم التسويق.","تدريب وتأهيل الموظفين الجدد على مهارات البيع وخدمة العملاء.","إعداد تقارير دورية حول الأداء العام لرفعها إلى الإدارة العليا.","مراقبة أنشطة المنافسين في السوق وتقديم اقتراحات لمواجهتها.","إجراء تقييمات الأداء الدورية لأفراد فريق العمل وتقديم التغذية الراجعة.","التأكد من التزام المتجر بجميع سياسات وإجراءات الشركة التشغيلية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (163, 'مدير عام', '["وضع الرؤية الاستراتيجية الشاملة للشركة والأهداف طويلة المدى.","الإشراف المباشر على العمليات اليومية لكافة أقسام وإدارات الشركة.","اعتماد الميزانيات السنوية ومراقبة النفقات لضمان الاستقرار المالي.","اتخاذ القرارات المصيرية والاستراتيجية التي تؤثر على مسار العمل.","تقييم أداء مديري الأقسام المختلفة وتقديم التوجيه والدعم لهم.","بناء وتوطيد علاقات قوية مع كبار الشركاء، والموردين، والمستثمرين.","ضمان امتثال الشركة لجميع القوانين والتشريعات الحكومية والتجارية.","دراسة واعتماد خطط التوسع، وافتتاح فروع جديدة، أو دخول أسواق جديدة.","إدارة الأزمات وحل المشكلات الكبرى التي قد تعيق تقدم الشركة.","تمثيل الشركة كواجهة رسمية في الفعاليات والمؤتمرات والاجتماعات الهامة.","مراجعة وتحليل التقارير المالية والتشغيلية وقياس الأداء العام (KPIs).","تعزيز ثقافة عمل إيجابية وتحفيز الموظفين على الابتكار والولاء للشركة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (164, 'مدير عمليات هندسة صناعية', '["تصميم وتطوير أنظمة الإنتاج والتصنيع لضمان أقصى قدر من الفعالية.","تحديد وتقليل الهدر في المواد والوقت لتحسين كفاءة العمليات الصناعية.","تخطيط وتنظيم سير العمل داخل المنشأة لضمان سلاسة حركة الإنتاج.","إدارة خطط صيانة وتحديث الآلات والمعدات لتقليل فترات التوقف (Downtime).","تطبيق معايير إدارة الجودة الشاملة (TQM) في جميع مراحل التشغيل.","تحليل تدفق المواد الخام وتوزيع العمالة بما يتناسب مع متطلبات الإنتاج.","إعداد دراسات الجدوى الفنية والهندسية للمشاريع وخطوط الإنتاج الجديدة.","ضمان تطبيق أعلى معايير السلامة والصحة المهنية داخل بيئة العمل الصناعية.","تدريب الفنيين والمهندسين على استخدام الأساليب والتقنيات الصناعية الحديثة.","وضع استراتيجيات لخفض تكاليف التشغيل دون المساس بجودة المنتج النهائي.","استخدام برامج النمذجة والمحاكاة الهندسية لاختبار العمليات قبل تطبيقها.","إعداد التقارير الفنية والهندسية الدورية لرفعها للإدارة لمتابعة الأداء."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (165, 'مدير تدريب', '["حصر وتحديد الاحتياجات التدريبية للموظفين بالتعاون مع مديري الأقسام.","تصميم وتطوير المناهج، والمواد التدريبية، والأدلة الإرشادية.","إعداد وإدارة الميزانية السنوية الخاصة بقسم التدريب والتطوير.","استقطاب وتقييم المدربين ومراكز التدريب الخارجية للتعاقد معهم.","جدولة وتنظيم ورش العمل، والندوات، والدورات التدريبية الميدانية.","قياس العائد على الاستثمار (ROI) للبرامج التدريبية وتأثيرها المالي.","إنشاء وتحديث قواعد بيانات سجلات تدريب الموظفين.","مواكبة أحدث التطورات التكنولوجية في مجالات وأساليب التدريب.","تقييم أثر التدريب الفعلي على أداء الموظف وإنتاجيته بعد الدورة.","وضع خطط ومسارات التطوير الوظيفي (Career Path) للكفاءات والمواهب.","إدارة وتفعيل منصات التعلم الإلكتروني (LMS) الخاصة بالشركة.","إعداد تقارير شاملة للإدارة توضح إنجازات خطة التدريب السنوية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (166, 'مدير علاقات عامة', '["تخطيط وتنفيذ استراتيجيات لبناء وتحسين الصورة الذهنية الإيجابية للشركة.","صياغة ومراجعة وتوزيع البيانات الصحفية والأخبار الرسمية للشركة.","بناء وإدارة شبكة علاقات قوية مع وسائل الإعلام والصحفيين والمؤثرين.","تنظيم وإدارة المؤتمرات الصحفية، وحفلات الإطلاق، والفعاليات الخاصة.","وضع خطط استباقية للتعامل مع الأزمات الإعلامية وإدارتها باحترافية.","إعداد وتطوير خطط التواصل الداخلي لتعزيز انتماء الموظفين للشركة.","رصد ومتابعة ما يُنشر عن الشركة في وسائل الإعلام ومنصات التواصل الاجتماعي.","الإشراف على المحتوى الإعلامي للموقع الإلكتروني والمنشورات الرسمية.","التنسيق المستمر مع قسم التسويق لدعم الحملات الإعلانية والترويجية.","تمثيل الشركة بشكل لائق أمام الجهات الحكومية والمنظمات المجتمعية.","كتابة الخطابات الرسمية والتصريحات الخاصة بأعضاء الإدارة العليا.","قياس نجاح حملات العلاقات العامة وتقديم تقارير تحليلية عن تفاعل الجمهور."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (167, 'مدير مصنع', '["الإشراف والتوجيه الكامل لجميع عمليات التصنيع والإنتاج داخل المصنع.","إعداد واعتماد جداول وخطط الإنتاج اليومية، والأسبوعية، والشهرية.","التأكد من مطابقة جميع المنتجات النهائية لمعايير الجودة والمواصفات المطلوبة.","إدارة مستويات المخزون من المواد الخام والمنتجات النهائية بدقة.","مراقبة كفاءة القوى العاملة وإدارة توزيع الورديات (الشفتات) بشكل عادل ومنظم.","فرض وتطبيق صارم لسياسات وإجراءات الأمن الصناعي والسلامة المهنية.","التدخل الفوري لحل أي أعطال أو مشكلات فنية قد توقف خطوط الإنتاج.","الإشراف على برامج الصيانة الدورية والوقائية للمعدات لضمان استمراريتها.","تحسين كفاءة استهلاك الموارد (طاقة، مياه، مواد) لتقليل تكلفة الإنتاج.","إجراء تقييمات دورية لأداء المشرفين والعمال وتحديد مسارات تطويرهم.","التنسيق مع إدارة المشتريات وسلاسل الإمداد لتوفير الخامات في الوقت المناسب.","رفع تقارير دقيقة حول معدلات الإنتاج، والهالك، والأداء العام للإدارة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (168, 'مدير توظيف', '["وضع وتصميم استراتيجيات وخطط التوظيف السنوية لتلبية احتياجات الشركة.","الاجتماع بمديري الأقسام لفهم متطلباتهم الدقيقة وتحديد الشواغر الوظيفية.","صياغة وتحديث التوصيف الوظيفي (Job Description) لكل دور في المؤسسة.","إدارة الحملات الإعلانية للوظائف عبر منصات التوظيف، ومواقع التواصل، والموقع الرسمي.","فرز وتصفية السير الذاتية وتحديد المرشحين الأكثر ملاءمة للمتطلبات.","إدارة وإجراء المقابلات الشخصية (الهاتفية، المرئية، والحضورية).","إعداد وتقديم عروض العمل (Job Offers) والتفاوض مع المرشحين حول الرواتب.","تنظيم والمشاركة في معارض التوظيف وملتقيات التوجيه المهني بالجامعات.","إدارة عمليات التقييم، واختبارات الكفاءة، والفحص الأمني أو المرجعي للمرشحين.","تصميم والإشراف على برامج تأهيل ودمج الموظفين الجدد (Onboarding).","بناء وتحديث قاعدة بيانات ضخمة (Talent Pool) للمواهب والمرشحين المحتملين.","تحليل مقاييس التوظيف (مثل: الوقت المستغرق للتوظيف، وتكلفة التعيين) لتحسين الأداء."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (169, 'مراسل', '["استلام وتسليم البريد والطرود والمستندات بين إدارات الشركة والجهات الخارجية بكفاءة وسرعة.","الحفاظ على أمن وسرية المستندات المنقولة وعدم الإفصاح عن محتواها للغير تحت أي ظرف.","تنظيم وترتيب البريد الوارد والصادر وتوزيعه على المكاتب والأقسام المعنية بدقة.","تخطيط ورسم المسارات اليومية لإنجاز مهام التوصيل في أسرع وقت وأقل جهد ممكن.","الحصول على إيصالات الاستلام وتوقيعات الجهات المستلمة لتوثيق إتمام عملية التسليم بنجاح.","إنجاز المعاملات الخارجية الروتينية مثل دفع الفواتير وإنهاء الأوراق في المصالح الحكومية والبنكية.","تحصيل الأموال أو نقل العهد المالية البسيطة وتسليمها للقسم المالي بأمان تام.","الحفاظ على نظافة وسلامة وسيلة النقل المخصصة للعمل وإبلاغ الإدارة باحتياجات صيانتها.","تدوين وتحديث حالة الطرود والمراسلات في سجلات الشركة أو عبر التطبيقات الإلكترونية المستخدمة.","استلام الطرود المرفوضة أو المرتجعة وإعادتها إلى مصدرها مع توضيح سبب عدم التسليم.","التواصل مع العملاء والجهات الخارجية بأسلوب مهني يعكس صورة إيجابية عن المؤسسة.","تقديم خدمات مكتبية مساندة عند الحاجة مثل تصوير المستندات أو ترتيب الملفات البسيطة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (170, 'مراقب حركة مركبات', '["استخدام أنظمة تحديد المواقع (GPS) لمراقبة مسارات المركبات والتأكد من التزامها بخطوط السير.","تخطيط وجدولة الرحلات اليومية وتوزيع مهام التوصيل أو النقل على السائقين لضمان أعلى كفاءة تشغيلية.","تتبع معدلات استهلاك الوقود لكل مركبة وتحليل البيانات للحد من الهدر وتقليل التكاليف.","توجيه السائقين والتواصل معهم لاختيار مسارات بديلة في حالات الازدحام المروري أو إغلاق الطرق.","التنسيق مع قسم الصيانة لجدولة الفحوصات الدورية للمركبات وتتبع إصلاح الأعطال.","التدخل السريع وإرسال فرق الدعم في حال تعرض إحدى المركبات لحادث أو عطل مفاجئ على الطريق.","التأكد من التزام السائقين بقوانين المرور والسرعات المقررة وتطبيق لوائح السلامة المهنية.","مراجعة السجلات الورقية والإلكترونية لأوقات مغادرة ووصول المركبات بدقة تامة.","التأكد من سريان رخص القيادة للسائقين وتراخيص سير المركبات قبل خروجها للعمل.","تحديث حالة الشحنات والتواصل مع العملاء لإبلاغهم بمواعيد الوصول المتوقعة أو التأخيرات المحتملة.","متابعة ساعات عمل السائقين لضمان حصولهم على فترات الراحة القانونية وتجنب الإرهاق.","تقديم تقارير يومية وشهرية للإدارة حول أداء الأسطول ومعدلات التأخير وكفاءة السائقين."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (171, 'بائع مواد إنشائية', '["استقبال العملاء (مقاولين، مهندسين، أو أفراد) وفهم احتياجاتهم من مواد البناء.","تقديم المشورة الفنية وشرح خصائص المواد المختلفة (الأسمنت، الحديد، الطوب، العوازل، إلخ) ومساعدة العميل في اختيار الأنسب.","إعداد عروض أسعار دقيقة للكميات المطلوبة وإصدار الفواتير ومتابعة عمليات الدفع.","التفاوض على الأسعار مع المقاولين وشركات البناء وإغلاق الصفقات لتحقيق أهداف المبيعات.","المتابعة الدورية لمستويات المخزون في المستودع ورفع طلبات التوريد للمواد التي توشك على النفاد.","ترتيب وعرض عينات المنتجات داخل المعرض بشكل جذاب يسهل على العميل رؤيتها وفحصها.","التنسيق مع قسم الحركة أو السائقين لضمان توصيل المواد الإنشائية إلى مواقع العمل في المواعيد المحددة.","تأسيس والحفاظ على علاقات عمل طويلة الأمد مع كبار العملاء والمقاولين لضمان استمرارية التعامل.","التعامل مع شكاوى العملاء بمهنية، وإدارة عمليات استرجاع أو استبدال المواد التالفة أو غير المطابقة.","مراقبة أسعار المنافسين والتغيرات في أسواق مواد البناء وإبلاغ الإدارة بأي تطورات.","كتابة تقارير يومية أو أسبوعية بحجم المبيعات والمواد الأكثر أو الأقل طلباً ورفعها للإدارة.","الفحص الظاهري للمواد عند استلامها من الموردين وقبل تسليمها للعميل لضمان سلامتها وجودتها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (172, 'مصمم جرافيك', '["الاجتماع مع العملاء أو مديري المشاريع لفهم الرسالة المراد إيصالها، والجمهور المستهدف، ومتطلبات التصميم.","العصف الذهني وتطوير مفاهيم مبتكرة للحملات الإعلانية والتسويقية.","تصميم الشعارات وبناء الهوية البصرية للشركات بما يشمل الألوان والخطوط المعتمدة.","إعداد تصاميم للمواد المطبوعة مثل البروشورات، الكتيبات، الكروت الشخصية، أغلفة المنتجات، واللوحات الإعلانية.","تصميم منشورات، إعلانات ممولة، وقصص تتناسب مع أبعاد ومتطلبات منصات التواصل الاجتماعي المختلفة.","تحديد واختيار الصور، الرسوم التوضيحية، الخطوط، والألوان المناسبة التي تخدم فكرة التصميم.","العمل باحترافية على برامج التصميم المعتمدة (مثل Adobe Photoshop, Illustrator, InDesign).","عرض النماذج الأولية على العملاء أو الفريق وتقبل الملاحظات وإجراء التعديلات المطلوبة للوصول للتصميم النهائي.","إعداد وتحضير الملفات النهائية للطباعة والتأكد من دقة الألوان والمقاسات والمواصفات الفنية.","التنسيق مع كتاب المحتوى ومطوري الويب لضمان تكامل التصميم مع النصوص والواجهات الرقمية.","الاطلاع المستمر على أحدث الاتجاهات العالمية في مجال التصميم الجرافيكي والتقنيات الجديدة.","الالتزام بتسليم المشاريع في المواعيد المحددة وتنظيم وأرشفة ملفات التصميم للرجوع إليها مستقبلاً."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (173, 'أخصائي تقييم ثغرات', '["إجراء فحوصات دورية للأنظمة والشبكات لاكتشاف الثغرات الأمنية.","تحليل نقاط الضعف في التطبيقات والبنية التحتية لتكنولوجيا المعلومات.","استخدام أدوات فحص الثغرات الآلية واليدوية لتقييم مستوى الأمان.","إعداد تقارير مفصلة توضح الثغرات المكتشفة ومستوى خطورتها.","تقديم توصيات وحلول تقنية لمعالجة الثغرات وإغلاقها.","التعاون مع فريق تطوير البرمجيات لضمان تطبيق معايير الأمان البرمجية.","متابعة أحدث التهديدات الأمنية وأساليب الاختراق الحديثة.","إجراء اختبارات الاختراق (Penetration Testing) عند الحاجة لمحاكاة الهجمات.","التحقق من فعالية التحديثات والترقيعات الأمنية (Patches) بعد تطبيقها.","ضمان توافق الأنظمة مع سياسات ومعايير الأمان المحلية والدولية.","توعية وتدريب الموظفين حول ممارسات الأمان لتجنب الهندسة الاجتماعية.","المشاركة في وضع خطط الاستجابة للحوادث الأمنية والتعافي من الكوارث."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (174, 'مأمور سنترال', '["استقبال المكالمات الهاتفية الواردة للشركة والرد عليها بأسلوب احترافي.","تحويل المكالمات إلى الأقسام أو الأشخاص المعنيين بدقة وسرعة.","الرد على استفسارات العملاء الأساسية وتزويدهم بالمعلومات العامة.","تسجيل رسائل المتصلين في حال عدم توفر الشخص المطلوب وتوصيلها له.","إدارة وصيانة لوحة السنترال (Switchboard) والإبلاغ عن أي أعطال.","تحديث دليل الهواتف الداخلي للموظفين والأقسام بشكل دوري.","إجراء المكالمات الصادرة وتنسيق المكالمات الجماعية (Conference Calls) عند الطلب.","استقبال الزوار والترحيب بهم (في حال الجمع بين مهام الاستقبال والسنترال).","التعامل مع المكالمات المزعجة أو الشكاوى بهدوء وتحويلها للجهة المختصة.","الالتزام ببروتوكولات سرية المعلومات وحماية بيانات المتصلين.","تتبع وتسجيل المكالمات الدولية أو الخاصة لأغراض الفوترة والمراجعة.","العمل تحت الضغط خلال أوقات الذروة لضمان عدم تأخر الرد على المتصلين."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (175, 'فني مواقع إلكترونية', '["متابعة أداء الموقع الإلكتروني والتأكد من سرعة تحميل الصفحات.","تحديث محتوى الموقع من نصوص وصور وفيديوهات بشكل دوري.","إجراء عمليات الصيانة الدورية واكتشاف وإصلاح الأخطاء البرمجية (Bugs).","أخذ نسخ احتياطية (Backups) لقواعد البيانات وملفات الموقع بانتظام.","مراقبة استضافة الموقع (Hosting) والتواصل مع الدعم الفني لمزود الخدمة عند انقطاع الخدمة.","ضمان توافق الموقع مع مختلف الأجهزة المحمولة والمتصفحات (Responsiveness).","تطبيق تحديثات الأمان لحماية الموقع من الاختراقات والبرمجيات الخبيثة.","إدارة حسابات المستخدمين والصلاحيات على نظام إدارة المحتوى.","تحسين بنية الموقع لمحركات البحث وإصلاح الروابط المعطلة.","إضافة وتفعيل الإضافات (Plugins) اللازمة لتحسين وظائف الموقع.","متابعة تحليلات الموقع (مثل Google Analytics) وتقديم تقارير بسيطة عن الزيارات.","تقديم الدعم الفني للموظفين فيما يخص استخدام البريد الإلكتروني المرتبط بالنطاق."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (176, 'مصحح لغوي', '["قراءة النصوص المكتوبة بدقة لاكتشاف الأخطاء الإملائية والنحوية والصرفية.","تصحيح أخطاء علامات الترقيم وتنسيق الفقرات لضمان وضوح المعنى.","تحسين الصياغة اللغوية والأسلوب ليتناسب مع الجمهور المستهدف وطبيعة المحتوى.","التأكد من اتساق المصطلحات والأسماء المستخدمة داخل النص الواحد.","مراجعة النصوص المترجمة للتأكد من دقتها ومطابقتها للمعنى الأصلي دون ركاكة.","التحقق من صحة التنسيقات العامة (العناوين، الخطوط، المسافات) قبل النشر أو الطباعة.","الالتزام بالدليل الأسلوبي (Style Guide) المعتمد لدى المؤسسة.","التعاون مع الكُتّاب والمؤلفين لتقديم ملاحظات بناءة حول كتاباتهم.","مراجعة المحتوى الرقمي (مقالات، منشورات سوشيال ميديا) قبل نشره.","التأكد من خلو النصوص من أي التباس أو معانٍ مزدوجة قد تسيء للفهم.","الالتزام بالمواعيد النهائية لتسليم المواد المصححة.","تحديث المعرفة بقواعد اللغة العربية وتطوراتها وأساليب الكتابة الحديثة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (177, 'أخصائي إدارة قواعد بيانات', '["تصميم وإنشاء قواعد البيانات بما يتوافق مع احتياجات المنظمة وتطبيقاتها.","إدارة وتحديث أنظمة إدارة قواعد البيانات (مثل Oracle, SQL Server, MySQL).","مراقبة أداء قواعد البيانات وتحسين سرعة استرجاع البيانات (Performance Tuning).","تنفيذ سياسات النسخ الاحتياطي (Backups) وخطط استعادة البيانات (Recovery) في حالات الطوارئ.","إدارة صلاحيات الوصول للمستخدمين لضمان سرية وأمن البيانات.","تحديث وإصدار التصحيحات (Patches) والترقيات لبرامج قواعد البيانات.","استكشاف الأخطاء والمشاكل المتعلقة بقواعد البيانات وإصلاحها لتقليل وقت التوقف.","ترحيل البيانات (Data Migration) بين الأنظمة والخوادم المختلفة عند الحاجة.","ضمان توافر قواعد البيانات على مدار الساعة (High Availability).","توثيق هيكلية قواعد البيانات والعمليات المتعلقة بها للرجوع إليها.","العمل مع مطوري البرامج لكتابة استعلامات (Queries) فعالة ومثالية.","التخطيط المستقبلي لاحتياجات التخزين التوسعية لقواعد البيانات (Capacity Planning)."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (178, 'كاتب شكاوى', '["الاستماع بعناية للعملاء أو الشاكين لفهم تفاصيل المشكلة أو التظلم بوضوح.","صياغة الشكاوى أو التظلمات بلغة رسمية، واضحة، وموجزة تعبر عن جوهر المشكلة.","جمع الوثائق والأدلة الداعمة (عقود، فواتير، صور) وإرفاقها مع الشكوى.","توجيه الشكوى إلى الجهة المعنية المختصة (إدارية، قانونية، أو جهات حكومية).","التأكد من كتابة جميع البيانات الشخصية للشاكي بشكل صحيح لسهولة التواصل.","مراجعة القوانين واللوائح ذات الصلة لضمان استناد الشكوى لأسس نظامية قوية.","الاحتفاظ بسجل أرشيفي سري للشكاوى المقدمة وتواريخها.","متابعة حالة الشكاوى المرفوعة وإبلاغ الشاكي بأي تطورات أو ردود.","التعديل على صيغة الشكوى بناءً على متطلبات الجهة المستلمة إذا لزم الأمر.","تقديم النصح للشاكي حول أفضل الطرق والخطوات التصعيدية المتاحة.","صياغة رسائل الرد على الشكاوى (في حال العمل لدى الجهة المستقبلة للشكوى).","الحفاظ على سرية وخصوصية المعلومات الحساسة للعملاء والشاكين."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (179, 'تقنية شبكات الحاسب', '["تركيب وتكوين أجهزة الشبكات الأساسية مثل الموجهات (Routers) والمحولات (Switches).","صيانة وإصلاح أعطال الشبكات السلكية واللاسلكية لضمان استمرارية العمل.","تمديد كابلات الشبكة وتجهيز البنية التحتية لتقنية المعلومات في المكاتب.","مراقبة أداء الشبكة وتحديد أسباب البطء أو الانقطاع ومعالجتها.","تقديم الدعم الفني المباشر للمستخدمين فيما يخص مشاكل الاتصال بالإنترنت أو الشبكة الداخلية.","تثبيت وتحديث برامج تشغيل كروت الشبكة والبرمجيات المرتبطة بها.","إعداد وإدارة حسابات المستخدمين وصلاحيات الوصول على الشبكة.","تطبيق سياسات الأمان الأساسية لحماية الأجهزة والشبكة من الفيروسات والاختراقات.","أخذ نسخ احتياطية دورية لإعدادات أجهزة الشبكة للرجوع إليها عند الحاجة.","توثيق مخططات الشبكة (Network Topology) والمنافذ وتحديثها باستمرار.","متابعة استهلاك عرض النطاق الترددي (Bandwidth) وتوزيع السرعات.","التعاون مع مهندسي الشبكات لتنفيذ خطط التوسعة والتحديث للبنية التحتية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (180, 'مهندس صناعي', '["تحليل وتصميم أنظمة الإنتاج لتحسين الكفاءة وتقليل الهدر في الوقت والموارد.","تطوير إجراءات العمل القياسية لزيادة الإنتاجية وخفض التكاليف التشغيلية.","إجراء دراسات الوقت والحركة (Time and Motion Study) للعمال والآلات.","تخطيط ومراقبة جودة المنتجات والعمليات الصناعية لضمان المطابقة للمعايير.","تطبيق سياسات ومعايير السلامة والصحة المهنية في بيئة العمل والمصانع.","إدارة سلاسل الإمداد وتخطيط المخزون بفعالية لضمان توفر المواد الخام.","تخطيط مساحات المصانع وتوزيع المعدات لتحسين تدفق المواد وتقليل مسافات النقل.","استخدام برامج المحاكاة الهندسية لتحليل الأنظمة الإنتاجية قبل تنفيذها.","تقييم أداء الآلات والمعدات واقتراح جداول الصيانة الوقائية الفعالة.","إعداد تقارير الأداء وتحليل البيانات وتقديم توصيات استراتيجية للإدارة العليا.","الإشراف على تدريب العمال والموظفين على طرق العمل والتقنيات الجديدة.","دمج التكنولوجيا الحديثة والأتمتة (Automation) في خطوط الإنتاج لرفع الكفاءة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (181, 'هندسه ميكانيكيه', '["تصميم وتطوير الآلات والمعدات الميكانيكية باستخدام برامج التصميم (مثل AutoCAD, SolidWorks).","الإشراف على عمليات تصنيع وتجميع وتركيب المكونات الميكانيكية في المواقع.","إجراء اختبارات الأداء للأنظمة الميكانيكية لضمان جودتها وكفاءتها التشغيلية.","تحليل أسباب الأعطال الميكانيكية المعقدة ووضع حلول هندسية جذرية لها.","تصميم والإشراف على تنفيذ أنظمة التدفئة والتهوية وتكييف الهواء (HVAC).","تخطيط وجدولة أعمال الصيانة الوقائية والتصحيحية للآلات والمعدات الثقيلة.","إعداد المواصفات الفنية وجداول الكميات لقطع الغيار والمواد الخام المطلوبة.","حساب الأحمال والضغوط وتحليل الإجهاد للمواد المستخدمة لضمان سلامة التصميم.","ضمان التزام المشاريع الميكانيكية بمعايير الجودة والسلامة الهندسية المعتمدة.","التعاون مع المهندسين الكهربائيين لدمج الأنظمة الكهروميكانيكية (MEP) بنجاح.","إدارة مشاريع التركيبات الميكانيكية ومتابعة المقاولين والموردين.","كتابة التقارير الفنية وتوثيق تصاميم ودلائل تشغيل وصيانة الآلات."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (182, 'مهندس كهرباء', '["تصميم المخططات والدوائر الكهربائية للمباني والمنشآت الصناعية والتجارية.","الإشراف على تمديد الكابلات وتركيب اللوحات الكهربائية الرئيسية والفرعية.","تصميم وصيانة أنظمة الإنارة الداخلية والخارجية وشبكات القوى الكهربائية.","إجراء الفحوصات والاختبارات للأجهزة والتمديدات الكهربائية للتأكد من سلامتها.","برمجة وصيانة أجهزة التحكم المنطقي المبرمج (PLC) في خطوط الإنتاج الصناعي.","تحليل وحل مشاكل انقطاع التيار، أو التذبذب في الجهد، أو الأعطال الكهربائية.","إعداد جداول الكميات والمواصفات الفنية للمناقصات والمشاريع الكهربائية.","تطبيق الأكواد الكهربائية المحلية والدولية لضمان أعلى معايير الأمان.","دراسة الأحمال الكهربائية وتحسين معامل القدرة لتقليل استهلاك الطاقة.","الإشراف على تركيب وصيانة المولدات الاحتياطية والمحولات الكهربائية.","التعاون مع المهندسين المدنيين والمعماريين لتنسيق مسارات الكابلات والخدمات.","إعداد خطط الطوارئ للتعامل مع المخاطر الكهربائية وتصميم أنظمة إنذار الحريق."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (183, 'هندسه شبكات تقنيه', '["تصميم البنية التحتية المتقدمة للشبكات المحلية (LAN) والواسعة (WAN).","تكوين وإدارة أجهزة التوجيه (Routers) والمحولات المتقدمة والجدران النارية (Firewalls).","تحليل حزم البيانات (Packet Analysis) لاكتشاف وحل مشاكل الشبكة المعقدة.","تصميم وتنفيذ بروتوكولات التوجيه المتقدمة (مثل OSPF, BGP) بكفاءة عالية.","تخطيط وتنفيذ وإدارة حلول الشبكات اللاسلكية (WLAN) للمؤسسات الكبرى.","تأمين بيئة الشبكة وتطبيق سياسات التشفير وحماية البيانات من التهديدات السيبرانية.","إدارة شبكات مراكز البيانات (Data Centers) السحابية والمحلية.","توفير حلول التكرار (Redundancy) لضمان استمرارية عمل الشبكة دون توقف.","مراقبة وضمان جودة الخدمة (QoS) لضمان أداء التطبيقات الحساسة مثل الصوت والفيديو.","تصميم وتنفيذ الشبكات الافتراضية الخاصة (VPNs) لربط الفروع وعمل الموظفين عن بُعد.","تقييم وإدخال تقنيات الشبكات الحديثة مثل الشبكات المعرفة بالبرمجيات (SDN).","قيادة الفرق الفنية في مشاريع دمج أو تحديث البنية التحتية للشبكات."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (184, 'هندسه مدنيه', '["تصميم الهياكل الخرسانية والمعدنية للمباني، الجسور، والمنشآت المختلفة.","إعداد المخططات الهندسية الإنشائية باستخدام برامج مثل (AutoCAD, Revit, STAAD).","حساب الكميات والتكاليف التقديرية لمواد البناء المطلوبة للمشروع.","الإشراف الميداني اليومي على مواقع البناء لضمان مطابقة التنفيذ للمواصفات والمخططات.","اختبار جودة مواد البناء (مثل الخرسانة، الحديد، التربة) في المعامل المعتمدة.","إدارة فرق العمل من مقاولين وعمال وتوجيههم وتوزيع المهام في الموقع.","تخطيط وجدولة مراحل تنفيذ المشروع لضمان التسليم في الوقت والميزانية المحددين.","مراجعة وتدقيق المخططات الإنشائية واعتمادها من الجهات الحكومية والمختصة.","تحليل وتقييم تربة الموقع وتصميم الأساسات المناسبة التي تتحمل الأحمال.","تطبيق إجراءات الأمن والسلامة الصارمة في مواقع العمل لحماية العمال والممتلكات.","حل المشاكل الهندسية الطارئة أو التعديلات التي قد تظهر أثناء مراحل التنفيذ.","إعداد المستخلصات المالية للمقاولين وتقارير الإنجاز الدورية لإدارة المشروع."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (185, 'مهندس تقنية شبكات', '["تخطيط ونشر البنية التحتية لتقنية المعلومات والأنظمة المتصلة بالشبكة.","دمج الأنظمة والخوادم الجديدة مع شبكة المؤسسة بشكل آمن وفعال.","إعداد وإدارة خوادم الشبكات الأساسية (مثل DNS, DHCP, Active Directory).","تحديث أنظمة تشغيل أجهزة الشبكات وتطبيق التصحيحات الأمنية (Patch Management).","التواصل مع مزودي خدمات الإنترنت (ISPs) لمتابعة جودة الخطوط وحل أعطال الربط.","استخدام أنظمة المراقبة (مثل SolarWinds أو PRTG) لتحليل أداء الشبكة استباقياً.","تنفيذ وتحديث بروتوكولات الأمان وأنظمة كشف ومنع التطفل (IPS/IDS).","تقديم المستوى الثاني والثالث من الدعم الفني (Tier 2/3 Support) للمشاكل المستعصية.","إدارة ترحيل الخدمات والشبكات المحلية إلى البيئات السحابية (Cloud Networking).","إعداد وتحديث وثائق وإجراءات التعافي من الكوارث (Disaster Recovery) للشبكة.","إدارة عناوين الـ IP (IPAM) وتوزيعها بشكل استراتيجي يمنع التعارض.","تدريب وتوجيه الكوادر الفنية المبتدئة على أساسيات وأفضل ممارسات تقنية الشبكات."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (186, 'بائع مواد انشائية', '["استقبال العملاء (مقاولين، مهندسين، أو أفراد) وفهم احتياجاتهم من مواد البناء.","تقديم المشورة الفنية وشرح خصائص المواد المختلفة (الأسمنت، الحديد، الطوب، العوازل، إلخ) ومساعدة العميل في اختيار الأنسب.","إعداد عروض أسعار دقيقة للكميات المطلوبة وإصدار الفواتير ومتابعة عمليات الدفع.","التفاوض على الأسعار مع المقاولين وشركات البناء وإغلاق الصفقات لتحقيق أهداف المبيعات.","المتابعة الدورية لمستويات المخزون في المستودع ورفع طلبات التوريد للمواد التي توشك على النفاد.","ترتيب وعرض عينات المنتجات داخل المعرض بشكل جذاب يسهل على العميل رؤيتها وفحصها.","التنسيق مع قسم الحركة أو السائقين لضمان توصيل المواد الإنشائية إلى مواقع العمل في المواعيد المحددة.","تأسيس والحفاظ على علاقات عمل طويلة الأمد مع كبار العملاء والمقاولين لضمان استمرارية التعامل.","التعامل مع شكاوى العملاء بمهنية، وإدارة عمليات استرجاع أو استبدال المواد التالفة أو غير المطابقة.","مراقبة أسعار المنافسين والتغيرات في أسواق مواد البناء وإبلاغ الإدارة بأي تطورات.","كتابة تقارير يومية أو أسبوعية بحجم المبيعات والمواد الأكثر أو الأقل طلباً ورفعها للإدارة.","الفحص الظاهري للمواد عند استلامها من الموردين وقبل تسليمها للعميل لضمان سلامتها وجودتها."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (187, 'اخصائي تقييم ثغرات', '["إجراء فحوصات دورية للأنظمة والشبكات لاكتشاف الثغرات الأمنية.","تحليل نقاط الضعف في التطبيقات والبنية التحتية لتكنولوجيا المعلومات.","استخدام أدوات فحص الثغرات الآلية واليدوية لتقييم مستوى الأمان.","إعداد تقارير مفصلة توضح الثغرات المكتشفة ومستوى خطورتها.","تقديم توصيات وحلول تقنية لمعالجة الثغرات وإغلاقها.","التعاون مع فريق تطوير البرمجيات لضمان تطبيق معايير الأمان البرمجية.","متابعة أحدث التهديدات الأمنية وأساليب الاختراق الحديثة.","إجراء اختبارات الاختراق (Penetration Testing) عند الحاجة لمحاكاة الهجمات.","التحقق من فعالية التحديثات والترقيعات الأمنية (Patches) بعد تطبيقها.","ضمان توافق الأنظمة مع سياسات ومعايير الأمان المحلية والدولية.","توعية وتدريب الموظفين حول ممارسات الأمان لتجنب الهندسة الاجتماعية.","المشاركة في وضع خطط الاستجابة للحوادث الأمنية والتعافي من الكوارث."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (188, 'مندوب مشترات', '["البحث عن موردين جدد في السوق المحلي للحصول على أفضل عروض الأسعار.","استلام طلبات الشراء من الأقسام المختلفة ومراجعتها.","التواصل المستمر مع الموردين لمتابعة أوامر التوريد.","زيارة أسواق الجملة والموردين لفحص البضائع قبل الشراء.","التفاوض المبدئي على الأسعار وشروط الدفع والتوصيل.","استلام وفحص البضائع الموردة والتأكد من مطابقتها للمواصفات المطلوبة.","حل أي مشاكل تتعلق بنقص الكميات أو تلف المواد أثناء النقل.","إعداد تقارير دورية عن حالة الطلبات والمشتريات المعلقة.","تسليم الفواتير والمستندات الخاصة بالمشتريات للإدارة المالية.","الحفاظ على علاقات جيدة ومستدامة مع الموردين المعتمدين.","تحديث سجلات المشتريات والأسعار بشكل يومي.","تنسيق عمليات نقل البضائع من مستودعات الموردين إلى مستودعات الشركة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (189, 'أخصائى مشتربات', '["تحليل عروض الأسعار المقدمة من الموردين والمفاضلة بينها بدقة.","إعداد وإصدار أوامر الشراء (Purchase Orders) عبر نظام تخطيط موارد المؤسسة (ERP).","التفاوض على العقود طويلة الأجل مع الموردين لضمان استمرارية التوريد بأفضل الأسعار.","تقييم أداء الموردين بشكل دوري بناءً على الجودة، وسرعة التوصيل، والالتزام.","متابعة الشحنات الدولية والمحلية وتنسيق عمليات التخليص الجمركي إن وجدت.","دراسة اتجاهات السوق وتحليل التغيرات في أسعار المواد الخام.","مراجعة العقود والاتفاقيات مع الإدارة القانونية قبل توقيعها.","التنسيق مع إدارة المخازن لتحديد مستويات المخزون (Reorder Point) وتجنب النقص.","معالجة وحل النزاعات المعقدة مع الموردين بشأن الجودة أو الفواتير.","إعداد تقارير تحليلية حول حجم الإنفاق وفرص توفير التكاليف.","توثيق وحفظ جميع سجلات المشتريات، والعقود، والمراسلات الرسمية.","تطبيق سياسات وإجراءات المشتريات المعتمدة داخل المؤسسة."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (190, 'مدير مشتريات', '["وضع وتطوير الاستراتيجية العامة للمشتريات بما يتماشى مع أهداف الشركة.","اعتماد أوامر الشراء والعقود ذات القيم المالية العالية.","الإشراف على فريق المشتريات وتوجيههم وتقييم أدائهم بشكل دوري.","إعداد ومراقبة الميزانية السنوية لقسم المشتريات والتحكم في النفقات.","بناء تحالفات وشراكات استراتيجية مع الموردين الرئيسيين والموزعين المعتمدين.","تطوير سياسات وإجراءات الشراء لضمان الشفافية والنزاهة والامتثال.","إدارة المخاطر المتعلقة بسلاسل الإمداد ووضع خطط بديلة للطوارئ.","تمثيل الشركة في المعارض التجارية والمؤتمرات للبحث عن مصادر توريد جديدة.","مراجعة تقارير الإنفاق وتقديم توصيات للإدارة العليا لتقليل التكاليف وزيادة الربحية.","حل المشكلات التصعيدية التي لا يمكن لفريق المشتريات التعامل معها.","الموافقة على إضافة موردين جدد لقائمة الموردين المعتمدين.","ضمان تكامل عمليات المشتريات مع الأقسام الأخرى كالمالية والإنتاج والمخازن."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (191, 'مندوب مشتربات', '["استلام ومراجعة طلبات الشراء اليومية من مشرفي الأقسام.","النزول الميداني للأسواق لجمع عروض الأسعار للمواد المستعجلة.","مقارنة أسعار السلع المتاحة واختيار الأنسب من حيث الجودة والسعر.","شراء وتوفير المستلزمات الإدارية والمكتبية بشكل دوري.","متابعة وتيرة التوريد لضمان عدم تأخر المشاريع أو خطوط الإنتاج.","إرجاع أو استبدال المواد غير المطابقة للمواصفات بالتنسيق مع المورد.","الاحتفاظ بالفواتير والسندات الورقية وتسويتها مع قسم الحسابات كعهد مالية.","ترتيب أولوية المشتريات بناءً على مدى أهميتها واستعجالها.","تقديم تحديثات مستمرة للمشرف المباشر حول سير عمليات الشراء.","نقل الطلبيات الصغيرة والمتوسطة شخصياً باستخدام مركبات الشركة.","بناء قاعدة بيانات مبسطة بأسماء وعناوين الموردين المحليين.","الالتزام بالميزانية المحددة لكل طلبية دون تجاوز."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (192, 'مراقب الجودة', '["فحص المواد الخام المستلمة والتأكد من مطابقتها للمواصفات والمعايير المطلوبة.","إجراء اختبارات وفحوصات دورية على المنتجات أثناء مراحل الإنتاج المختلفة.","عزل وإيقاف المنتجات المعيبة أو غير المطابقة لمنع وصولها للعملاء.","توثيق وتسجيل نتائج الفحص والاختبار في نماذج وتقارير الجودة المعتمدة.","معايرة أدوات ومعدات القياس بانتظام لضمان دقة القراءات.","مراقبة بيئة العمل (النظافة، الحرارة، الرطوبة) لضمان توافقها مع معايير الجودة.","التحقيق في أسباب العيوب (Root Cause Analysis) وتقديم اقتراحات لتفاديها.","تدريب وتوعية العمال على معايير الجودة وإجراءات التشغيل القياسية (SOPs).","مراجعة وتدقيق بطاقات التعبئة والتغليف والتواريخ المطبوعة على المنتجات.","متابعة تنفيذ الإجراءات التصحيحية والوقائية (CAPA) مع قسم الإنتاج.","المشاركة في عمليات التدقيق الداخلي لنظام إدارة الجودة.","ضمان التزام المصنع بتعليمات السلامة والصحة المهنية ومقاييس ISO."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (193, 'بائع اثاث', '["الترحيب بالعملاء فور دخولهم المعرض وتقديم المساعدة بأسلوب لبق.","فهم احتياجات العميل وميزانيته واقتراح قطع الأثاث المناسبة له.","شرح تفاصيل ومواصفات الأثاث (نوع الخشب، الأقمشة، الأبعاد، الضمان).","مساعدة العملاء في تنسيق الألوان واختيار التصاميم التي تلائم مساحاتهم.","إعداد عروض الأسعار والفواتير ومتابعة عمليات الدفع والتقسيط إن وجدت.","ترتيب وتنسيق صالة العرض وإضافة اللمسات الديكورية لإبراز جمال الأثاث.","التفاوض المباشر مع العملاء لإغلاق الصفقات وتحقيق أهداف المبيعات الشهرية.","التنسيق مع إدارة المخازن للتأكد من توافر القطع المطلوبة قبل إتمام البيع.","متابعة مواعيد التسليم والتركيب مع قسم الحركة لضمان رضا العميل.","التواصل مع العملاء بعد البيع للتأكد من رضاهم وحل أي شكاوى محتملة.","تحديث معرفته بشكل مستمر بأحدث خطوط الموضة في الأثاث والديكور.","جرد البضائع الموجودة في صالة العرض والمشاركة في الجرد السنوي."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (194, 'مشرف إنتاج', '["تخطيط وتوزيع المهام اليومية على العمال والفنيين في خطوط الإنتاج.","متابعة سير العملية الإنتاجية لضمان تحقيق خطة الإنتاج اليومية والشهرية.","الإشراف المباشر على تشغيل الآلات والمعدات وضمان استخدامها بشكل صحيح.","تقليل نسبة الهالك أو الفاقد من المواد الخام إلى الحد الأدنى المسموح.","تطبيق معايير ولوائح السلامة والصحة المهنية لحماية العمال من إصابات العمل.","التنسيق المستمر مع قسم الصيانة للإبلاغ عن أي أعطال مفاجئة بالماكينات وإصلاحها.","مراقبة التزام العمال بمواعيد الحضور والانصراف وتقييم أدائهم الفني.","استلام المواد الخام من المخازن وتسليم المنتج النهائي لمخازن التام.","إعداد تقارير الوردية التي تشمل الكميات المنتجة، والأعطال، والهالك.","التعاون مع قسم الجودة لتصحيح أي أخطاء في المنتج أثناء عملية التصنيع.","تدريب العمال الجدد على خطوات العمل وتوجيههم باستمرار.","تحفيز فريق العمل وحل أي نزاعات أو مشاكل طارئة تحدث خلال الوردية."]', NOW(), NOW());
INSERT INTO job_titles (id, title, tasks, created_at, updated_at) VALUES (195, 'مساعد حسابات', '["إدخال البيانات المالية اليومية والفواتير على النظام المحاسبي بدقة.","مراجعة وتصنيف المستندات المالية (فواتير، إيصالات، سندات قبض وصرف).","إجراء التسويات البنكية الشهرية ومطابقتها مع دفاتر الشركة.","مساعدة المحاسبين في إعداد كشوف الرواتب والأجور للموظفين.","متابعة وتحصيل الحسابات المدينة (العملاء) وتسجيل المدفوعات الواردة.","مراجعة وتسجيل فواتير الموردين (الحسابات الدائنة) وتجهيز دفعاتها.","أرشفة وتنظيم الملفات والمستندات الورقية والإلكترونية لسهولة الرجوع إليها.","جرد وتسوية العهد المالية النثرية (Petty Cash) مع الموظفين والأقسام.","المساعدة في التجهيز لعمليات الإقفال الشهري والسنوي للحسابات.","مراجعة حسابات المخزون والمشاركة في عمليات الجرد الفعلي للمخازن.","إعداد تقارير مالية مبسطة بطلب من المدير المالي أو المحاسب الأول.","التأكد من الالتزام بالسياسات والإجراءات المالية المعتمدة داخل المؤسسة."]', NOW(), NOW());